-- ==========================================================================
__modules["Components/ColorPicker"] = function()
--[[
	ColorPicker
	  Section:AddColorPicker({
	      Title, Description, Flag, Default = Color3, Transparency = 0 (nil = no alpha bar),
	      Rainbow = false, RainbowSpeed = 0.2, Callback = function(color, transparency) end,
	  })
	  :Set(color, transparency?) | :Set({Color = Color3|"#hex", Transparency, Rainbow})
	  :Get() -> color, transparency    :SetRainbow(bool)
	Inline panel with HSV square, hue bar, alpha bar, hex input and rainbow toggle.
	Note: the HSV square's white/black overlays are mathematically derived
	(Color3.fromHSV) - they are part of the colour model, not theme colours.
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Element = Import("Components/Element")

local Create = Utility.Create
local RunService = Utility.Services.RunService

local ColorPicker = setmetatable({}, { __index = Element })
ColorPicker.__index = ColorPicker

-- HSV model constants (derived, not design colours)
local HSV_WHITE = Color3.fromHSV(0, 0, 1)
local HSV_BLACK = Color3.fromHSV(0, 0, 0)

local function hueSequence(): ColorSequence
	local keys = {}
	for i = 0, 6 do
		table.insert(keys, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6 % 1, 1, 1)))
	end
	return ColorSequence.new(keys)
end

------------------------------------------------------------------------------
-- Shared rainbow ticker (only runs while at least one picker uses rainbow)
------------------------------------------------------------------------------
local rainbowPickers: { [any]: boolean } = {}
local rainbowConnection: RBXScriptConnection? = nil
local lastRainbowTick = 0

local function updateRainbowTicker()
	local any = next(rainbowPickers) ~= nil
	if any and not rainbowConnection then
		rainbowConnection = RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now - lastRainbowTick < 1 / 30 then
				return
			end
			lastRainbowTick = now
			for picker in rainbowPickers do
				if picker.Destroyed then
					rainbowPickers[picker] = nil
				else
					local hue = (now * (picker.Options.RainbowSpeed or 0.2)) % 1
					picker:_ApplyHSV(hue, math.max(picker.S, 0.6), math.max(picker.V, 0.8), true)
				end
			end
		end)
	elseif not any and rainbowConnection then
		rainbowConnection:Disconnect()
		rainbowConnection = nil
	end
end

------------------------------------------------------------------------------
function ColorPicker.new(section: any, options: { [string]: any })
	local self = Element.new(section, options, "ColorPicker", ColorPicker)
	local o = self.Options
	local default: Color3 = if typeof(o.Default) == "Color3" then o.Default else (Utility.HexToColor(o.Default) or Theme.Values.Accent)
	self.Color = default
	self.H, self.S, self.V = default:ToHSV()
	self.HasAlpha = o.Transparency ~= nil or o.Alpha == true
	self.Transparency = math.clamp(tonumber(o.Transparency) or 0, 0, 1)
	self.Rainbow = false
	self.Opened = false

	self:_BuildRow({ ControlWidth = 64 })

	-- swatch
	local swatch = Create("TextButton", {
		Name = "Swatch",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.fromOffset(42, 24),
		Parent = self.Control,
	})
	Kit.Corner(swatch, 0.6)
	local swatchStroke = Kit.Stroke(swatch, "Border", {
		Always = true,
		Deps = { "Border", "Accent" },
		Compute = function(T)
			return if self.Opened then T.Accent else T.Border
		end,
	})
	table.insert(self._stateful, swatchStroke)
	self.Swatch = swatch
	Animations.AttachPress(swatch, swatch, 0.92)

	-- panel
	local panel = Create("Frame", {
		Name = "Panel",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		ClipsDescendants = true,
		Visible = false,
		LayoutOrder = 2,
		Parent = self.Stack,
	})
	self.Panel = panel
	local inner = Create("Frame", {
		Name = "Inner",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = panel,
	})
	Kit.Padding(inner, "Inner", 0)
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8), Parent = inner })
	self.Inner = inner

	-- SV + hue row
	local pickRow = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 130),
		LayoutOrder = 1,
		Parent = inner,
	})
	local sv = Create("Frame", {
		Name = "SV",
		Size = UDim2.new(1, -26, 1, 0),
		Parent = pickRow,
	})
	Kit.Corner(sv, 0.5)
	local sat = Create("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = HSV_WHITE, Parent = sv })
	Kit.Corner(sat, 0.5)
	Create("UIGradient", {
		Transparency = NumberSequence.new(0, 1),
		Parent = sat,
	})
	local val = Create("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = HSV_BLACK, ZIndex = 2, Parent = sv })
	Kit.Corner(val, 0.5)
	Create("UIGradient", {
		Rotation = 90,
		Transparency = NumberSequence.new(1, 0),
		Parent = val,
	})
	local svCursor = Create("Frame", {
		Name = "Cursor",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.fromOffset(12, 12),
		BackgroundTransparency = 1,
		ZIndex = 4,
		Parent = sv,
	})
	Kit.Corner(svCursor, "pill")
	local cursorStroke = Kit.Stroke(svCursor, "ToggleKnob", { Always = true })
	Kit.Bind(cursorStroke, "Thickness", { "BorderThickness" }, function()
		return 2
	end)
	local hue = Create("Frame", {
		Name = "Hue",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.fromScale(1, 0),
		Size = UDim2.new(0, 16, 1, 0),
		BackgroundColor3 = HSV_WHITE,
		Parent = pickRow,
	})
	Kit.Corner(hue, "pill")
	Create("UIGradient", { Rotation = 90, Color = hueSequence(), Parent = hue })
	local hueCursor = Create("Frame", {
		Name = "Cursor",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.new(1, 4, 0, 6),
		ZIndex = 3,
		Parent = hue,
	})
	Kit.Corner(hueCursor, "pill")
	Kit.Bind(hueCursor, "BackgroundColor3", "ToggleKnob")
	Kit.Stroke(hueCursor, "Border", { Always = true })
	self.SV, self.SVCursor, self.Hue, self.HueCursor = sv, svCursor, hue, hueCursor

	-- alpha bar
	if self.HasAlpha then
		local alpha = Create("Frame", {
			Name = "Alpha",
			Size = UDim2.new(1, -26, 0, 12),
			LayoutOrder = 2,
			Parent = inner,
		})
		Kit.Corner(alpha, "pill")
		Kit.Stroke(alpha, "Border", { Always = true })
		local alphaGradient = Create("UIGradient", { Transparency = NumberSequence.new(0, 1), Parent = alpha })
		local alphaCursor = Create("Frame", {
			Name = "Cursor",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0, 0.5),
			Size = UDim2.fromOffset(6, 16),
			ZIndex = 3,
			Parent = alpha,
		})
		Kit.Corner(alphaCursor, "pill")
		Kit.Bind(alphaCursor, "BackgroundColor3", "ToggleKnob")
		Kit.Stroke(alphaCursor, "Border", { Always = true })
		self.Alpha, self.AlphaCursor, self.AlphaGradient = alpha, alphaCursor, alphaGradient
	end

	-- hex + rainbow row
	local bottom = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 28),
		LayoutOrder = 3,
		Parent = inner,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 6),
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Parent = bottom,
	})
	local hexField = Create("Frame", { Size = UDim2.new(0.5, -3, 1, 0), LayoutOrder = 1, Parent = bottom })
	Kit.Panel(hexField, "Input", "Panel")
	Kit.Corner(hexField, 0.6)
	Kit.Stroke(hexField, "Border")
	local hexBox = Kit.TextBox({
		Name = "Hex",
		Position = UDim2.fromOffset(8, 0),
		Size = UDim2.new(1, -16, 1, 0),
		PlaceholderText = "#RRGGBB",
		Parent = hexField,
	}, "Mono")
	self.HexBox = hexBox

	local rainbowButton = Create("TextButton", { Size = UDim2.new(0.5, -3, 1, 0), LayoutOrder = 2, Parent = bottom })
	Kit.Corner(rainbowButton, 0.6)
	self:_Stateful(rainbowButton, "BackgroundColor3", { "Accent", "Input" }, function(T)
		return if self.Rainbow then T.Accent else T.Input
	end)
	self:_Stateful(rainbowButton, "BackgroundTransparency", { "Accent" }, function()
		return if self.Rainbow then 0.75 else 0
	end)
	local rainbowStroke = Kit.Stroke(rainbowButton, "Border", {
		Deps = { "Border", "Accent" },
		Compute = function(T)
			return if self.Rainbow then T.Accent else T.Border
		end,
	})
	table.insert(self._stateful, rainbowStroke)
	local rainbowLabel = Kit.Label({
		Size = UDim2.fromScale(1, 1),
		Text = "Rainbow",
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = rainbowButton,
	}, "Small", "Text")
	self:_Stateful(rainbowLabel, "TextColor3", { "Text", "Accent" }, function(T)
		return if self.Rainbow then T.Accent else T.Text
	end)
	Animations.AttachPress(rainbowButton, rainbowButton, 0.95)

	-- interactions -----------------------------------------------------------
	self.Maid:Give(swatch.MouseButton1Click:Connect(function()
		if self.Disabled then
			return
		end
		if self.Opened then
			self:Close()
		else
			self:Open()
		end
	end))

	local function svFrom(pos: Vector2)
		local p, s = sv.AbsolutePosition, sv.AbsoluteSize
		local x = math.clamp((pos.X - p.X) / math.max(s.X, 1), 0, 1)
		local y = math.clamp((pos.Y - p.Y) / math.max(s.Y, 1), 0, 1)
		self:SetRainbow(false)
		self:_ApplyHSV(self.H, x, 1 - y)
	end
	local function hueFrom(pos: Vector2)
		local p, s = hue.AbsolutePosition, hue.AbsoluteSize
		local y = math.clamp((pos.Y - p.Y) / math.max(s.Y, 1), 0, 0.999)
		self:SetRainbow(false)
		self:_ApplyHSV(y, self.S, self.V)
	end
	local svHit = Kit.Hitbox(sv, 5)
	local hueHit = Kit.Hitbox(hue, 5)
	self.Maid:Give(Input.Track(svHit, {
		Threshold = 0,
		MoveBeforeThreshold = true,
		LockScroll = true,
		Began = svFrom,
		Moved = svFrom,
	}))
	self.Maid:Give(Input.Track(hueHit, {
		Threshold = 0,
		MoveBeforeThreshold = true,
		LockScroll = true,
		Began = hueFrom,
		Moved = hueFrom,
	}))
	if self.Alpha then
		local alphaHit = Kit.Hitbox(self.Alpha, 5)
		alphaHit.Size = UDim2.new(1, 0, 1, 12)
		alphaHit.Position = UDim2.fromOffset(0, -6)
		local function alphaFrom(pos: Vector2)
			local p, s = self.Alpha.AbsolutePosition, self.Alpha.AbsoluteSize
			local x = math.clamp((pos.X - p.X) / math.max(s.X, 1), 0, 1)
			self:_SetTransparency(math.floor(x * 100 + 0.5) / 100)
		end
		self.Maid:Give(Input.Track(alphaHit, {
			Threshold = 0,
			MoveBeforeThreshold = true,
			LockScroll = true,
			Began = alphaFrom,
			Moved = alphaFrom,
		}))
	end
	self.Maid:Give(hexBox.FocusLost:Connect(function()
		local color = Utility.HexToColor(hexBox.Text)
		if color and not self.Disabled then
			self:SetRainbow(false)
			local h, s, v = color:ToHSV()
			self:_ApplyHSV(h, s, v)
		else
			self:_Render()
		end
	end))
	self.Maid:Give(rainbowButton.MouseButton1Click:Connect(function()
		if not self.Disabled then
			self:SetRainbow(not self.Rainbow)
		end
	end))

	if o.Rainbow then
		self:SetRainbow(true)
	end
	self:_Render()
	self:_Register()
	return self
end

------------------------------------------------------------------------------
function ColorPicker:_Render()
	local color = self.Color
	self.Swatch.BackgroundColor3 = color
	self.Swatch.BackgroundTransparency = self.Transparency * 0.85
	self.SV.BackgroundColor3 = Color3.fromHSV(self.H, 1, 1)
	self.SVCursor.Position = UDim2.fromScale(self.S, 1 - self.V)
	self.HueCursor.Position = UDim2.fromScale(0.5, self.H)
	if self.Alpha then
		self.Alpha.BackgroundColor3 = color
		self.AlphaCursor.Position = UDim2.fromScale(self.Transparency, 0.5)
	end
	if not self.HexBox:IsFocused() then
		self.HexBox.Text = Utility.ColorToHex(color)
	end
end

function ColorPicker:_Emit(silent: boolean?, fromConfig: boolean?)
	if silent then
		self.Changed:Fire(self.Color, self.Transparency)
		return
	end
	self.Changed:Fire(self.Color, self.Transparency)
	if self.Flag then
		Import("Config").FlagChanged:Fire(self.Flag, self.Color)
	end
	if fromConfig and self.NoCallbackOnLoad then
		return
	end
	Utility.SafeCallback(self.Callback, self.Color, self.Transparency)
end

function ColorPicker:_ApplyHSV(h: number, s: number, v: number, fromRainbow: boolean?)
	self.H, self.S, self.V = h, s, v
	local color = Color3.fromHSV(h, s, v)
	if not fromRainbow and color == self.Color then
		self:_Render()
		return
	end
	self.Color = color
	self:_Render()
	self:_Emit()
end

function ColorPicker:_SetTransparency(value: number)
	local t = math.clamp(value, 0, 1)
	if t == self.Transparency then
		return
	end
	self.Transparency = t
	self:_Render()
	self:_Emit()
end

function ColorPicker:SetRainbow(enabled: boolean)
	if self.Rainbow == enabled then
		return
	end
	self.Rainbow = enabled
	rainbowPickers[self] = if enabled then true else nil
	updateRainbowTicker()
	for _, inst in self._stateful do
		Kit.Refresh(inst)
	end
end

function ColorPicker:Open()
	if self.Opened then
		return
	end
	self.Opened = true
	self.Panel.Visible = true
	self:_SetState("Focus", true)
	task.defer(function()
		Animations.Tween(self.Panel, { Size = UDim2.new(1, 0, 0, self.Inner.AbsoluteSize.Y) }, 0.28)
	end)
end

function ColorPicker:Close()
	if not self.Opened then
		return
	end
	self.Opened = false
	self:_SetState("Focus", false)
	local tween = Animations.Tween(self.Panel, { Size = UDim2.new(1, 0, 0, 0) }, 0.22)
	local function hide()
		if not self.Opened then
			self.Panel.Visible = false
		end
	end
	if tween then
		tween.Completed:Once(hide)
	else
		hide()
	end
end

-- :Set(Color3, transparency?) or :Set({Color, Transparency, Rainbow})
function ColorPicker:Set(value: any, transparency: any?, fromConfig: boolean?)
	local color: Color3? = nil
	local t: number? = if type(transparency) == "number" then transparency else nil
	local rainbow: boolean? = nil
	if typeof(value) == "Color3" then
		color = value
	elseif type(value) == "string" then
		color = Utility.HexToColor(value)
	elseif type(value) == "table" then
		color = if typeof(value.Color) == "Color3" then value.Color else Utility.HexToColor(value.Color)
		t = tonumber(value.Transparency)
		if type(value.Rainbow) == "boolean" then
			rainbow = value.Rainbow
		end
	end
	if color then
		self.Color = color
		self.H, self.S, self.V = color:ToHSV()
	end
	if t then
		self.Transparency = math.clamp(t, 0, 1)
	end
	if rainbow ~= nil then
		self:SetRainbow(rainbow)
	end
	self:_Render()
	self:_Emit(transparency == true, fromConfig)
end

-- silent update used by the Appearance tab
function ColorPicker:SetSilent(color: Color3, transparency: number?)
	self.Color = color
	self.H, self.S, self.V = color:ToHSV()
	if transparency then
		self.Transparency = transparency
	end
	self:_Render()
end

function ColorPicker:Get(): (Color3, number)
	return self.Color, self.Transparency
end

function ColorPicker:Serialize(): any
	return { Color = Utility.ColorToHex(self.Color), Transparency = self.Transparency, Rainbow = self.Rainbow }
end

function ColorPicker:Deserialize(value: any)
	if type(value) == "table" or type(value) == "string" then
		self:Set(value, nil, true)
	end
end

function ColorPicker:Destroy()
	rainbowPickers[self] = nil
	updateRainbowTicker()
	Element.Destroy(self)
end

return ColorPicker
end

-- ==========================================================================
-- Components/Dialog
-- ==========================================================================
__modules["Components/Dialog"] = function()
--[[
	Dialog / Modal
	  local d = Window:Dialog({
	      Title = "Delete config?", Content = "This cannot be undone.", Icon = "warning",
	      Input = { Placeholder = "Name", Default = "" },          -- optional prompt field
	      Buttons = {
	          { Title = "Cancel" },
	          { Title = "Delete", Style = "Danger", Callback = function(inputText) end },
	      },
	  })
	  d:Close()
	  Window:Confirm(title, content [, confirmText, style]) -> boolean   (yields)
	  Window:Prompt(title, content, placeholder, default) -> string?    (yields)
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Gui = Import("Gui")
local Constants = Import("Constants")

local Create = Utility.Create

local Dialog = {}
Dialog.__index = Dialog

function Dialog.new(window: any?, options: { [string]: any })
	local self = setmetatable({}, Dialog)
	local o = options or {}
	self.Closed = false
	local layer: GuiObject = if window and window.DialogLayer then window.DialogLayer else Gui.Layer("Popups")
	layer.Visible = true

	local root = Create("Frame", {
		Name = "Dialog",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 10,
		Parent = layer,
	})
	self.Root = root

	local backdrop = Create("TextButton", {
		Name = "Backdrop",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 10,
		Parent = root,
	})
	Kit.Bind(backdrop, "BackgroundColor3", "Overlay")
	Animations.Tween(backdrop, { BackgroundTransparency = Theme:Alpha("Overlay", "Free") }, 0.25)
	self.Backdrop = backdrop

	local card = Create("Frame", {
		Name = "Card",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(0.9, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 11,
		Parent = root,
	})
	Create("UISizeConstraint", { MaxSize = Vector2.new(o.Width or 380, math.huge), Parent = card })
	Kit.Panel(card, "Card", "Free")
	Kit.Corner(card, 1.2)
	Kit.Stroke(card, "Border", { Always = true })
	Kit.Padding(card, 18)
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10), Parent = card })
	local scale = Create("UIScale", { Scale = 0.85, Parent = card })
	Animations.Tween(scale, { Scale = 1 }, 0.35, Enum.EasingStyle.Back)
	self.Card, self.Scale = card, scale

	local header = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 24),
		LayoutOrder = 1,
		ZIndex = 11,
		Parent = card,
	})
	local offset = 0
	if o.Icon then
		Kit.Icon(o.Icon, { Size = UDim2.fromOffset(20, 20), Position = UDim2.fromOffset(0, 2), ZIndex = 11, Parent = header }, o.IconColor or "Accent")
		offset = 28
	end
	Kit.Label({
		Text = tostring(o.Title or "Dialog"),
		Position = UDim2.fromOffset(offset, 0),
		Size = UDim2.new(1, -offset, 1, 0),
		ZIndex = 11,
		Parent = header,
	}, "Title", "Text")

	if o.Content then
		Kit.Label({
			Text = tostring(o.Content),
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			TextTruncate = Enum.TextTruncate.None,
			RichText = o.RichText == true,
			LayoutOrder = 2,
			ZIndex = 11,
			Parent = card,
		}, "Body", "TextMuted")
	end

	if o.Input then
		local field = Create("Frame", { Size = UDim2.new(1, 0, 0, 34), LayoutOrder = 3, ZIndex = 11, Parent = card })
		Kit.Panel(field, "Input", "Free")
		Kit.Corner(field, 0.6)
		Kit.Stroke(field, "Accent", { Always = true })
		self.Input = Kit.TextBox({
			Position = UDim2.fromOffset(10, 0),
			Size = UDim2.new(1, -20, 1, 0),
			PlaceholderText = o.Input.Placeholder or "",
			Text = o.Input.Default or "",
			ZIndex = 11,
			Parent = field,
		}, "Body")
		task.defer(function()
			if self.Input and not self.Closed then
				self.Input:CaptureFocus()
			end
		end)
	end

	local buttons = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 34),
		LayoutOrder = 4,
		ZIndex = 11,
		Parent = card,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
		Parent = buttons,
	})
	local list = o.Buttons or { { Title = Constants.Strings.Ok, Style = "Primary" } }
	for index, data in list do
		local style = data.Style or "Default"
		local button = Create("TextButton", {
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = index,
			ClipsDescendants = true,
			ZIndex = 11,
			Parent = buttons,
		})
		Create("UISizeConstraint", { MinSize = Vector2.new(84, 0), Parent = button })
		Create("UIPadding", { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14), Parent = button })
		Kit.Corner(button, 0.7)
		local textKey = "Text"
		if style == "Primary" then
			Kit.AccentFill(button, "Button")
			textKey = "AccentText"
		elseif style == "Danger" then
			Kit.Panel(button, "Danger", "Free")
			textKey = "AccentText"
		else
			Kit.Panel(button, "Surface", "Free")
			Kit.Stroke(button, "Border")
		end
		local label = Kit.Label({
			Text = tostring(data.Title or "OK"),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 11,
			Parent = button,
		}, "Heading", textKey)
		label.Name = "Label"
		Animations.AttachPress(button, button, 0.95)
		button.MouseButton1Click:Connect(function()
			Animations.Ripple(button, nil, textKey)
			local text = if self.Input then self.Input.Text else nil
			if data.Callback then
				Utility.SafeCallback(data.Callback, text)
			end
			if data.Close ~= false then
				self:Close()
			end
		end)
	end

	if o.Dismissible ~= false then
		backdrop.MouseButton1Click:Connect(function()
			if o.OnDismiss then
				Utility.SafeCallback(o.OnDismiss)
			end
			self:Close()
		end)
	end
	return self
end

function Dialog:Close()
	if self.Closed then
		return
	end
	self.Closed = true
	Animations.Tween(self.Backdrop, { BackgroundTransparency = 1 }, 0.2)
	local tween = Animations.Tween(self.Scale, { Scale = 0.85 }, 0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
	local root = self.Root
	local function done()
		local layer = root.Parent
		root:Destroy()
		if layer and #layer:GetChildren() == 0 and layer:IsA("GuiObject") and layer.Name == "DialogLayer" then
			layer.Visible = false
		end
	end
	if tween then
		self.Card.Visible = true
		task.delay(0.2 / Animations.Speed(), done)
	else
		done()
	end
end
Dialog.Destroy = Dialog.Close

-- Yields until the user decides. Returns true when confirmed.
function Dialog.Confirm(window: any?, title: string, content: string?, confirmText: string?, style: string?): boolean
	local thread = coroutine.running()
	local resolved = false
	local function resolve(value: boolean)
		if resolved then
			return
		end
		resolved = true
		task.spawn(thread, value)
	end
	Dialog.new(window, {
		Title = title,
		Content = content,
		Icon = if style == "Danger" then "warning" else "info",
		IconColor = if style == "Danger" then "Danger" else "Accent",
		OnDismiss = function()
			resolve(false)
		end,
		Buttons = {
			{
				Title = Constants.Strings.Cancel,
				Callback = function()
					resolve(false)
				end,
			},
			{
				Title = confirmText or Constants.Strings.Confirm,
				Style = style or "Primary",
				Callback = function()
					resolve(true)
				end,
			},
		},
	})
	return coroutine.yield()
end

function Dialog.Prompt(window: any?, title: string, content: string?, placeholder: string?, default: string?): string?
	local thread = coroutine.running()
	local resolved = false
	local function resolve(value: string?)
		if resolved then
			return
		end
		resolved = true
		task.spawn(thread, value)
	end
	Dialog.new(window, {
		Title = title,
		Content = content,
		Input = { Placeholder = placeholder, Default = default },
		OnDismiss = function()
			resolve(nil)
		end,
		Buttons = {
			{
				Title = Constants.Strings.Cancel,
				Callback = function()
					resolve(nil)
				end,
			},
			{
				Title = Constants.Strings.Ok,
				Style = "Primary",
				Callback = function(text)
					resolve(text)
				end,
			},
		},
	})
	return coroutine.yield()
end

return Dialog
end

-- ==========================================================================
-- Components/Display
-- ==========================================================================
__modules["Components/Display"] = function()
--[[
	Display elements: Label, Paragraph, Divider, Tags (chips), StatusCard

	  Section:AddLabel({ Text, Color = "Text", Role = "Body", Icon })      -> :Set(text)
	  Section:AddParagraph({ Title, Content })                             -> :Set({Title, Content})
	  Section:AddDivider({ Text = nil })
	  Section:AddTags({ Tags = { "Live", {Text = "Beta", Color = "Warning", Icon = "bolt"} } }) -> :SetTags(list)
	  Section:AddStatusCard({ Title, Subtitle, Icon, Status = "Success" }) -> :SetStatus(text, colorKey)
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Element = Import("Components/Element")
local Tooltip = Import("Components/Tooltip")

local Create = Utility.Create

local Display = {}

local function plainRoot(self: any, name: string): Frame
	local section = self.Section
	local root = Create("Frame", {
		Name = name,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = section:_NextOrder(),
	})
	self.Root = root
	self.Maid:Give(root)
	self.Maid:Give(Tooltip.Attach(root, function()
		return self.TooltipText
	end))
	root.Parent = section.Container
	return root
end

------------------------------------------------------------------------------
-- Label
------------------------------------------------------------------------------
local Label = setmetatable({}, { __index = Element })
Label.__index = Label
Display.Label = Label

function Label.new(section: any, options: any)
	local opts = if type(options) == "string" then { Text = options } else options or {}
	local self = Element.new(section, opts, "Label", Label)
	local root = plainRoot(self, "Label")
	self.Value = tostring(opts.Text or opts.Title or "")
	local offset = 0
	if opts.Icon then
		Kit.Icon(opts.Icon, { Size = UDim2.fromOffset(15, 15), Position = UDim2.fromOffset(2, 2), Parent = root }, opts.Color or "TextMuted")
		offset = 22
	end
	self.Label = Kit.Label({
		Text = self.Value,
		Position = UDim2.fromOffset(offset, 0),
		Size = UDim2.new(1, -offset, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		RichText = opts.RichText == true,
		TextTruncate = Enum.TextTruncate.None,
		Parent = root,
	}, opts.Role or "Body", opts.Color or "Text")
	return self
end

function Label:Set(text: any)
	self.Value = tostring(text)
	self.Label.Text = self.Value
end

function Label:SetColor(colorKey: string)
	Kit.Bind(self.Label, "TextColor3", colorKey)
end

------------------------------------------------------------------------------
-- Paragraph
------------------------------------------------------------------------------
local Paragraph = setmetatable({}, { __index = Element })
Paragraph.__index = Paragraph
Display.Paragraph = Paragraph

function Paragraph.new(section: any, options: any)
	local self = Element.new(section, options, "Paragraph", Paragraph)
	local o = self.Options
	local root = plainRoot(self, "Paragraph")
	Kit.Panel(root, "Surface", "Panel")
	Kit.Corner(root, 0.7)
	Kit.Stroke(root, "Border")
	Kit.Padding(root, "Inner")
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), Parent = root })
	self.TitleLabel = Kit.Label({
		Text = tostring(o.Title or ""),
		Visible = o.Title ~= nil,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		LayoutOrder = 1,
		Parent = root,
	}, "Heading", "Text")
	self.ContentLabel = Kit.Label({
		Text = tostring(o.Content or ""),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		RichText = o.RichText == true,
		TextTruncate = Enum.TextTruncate.None,
		TextYAlignment = Enum.TextYAlignment.Top,
		LayoutOrder = 2,
		Parent = root,
	}, "Small", "TextMuted")
	return self
end

function Paragraph:Set(value: any)
	if type(value) == "table" then
		if value.Title ~= nil then
			self.TitleLabel.Text = tostring(value.Title)
			self.TitleLabel.Visible = true
		end
		if value.Content ~= nil then
			self.ContentLabel.Text = tostring(value.Content)
		end
	else
		self.ContentLabel.Text = tostring(value)
	end
end

function Paragraph:SetContent(text: string)
	self.ContentLabel.Text = text
end

------------------------------------------------------------------------------
-- Divider
------------------------------------------------------------------------------
local Divider = setmetatable({}, { __index = Element })
Divider.__index = Divider
Display.Divider = Divider

function Divider.new(section: any, options: any)
	local opts = if type(options) == "string" then { Text = options } else options or {}
	local self = Element.new(section, opts, "Divider", Divider)
	local root = plainRoot(self, "Divider")
	root.AutomaticSize = Enum.AutomaticSize.None
	root.Size = UDim2.new(1, 0, 0, if opts.Text then 18 else 9)
	if opts.Text then
		local label = Kit.Label({
			Text = string.upper(tostring(opts.Text)),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 2,
			Parent = root,
		}, "Tiny", "TextMuted")
		local function line(left: boolean)
			local l = Create("Frame", {
				AnchorPoint = Vector2.new(if left then 0 else 1, 0.5),
				Position = UDim2.fromScale(if left then 0 else 1, 0.5),
				Size = UDim2.new(0.5, -40, 0, 1),
				Parent = root,
			})
			Kit.Bind(l, "BackgroundColor3", "Border")
			return l
		end
		local left, right = line(true), line(false)
		local function fit()
			local w = label.AbsoluteSize.X / 2 + 8
			left.Size = UDim2.new(0.5, -w, 0, 1)
			right.Size = UDim2.new(0.5, -w, 0, 1)
		end
		self.Maid:Give(label:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
		task.defer(fit)
	else
		local l = Create("Frame", {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.fromScale(0, 0.5),
			Size = UDim2.new(1, 0, 0, 1),
			Parent = root,
		})
		Kit.Bind(l, "BackgroundColor3", "Border")
	end
	return self
end

------------------------------------------------------------------------------
-- Tags / chips
------------------------------------------------------------------------------
local Tags = setmetatable({}, { __index = Element })
Tags.__index = Tags
Display.Tags = Tags

-- Builds chips into `parent` (also used by page headers). Returns created chips.
function Display.BuildChips(parent: Instance, list: { any }): { Frame }
	local chips = {}
	for index, tag in list do
		local data = if type(tag) == "table" then tag else { Text = tostring(tag) }
		local colorKey = data.Color or "Accent"
		local chip = Create("Frame", {
			Name = "Chip",
			Size = UDim2.new(0, 0, 0, 22),
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = index,
			Parent = parent,
		})
		Kit.Bind(chip, "BackgroundColor3", colorKey)
		Kit.Bind(chip, "BackgroundTransparency", { colorKey }, function()
			return 0.84
		end)
		Kit.Corner(chip, "pill")
		Create("UIPadding", { PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9), Parent = chip })
		Create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 5),
			Parent = chip,
		})
		if data.Icon then
			Kit.Icon(data.Icon, { Size = UDim2.fromOffset(11, 11), LayoutOrder = 1, Parent = chip }, colorKey)
		end
		Kit.Label({
			Text = tostring(data.Text or ""),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			LayoutOrder = 2,
			Parent = chip,
		}, "Tiny", colorKey)
		table.insert(chips, chip)
	end
	return chips
end

function Tags.new(section: any, options: any)
	local opts = if type(options) == "table" and options.Tags == nil and #options > 0 then { Tags = options } else options or {}
	local self = Element.new(section, opts, "Tags", Tags)
	local root = plainRoot(self, "Tags")
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		Wraps = true,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 6),
		Parent = root,
	})
	self.Value = opts.Tags or {}
	self.Chips = Display.BuildChips(root, self.Value)
	return self
end

function Tags:SetTags(list: { any })
	for _, chip in self.Chips do
		chip:Destroy()
	end
	self.Value = list
	self.Chips = Display.BuildChips(self.Root, list)
end
Tags.Set = Tags.SetTags

------------------------------------------------------------------------------
-- Status card
------------------------------------------------------------------------------
local StatusCard = setmetatable({}, { __index = Element })
StatusCard.__index = StatusCard
Display.StatusCard = StatusCard

function StatusCard.new(section: any, options: any)
	local self = Element.new(section, options, "StatusCard", StatusCard)
	local o = self.Options
	self.StatusKey = o.Status or o.Color or "Success"
	local root = plainRoot(self, "StatusCard")
	root.AutomaticSize = Enum.AutomaticSize.None
	Kit.Bind(root, "Size", { "Spacing" }, function(T)
		return UDim2.new(1, 0, 0, Theme:Metric("Row", T) + 18)
	end)
	Kit.Panel(root, "Surface", "Panel")
	Kit.Corner(root, 0.8)
	Kit.Stroke(root, "Border")
	Kit.Padding(root, "Inner", 0)

	local badge = Create("Frame", {
		Name = "Badge",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(36, 36),
		Parent = root,
	})
	Kit.Corner(badge, 0.8)
	Kit.Bind(badge, "BackgroundColor3", { "Success", "Warning", "Danger", "Accent", "Accent2", "TextMuted" }, function(T)
		return T[self.StatusKey] or T.Accent
	end)
	Kit.Bind(badge, "BackgroundTransparency", { "Accent" }, function()
		return 0.84
	end)
	self.Badge = badge
	self.Icon = Kit.Icon(o.Icon or "activity", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(18, 18),
		Parent = badge,
	}, self.StatusKey)

	local text = Create("Frame", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(48, 0),
		Size = UDim2.new(1, -48, 1, 0),
		Parent = root,
	})
	Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 2),
		Parent = text,
	})
	self.TitleLabel = Kit.Label({
		Text = tostring(o.Title or "Status"),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = text,
	}, "Heading", "Text")
	self.SubtitleLabel = Kit.Label({
		Text = tostring(o.Subtitle or ""),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Parent = text,
	}, "Small", self.StatusKey)
	Kit.Bind(self.SubtitleLabel, "TextColor3", { "Success", "Warning", "Danger", "Accent", "Accent2", "TextMuted" }, function(T)
		return T[self.StatusKey] or T.Accent
	end)
	return self
end

function StatusCard:SetStatus(subtitle: string?, colorKey: string?)
	if subtitle then
		self.SubtitleLabel.Text = subtitle
	end
	if colorKey then
		self.StatusKey = colorKey
		Kit.Refresh(self.Badge, "BackgroundColor3")
		Kit.Refresh(self.SubtitleLabel, "TextColor3")
		Kit.SetIconColor(self.Icon, colorKey)
	end
end
StatusCard.Set = function(self, value: any)
	if type(value) == "table" then
		self:SetStatus(value.Subtitle, value.Status)
		if value.Title then
			self.TitleLabel.Text = value.Title
		end
	else
		self:SetStatus(tostring(value))
	end
end

function StatusCard:SetIcon(name: string)
	Kit.SetIcon(self.Icon, name)
end

return Display
end

-- ==========================================================================
-- Components/Dropdown
-- ==========================================================================
__modules["Components/Dropdown"] = function()
--[[
	Dropdown (single / multi, optional search)
	  Section:AddDropdown({
	      Title, Description, Flag, Values = {"A", "B"}, Default = "A" | {"A"},
	      Multi = false, Search = nil (auto when > 8 values), Placeholder = "Select...",
	      AllowNone = false, MaxHeight = 190, Callback = function(value) end,
	  })
	  Dropdown:Set(value) :Get() :Refresh(values, keepSelection?) :Open() :Close()
	Single -> string | nil, Multi -> { string } (in list order).
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Constants = Import("Constants")
local Element = Import("Components/Element")

local Create = Utility.Create

local Dropdown = setmetatable({}, { __index = Element })
Dropdown.__index = Dropdown

local function toStringList(values: any): { string }
	local list = {}
	if type(values) == "table" then
		for _, v in values do
			table.insert(list, tostring(v))
		end
	end
	return list
end

function Dropdown.new(section: any, options: { [string]: any })
	local self = Element.new(section, options, "Dropdown", Dropdown)
	local o = self.Options
	self.Multi = o.Multi == true
	self.Values = toStringList(o.Values)
	self.AllowNone = o.AllowNone == true or self.Multi
	self.Placeholder = o.Placeholder or "Select..."
	self.MaxHeight = o.MaxHeight or 190
	self.Opened = false
	self.Items = {} :: { [string]: any }
	if self.Multi then
		self.Value = {}
		if type(o.Default) == "table" then
			self.Value = self:_FilterMulti(o.Default)
		elseif o.Default ~= nil then
			self.Value = self:_FilterMulti({ o.Default })
		end
	else
		local default = if o.Default ~= nil then tostring(o.Default) else nil
		self.Value = if default and table.find(self.Values, default) then default else nil
		if self.Value == nil and not self.AllowNone then
			self.Value = self.Values[1]
		end
	end

	self:_BuildRow({ ControlWidth = 168 })

	-- selection box
	local box = Create("TextButton", {
		Name = "Box",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.new(1, 0, 0, 28),
		Parent = self.Control,
	})
	Kit.Bind(box, "Size", { "Spacing" }, function(T)
		return UDim2.new(1, 0, 0, math.max(Theme:Metric("Row", T) - 12, 26))
	end)
	self:_Stateful(box, "BackgroundColor3", { "Input", "Text" }, function(T)
		return if self.State.Hover then Utility.Mix(T.Input, T.Text, 0.04) else T.Input
	end)
	Kit.Bind(box, "BackgroundTransparency", Theme.AlphaDeps("Input", "Panel"), function(T)
		return Theme:Alpha("Input", "Panel", T)
	end)
	Kit.Corner(box, 0.6)
	local boxStroke = Kit.Stroke(box, "Border", {
		Deps = { "Border", "Accent" },
		Compute = function(T)
			return if self.Opened then T.Accent else T.Border
		end,
	})
	table.insert(self._stateful, boxStroke)
	self.SelectedLabel = Kit.Label({
		Name = "Selected",
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -34, 1, 0),
		Parent = box,
	}, "Small", "Text")
	Kit.Bind(self.SelectedLabel, "TextColor3", { "Text", "TextMuted" }, function(T)
		local empty = if self.Multi then #self.Value == 0 else self.Value == nil
		return if empty then T.TextMuted else T.Text
	end)
	local chevron = Kit.Icon("chevron-down", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -9, 0.5, 0),
		Size = UDim2.fromOffset(12, 12),
		Parent = box,
	}, "TextMuted")
	self.Chevron = chevron
	self.Box = box
	Animations.AttachPress(box, box, 0.97)

	-- expandable list (inside the row's stack)
	local listHolder = Create("Frame", {
		Name = "List",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		ClipsDescendants = true,
		LayoutOrder = 2,
		Visible = false,
		Parent = self.Stack,
	})
	self.ListHolder = listHolder
	local inner = Create("Frame", {
		Name = "Inner",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = listHolder,
	})
	Kit.Padding(inner, "Inner", 0)
	local innerList = Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 4),
		Parent = inner,
	})
	self.Inner = inner
	self._innerList = innerList

	local useSearch = if o.Search == nil then #self.Values > 8 else o.Search == true
	if useSearch then
		local searchBox = Kit.TextBox({
			Name = "Search",
			Size = UDim2.new(1, 0, 0, 28),
			PlaceholderText = Constants.Strings.Search,
			LayoutOrder = 1,
			Parent = inner,
		}, "Small")
		Kit.Panel(searchBox, "Input", "Panel")
		Kit.Corner(searchBox, 0.6)
		Kit.Stroke(searchBox, "Border")
		Create("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = searchBox })
		self.Maid:Give(searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			self:_Filter(searchBox.Text)
		end))
		self.SearchBox = searchBox
	end

	local scroll = Kit.Scrolling({
		Name = "Items",
		Size = UDim2.new(1, 0, 0, 0),
		LayoutOrder = 2,
		Parent = inner,
	})
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = scroll })
	self.Scroll = scroll

	self.Maid:Give(Input.Track(box, {
		LongPress = if o.Tooltip then 0.5 else nil,
		LongPressed = function(pos)
			self:_ShowTouchTooltip(pos)
		end,
		Tap = function()
			if not self.Disabled then
				Kit.Sound("Click")
				if self.Opened then
					self:Close()
				else
					self:Open()
				end
			end
		end,
	}))

	self:_BuildItems()
	self:_RenderText()
	self:_Register()
	return self
end

------------------------------------------------------------------------------
-- Items
------------------------------------------------------------------------------
function Dropdown:_ItemHeight(): number
	return if Theme.TouchMode then 40 else math.max(Theme:Metric("Row") - 8, 28)
end

function Dropdown:_IsSelected(value: string): boolean
	if self.Multi then
		return table.find(self.Value, value) ~= nil
	end
	return self.Value == value
end

function Dropdown:_BuildItems()
	for _, item in self.Items do
		item.Button:Destroy()
	end
	table.clear(self.Items)
	for index, value in self.Values do
		local button = Create("TextButton", {
			Name = "Item",
			Size = UDim2.new(1, -4, 0, self:_ItemHeight()),
			LayoutOrder = index,
			Parent = self.Scroll,
		})
		Kit.Corner(button, 0.5)
		local hovered = false
		Kit.Bind(button, "BackgroundColor3", { "Accent", "Surface", "Text" }, function(T)
			if self:_IsSelected(value) then
				return T.Accent
			end
			return if hovered then Utility.Mix(T.Surface, T.Text, 0.06) else T.Surface
		end)
		Kit.Bind(button, "BackgroundTransparency", { "Accent" }, function()
			if self:_IsSelected(value) then
				return 0.82
			end
			return if hovered then 0.2 else 1
		end)
		local label = Kit.Label({
			Text = value,
			Position = UDim2.fromOffset(10, 0),
			Size = UDim2.new(1, -36, 1, 0),
			Parent = button,
		}, "Small", "Text")
		Kit.Bind(label, "TextColor3", { "Text", "Accent" }, function(T)
			return if self:_IsSelected(value) then T.Accent else T.Text
		end)
		local check = Kit.Icon("check", {
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.fromOffset(12, 12),
			Parent = button,
		}, "Accent")
		local item = { Button = button, Label = label, Check = check, Value = value }
		local function refresh()
			Kit.Refresh(button)
			Kit.Refresh(label)
			check.Visible = self:_IsSelected(value)
		end
		item.Refresh = refresh
		button.MouseEnter:Connect(function()
			hovered = true
			refresh()
		end)
		button.MouseLeave:Connect(function()
			hovered = false
			refresh()
		end)
		button.MouseButton1Click:Connect(function()
			self:_Choose(value)
		end)
		refresh()
		self.Items[value] = item
	end
	if self.SearchBox then
		self:_Filter(self.SearchBox.Text)
	end
	self:_Resize()
end

function Dropdown:_Filter(query: string)
	local q = string.lower(query or "")
	for value, item in self.Items do
		item.Button.Visible = q == "" or string.find(string.lower(value), q, 1, true) ~= nil
	end
	self:_Resize()
end

function Dropdown:_ContentHeight(): number
	local count = 0
	for _, item in self.Items do
		if item.Button.Visible then
			count += 1
		end
	end
	local itemsHeight = count * (self:_ItemHeight() + 2)
	return math.min(itemsHeight, self.MaxHeight)
end

function Dropdown:_Resize()
	local listHeight = self:_ContentHeight()
	self.Scroll.Size = UDim2.new(1, 0, 0, listHeight)
	if self.Opened then
		local searchHeight = if self.SearchBox then 32 else 0
		local target = listHeight + searchHeight + Theme:Metric("Inner") + 2
		Animations.Tween(self.ListHolder, { Size = UDim2.new(1, 0, 0, target) }, 0.25)
	end
end

function Dropdown:_Choose(value: string)
	if self.Disabled then
		return
	end
	Kit.Sound("Click")
	if self.Multi then
		local list = table.clone(self.Value)
		local index = table.find(list, value)
		if index then
			table.remove(list, index)
		else
			table.insert(list, value)
		end
		self:Set(list)
	else
		if self.Value == value and self.AllowNone then
			self:Set(nil)
		else
			self:Set(value)
		end
		self:Close()
	end
end

------------------------------------------------------------------------------
-- Open / close
------------------------------------------------------------------------------
function Dropdown:Open()
	if self.Opened then
		return
	end
	self.Opened = true
	self.ListHolder.Visible = true
	self:_SetState("Focus", true)
	Animations.Tween(self.Chevron, { Rotation = 180 }, 0.25)
	self:_Resize()
	for _, inst in self._stateful do
		Kit.Refresh(inst)
	end
end

function Dropdown:Close()
	if not self.Opened then
		return
	end
	self.Opened = false
	self:_SetState("Focus", false)
	Animations.Tween(self.Chevron, { Rotation = 0 }, 0.25)
	local tween = Animations.Tween(self.ListHolder, { Size = UDim2.new(1, 0, 0, 0) }, 0.2)
	local function hide()
		if not self.Opened then
			self.ListHolder.Visible = false
		end
	end
	if tween then
		tween.Completed:Once(hide)
	else
		hide()
	end
	for _, inst in self._stateful do
		Kit.Refresh(inst)
	end
end

------------------------------------------------------------------------------
-- Value
------------------------------------------------------------------------------
function Dropdown:_FilterMulti(list: any): { string }
	local result = {}
	if type(list) ~= "table" then
		return result
	end
	local wanted = {}
	for _, v in list do
		wanted[tostring(v)] = true
	end
	for _, value in self.Values do
		if wanted[value] then
			table.insert(result, value)
		end
	end
	return result
end

function Dropdown:_RenderText()
	local text
	if self.Multi then
		text = if #self.Value > 0 then table.concat(self.Value, ", ") else Constants.Strings.None
	else
		text = if self.Value ~= nil then self.Value else self.Placeholder
	end
	self.SelectedLabel.Text = text
	Kit.Refresh(self.SelectedLabel, "TextColor3")
	for _, item in self.Items do
		item.Refresh()
	end
end

function Dropdown:Set(value: any, silent: boolean?, fromConfig: boolean?)
	local newValue
	if self.Multi then
		newValue = self:_FilterMulti(if type(value) == "table" then value elseif value ~= nil then { value } else {})
	else
		newValue = if value ~= nil then tostring(value) else nil
		if newValue ~= nil and not table.find(self.Values, newValue) then
			return
		end
		if newValue == nil and not self.AllowNone then
			return
		end
		if newValue == self.Value then
			return
		end
	end
	self.Value = newValue
	self:_RenderText()
	local out = if self.Multi then table.clone(newValue) else newValue
	if silent then
		self.Changed:Fire(out)
	else
		self:_Fire(out, fromConfig)
	end
end

function Dropdown:Get(): any
	if self.Multi then
		return table.clone(self.Value)
	end
	return self.Value
end

-- Replaces the option list. keepSelection keeps still-valid selected values.
function Dropdown:Refresh(values: { any }, keepSelection: boolean?)
	self.Values = toStringList(values)
	if self.Multi then
		self.Value = if keepSelection ~= false then self:_FilterMulti(self.Value) else {}
	elseif keepSelection == false or (self.Value and not table.find(self.Values, self.Value)) then
		self.Value = if self.AllowNone then nil else self.Values[1]
	end
	self:_BuildItems()
	self:_RenderText()
end

function Dropdown:Serialize(): any
	return self:Get()
end

function Dropdown:Deserialize(value: any)
	if self.Multi then
		if type(value) == "table" then
			self:Set(value, false, true)
		end
	elseif type(value) == "string" or value == nil then
		if value == nil and not self.AllowNone then
			return
		end
		self:Set(value, false, true)
	end
end

return Dropdown
end

-- ==========================================================================
-- Components/Element
-- ==========================================================================
__modules["Components/Element"] = function()
--[[
	Element
	Base class of every section element. Provides:
	  * row frame with themed background/border, hover & focus states
	  * Flag registration (Config), callback dispatch, Changed signal
	  * :Set / :Get (implemented by subclasses), :SetVisible, :SetDisabled,
	    :SetTooltip, :SetTitle, :SetDescription, :OnChanged, :Destroy
	  * tooltip (hover on desktop, long-press on touch)

	Subclass pattern:
	  local Toggle = setmetatable({}, { __index = Element })
	  Toggle.__index = Toggle
	  local self = Element.new(section, options, "Toggle", Toggle)
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Maid = Import("Maid")
local Signal = Import("Signal")
local Config = Import("Config")
local Tooltip = Import("Components/Tooltip")

local Create = Utility.Create

local Element = {}
Element.__index = Element

function Element.new(section: any, options: { [string]: any }?, kind: string, class: any?): any
	local opts = options or {}
	local self = setmetatable({}, class or Element)
	self.Section = section
	self.Window = section and section.Window
	self.Options = opts
	self.Type = kind
	self.Flag = opts.Flag
	self.Callback = opts.Callback
	self.IgnoreConfig = opts.IgnoreConfig == true
	self.NoCallbackOnLoad = opts.NoCallbackOnLoad == true
	self.Maid = Maid.new()
	self.Changed = Signal.new()
	self.Visible = true
	self.Disabled = false
	self.TooltipText = opts.Tooltip
	self.State = { Hover = false, Pressed = false, Focus = false, Disabled = false }
	self._stateful = {} :: { Instance }
	return self
end

------------------------------------------------------------------------------
-- Row construction
------------------------------------------------------------------------------

-- Builds the standard row: Root (auto height) > Main (Row metric height) with a
-- title/description block on the left and a `Control` holder on the right.
-- options.ControlWidth: width of the right control area (px)
-- options.Plain: no background
function Element:_BuildRow(options: { [string]: any }?)
	local opts = options or {}
	local o = self.Options
	local parent = if self.Section then self.Section.Container else nil

	local root = Create("Frame", {
		Name = self.Type .. (if o.Title then "_" .. tostring(o.Title) else ""),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = if self.Section then self.Section:_NextOrder() else 0,
		ClipsDescendants = opts.Clips == true,
	})
	self.Root = root
	self.Maid:Give(root)

	if not opts.Plain then
		self:_Stateful(root, "BackgroundColor3", { "Surface", "Text" }, function(T)
			if self.State.Hover and not self.State.Disabled then
				return Utility.Mix(T.Surface, T.Text, 0.035)
			end
			return T.Surface
		end)
		Kit.Bind(root, "BackgroundTransparency", Theme.AlphaDeps("Surface", "Panel"), function(T)
			return Theme:Alpha("Surface", "Panel", T)
		end)
		Kit.Corner(root, 0.7)
		local stroke = Kit.Stroke(root, "Border", {
			Deps = { "Border", "Accent", "Text" },
			Compute = function(T)
				if self.State.Focus then
					return T.Accent
				elseif self.State.Hover and not self.State.Disabled then
					return Utility.Mix(T.Border, T.Text, 0.12)
				end
				return T.Border
			end,
		})
		table.insert(self._stateful, stroke)
	end

	-- Stack: vertical list (Main + optional expandable panels like dropdown lists)
	local stack = Create("Frame", {
		Name = "Stack",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = root,
	})
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = stack })
	self.Stack = stack

	local main = Create("Frame", {
		Name = "Main",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 38),
		LayoutOrder = 1,
		Parent = stack,
	})
	self.Main = main
	local extra = opts.ExtraHeight or 0
	local hasDescription = o.Description ~= nil and o.Description ~= ""
	local rowBonus = opts.RowBonus or 0
	Kit.Bind(main, "Size", { "Spacing", "TextScale" }, function(T)
		local h = Theme:Metric("Row", T) + extra + rowBonus
		local description = self.Options.Description
		if description ~= nil and description ~= "" and not opts.NoText then
			h += Theme:TextSize("Small", T) + 2
		end
		return UDim2.new(1, 0, 0, h)
	end)

	local controlWidth = opts.ControlWidth or 0
	if not opts.NoText then
		local textHolder = Create("Frame", {
			Name = "Text",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, -(controlWidth + 8), 1, -extra),
			Parent = main,
		})
		Kit.Padding(textHolder, "Inner", 0)
		local list = Create("UIListLayout", {
			SortOrder = Enum.SortOrder.LayoutOrder,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 1),
			Parent = textHolder,
		})
		list.Name = "List"
		self.TitleLabel = Kit.Label({
			Name = "Title",
			Text = tostring(o.Title or o.Text or ""),
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 1,
			Parent = textHolder,
		}, "Body", "Text")
		self.DescriptionLabel = Kit.Label({
			Name = "Description",
			Text = tostring(o.Description or ""),
			Visible = hasDescription,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 2,
			Parent = textHolder,
		}, "Small", "TextMuted")
		self.TextHolder = textHolder
	end

	if controlWidth > 0 then
		local control = Create("Frame", {
			Name = "Control",
			BackgroundTransparency = 1,
			ZIndex = 3, -- above row hitboxes so buttons inside stay clickable
			AnchorPoint = Vector2.new(1, 0.5),
			Size = UDim2.new(0, controlWidth, 1, -extra),
			Position = UDim2.new(1, 0, 0.5, -extra / 2),
			Parent = main,
		})
		Kit.Padding(control, "Inner", 0)
		self.Control = control
	end

	-- hover state
	self.Maid:Give(root.MouseEnter:Connect(function()
		self:_SetState("Hover", true)
	end))
	self.Maid:Give(root.MouseLeave:Connect(function()
		self:_SetState("Hover", false)
	end))

	-- tooltip
	self.Maid:Give(Tooltip.Attach(root, function()
		return self.TooltipText
	end))

	root.Parent = parent
	return root
end

-- Disabled cover (sinks input). Created lazily.
function Element:_Cover(): TextButton
	if self._cover then
		return self._cover
	end
	local cover = Create("TextButton", {
		Name = "DisabledCover",
		Size = UDim2.fromScale(1, 1),
		ZIndex = 50,
		Visible = false,
		Parent = self.Root,
	})
	Kit.Bind(cover, "BackgroundColor3", "Card")
	Kit.Bind(cover, "BackgroundTransparency", { "Card" }, function()
		return 0.45
	end)
	Kit.Corner(cover, 0.7)
	self._cover = cover
	return cover
end

------------------------------------------------------------------------------
-- State helpers
------------------------------------------------------------------------------

-- Binds a property whose value also depends on element state (hover, focus...)
function Element:_Stateful(inst: Instance, property: string, deps: { string }, compute: (any) -> any, options: any?)
	Kit.Bind(inst, property, deps, compute, options)
	if not table.find(self._stateful, inst) then
		table.insert(self._stateful, inst)
	end
end

function Element:_SetState(name: string, value: boolean)
	if self.State[name] == value then
		return
	end
	self.State[name] = value
	for _, inst in self._stateful do
		Kit.Refresh(inst)
	end
	if self._OnState then
		self:_OnState(name, value)
	end
end

------------------------------------------------------------------------------
-- Flag / callback
------------------------------------------------------------------------------
function Element:_Register()
	if self.Flag then
		Config:Register(self)
	end
end

-- Fires callback + Changed. `fromConfig` respects NoCallbackOnLoad.
function Element:_Fire(value: any, fromConfig: boolean?)
	self.Changed:Fire(value)
	if self.Flag then
		Config.FlagChanged:Fire(self.Flag, value)
	end
	if fromConfig and self.NoCallbackOnLoad then
		return
	end
	Utility.SafeCallback(self.Callback, value)
end

function Element:OnChanged(fn: (any) -> ())
	return self.Changed:Connect(fn)
end

-- Default serialisation: the raw value
function Element:Serialize(): any
	return self:Get()
end

function Element:Deserialize(value: any)
	self:Set(value, false, true)
end

function Element:Get(): any
	return self.Value
end

function Element:Set(value: any, _silent: boolean?, _fromConfig: boolean?)
	self.Value = value
end

------------------------------------------------------------------------------
-- Common API
------------------------------------------------------------------------------
function Element:SetVisible(visible: boolean)
	self.Visible = visible
	if self.Root then
		self.Root.Visible = visible
	end
end

function Element:SetDisabled(disabled: boolean)
	self.Disabled = disabled
	self:_SetState("Disabled", disabled)
	if self.Root then
		self:_Cover().Visible = disabled
	end
end

function Element:SetTooltip(text: string?)
	self.TooltipText = text
end

function Element:SetTitle(text: string)
	self.Options.Title = text
	if self.TitleLabel then
		self.TitleLabel.Text = text
	end
end

function Element:SetDescription(text: string?)
	self.Options.Description = text
	if self.DescriptionLabel then
		self.DescriptionLabel.Text = text or ""
		self.DescriptionLabel.Visible = text ~= nil and text ~= ""
		Kit.Refresh(self.Main, "Size")
	end
end

-- Shows the tooltip at a position (used for touch long-press)
function Element:_ShowTouchTooltip(position: Vector2)
	if self.TooltipText then
		Tooltip.ShowAt(self.TooltipText, position, 2.5)
	end
end

function Element:Destroy()
	if self.Destroyed then
		return
	end
	self.Destroyed = true
	Config:Unregister(self)
	self.Changed:Destroy()
	self.Maid:Clean()
	if self.Section then
		self.Section:_RemoveElement(self)
	end
end

return Element
end

-- ==========================================================================
-- Components/Keybind
-- ==========================================================================
__modules["Components/Keybind"] = function()
--[[
	Keybind picker
	  Section:AddKeybind({
	      Title, Description, Flag, Default = Enum.KeyCode.E | "E",
	      Mode = "Toggle" | "Hold" | "Always", ChangeableMode = true,
	      Callback = function(active: boolean) end,     -- key pressed (toggle/hold state)
	      ChangedCallback = function(keyName: string) end, -- rebinding
	      Blacklist = { "Escape" },
	  })
	Click the key box and press a key (Backspace/Delete clears, Escape cancels).
	Mouse buttons: MouseButton1/2/3 are supported as binds.
	Keybind:Set({Key = "E", Mode = "Hold"}) | Keybind:Set("E")  :Get() -> {Key, Mode}
	Keybind:GetState() -> boolean (current toggle/hold state)
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Element = Import("Components/Element")

local Create = Utility.Create
local UserInputService = Utility.Services.UserInputService

local Keybind = setmetatable({}, { __index = Element })
Keybind.__index = Keybind

local MODES = { "Toggle", "Hold", "Always" }
local MOUSE = {
	MouseButton1 = Enum.UserInputType.MouseButton1,
	MouseButton2 = Enum.UserInputType.MouseButton2,
	MouseButton3 = Enum.UserInputType.MouseButton3,
}
local SHORT = {
	LeftShift = "LShift",
	RightShift = "RShift",
	LeftControl = "LCtrl",
	RightControl = "RCtrl",
	LeftAlt = "LAlt",
	RightAlt = "RAlt",
	MouseButton1 = "MB1",
	MouseButton2 = "MB2",
	MouseButton3 = "MB3",
	Backquote = "`",
	Space = "Space",
}

local function keyName(value: any): string?
	if value == nil then
		return nil
	end
	if typeof(value) == "EnumItem" then
		return value.Name
	end
	if type(value) == "string" then
		if value == "" or value == "None" then
			return nil
		end
		if MOUSE[value] then
			return value
		end
		local ok = pcall(function()
			return (Enum.KeyCode :: any)[value]
		end)
		return if ok then value else nil
	end
	return nil
end

function Keybind.new(section: any, options: { [string]: any })
	local self = Element.new(section, options, "Keybind", Keybind)
	local o = self.Options
	self.Key = keyName(o.Default)
	self.Mode = if table.find(MODES, o.Mode) then o.Mode else "Toggle"
	self.ChangeableMode = o.ChangeableMode ~= false
	self.Active = self.Mode == "Always"
	self.Listening = false
	self.Blacklist = o.Blacklist or {}

	self:_BuildRow({ ControlWidth = if self.ChangeableMode then 150 else 100 })

	local control = self.Control
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 6),
		Parent = control,
	})

	if self.ChangeableMode then
		local modeButton = Create("TextButton", {
			Name = "Mode",
			Size = UDim2.fromOffset(52, 26),
			LayoutOrder = 1,
			Parent = control,
		})
		Kit.Panel(modeButton, "Input", "Panel")
		Kit.Corner(modeButton, 0.6)
		Kit.Stroke(modeButton, "Border")
		self.ModeLabel = Kit.Label({
			Size = UDim2.fromScale(1, 1),
			TextXAlignment = Enum.TextXAlignment.Center,
			Text = self.Mode,
			Parent = modeButton,
		}, "Tiny", "TextMuted")
		Animations.AttachPress(modeButton, modeButton, 0.93)
		self.Maid:Give(modeButton.MouseButton1Click:Connect(function()
			if self.Disabled then
				return
			end
			local index = table.find(MODES, self.Mode) or 1
			self:SetMode(MODES[index % #MODES + 1])
		end))
	end

	local keyButton = Create("TextButton", {
		Name = "Key",
		Size = UDim2.fromOffset(78, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Parent = control,
	})
	Kit.Panel(keyButton, "Input", "Panel")
	Kit.Corner(keyButton, 0.6)
	local stroke = Kit.Stroke(keyButton, "Border", {
		Deps = { "Border", "Accent" },
		Compute = function(T)
			return if self.Listening then T.Accent else T.Border
		end,
	})
	table.insert(self._stateful, stroke)
	Create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = keyButton })
	Create("UISizeConstraint", { MinSize = Vector2.new(60, 0), Parent = keyButton })
	self.KeyLabel = Kit.Label({
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = keyButton,
	}, "Mono", "Text")
	self:_Stateful(self.KeyLabel, "TextColor3", { "Text", "Accent" }, function(T)
		return if self.Listening or self.Active then T.Accent else T.Text
	end)
	Animations.AttachPress(keyButton, keyButton, 0.95)
	self.KeyButton = keyButton

	self.Maid:Give(keyButton.MouseButton1Click:Connect(function()
		if self.Disabled or self.Listening then
			return
		end
		self:_Listen()
	end))

	-- runtime handling
	self.Maid:Give(UserInputService.InputBegan:Connect(function(input, processed)
		if self.Listening or not self.Key or self.Mode == "Always" then
			return
		end
		if processed and not MOUSE[self.Key] then
			return
		end
		if self:_Matches(input) then
			if self.Mode == "Toggle" then
				self:_SetActive(not self.Active)
			else
				self:_SetActive(true)
			end
		end
	end))
	self.Maid:Give(UserInputService.InputEnded:Connect(function(input)
		if self.Mode == "Hold" and self.Key and self:_Matches(input) then
			self:_SetActive(false)
		end
	end))

	self:_RenderKey()
	self:_Register()
	return self
end

function Keybind:_Matches(input: InputObject): boolean
	local key = self.Key
	if not key then
		return false
	end
	if MOUSE[key] then
		return input.UserInputType == MOUSE[key]
	end
	return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode.Name == key
end

function Keybind:_SetActive(active: boolean)
	if self.Active == active then
		return
	end
	self.Active = active
	for _, inst in self._stateful do
		Kit.Refresh(inst)
	end
	Utility.SafeCallback(self.Callback, active)
end

function Keybind:_RenderKey()
	if self.Listening then
		self.KeyLabel.Text = "..."
	else
		local key = self.Key
		self.KeyLabel.Text = if key then (SHORT[key] or key) else "None"
	end
	if self.ModeLabel then
		self.ModeLabel.Text = self.Mode
	end
	for _, inst in self._stateful do
		Kit.Refresh(inst)
	end
end

function Keybind:_Listen()
	self.Listening = true
	self:_SetState("Focus", true)
	self:_RenderKey()
	local connection
	connection = UserInputService.InputBegan:Connect(function(input)
		local name: string? = nil
		if input.UserInputType == Enum.UserInputType.Keyboard then
			if input.KeyCode == Enum.KeyCode.Escape then
				name = self.Key or "None"
			elseif input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
				name = "None"
			else
				name = input.KeyCode.Name
			end
		else
			for mouseName, inputType in MOUSE do
				if input.UserInputType == inputType then
					name = mouseName
				end
			end
		end
		if not name then
			return
		end
		if table.find(self.Blacklist, name) then
			Animations.Shake(self.KeyButton, 4)
			return
		end
		connection:Disconnect()
		-- let the click that started listening pass
		task.defer(function()
			self.Listening = false
			self:_SetState("Focus", false)
			self:Set({ Key = name, Mode = self.Mode })
			self:_RenderKey()
		end)
	end)
	self.Maid:Give(connection)
end

function Keybind:SetMode(mode: string)
	if not table.find(MODES, mode) or mode == self.Mode then
		return
	end
	self.Mode = mode
	if mode == "Always" then
		self:_SetActive(true)
	elseif mode == "Hold" then
		self:_SetActive(false)
	end
	self:_RenderKey()
	self.Changed:Fire(self:Get())
	if self.Flag then
		Import("Config").FlagChanged:Fire(self.Flag, self:Get())
	end
end

-- Set accepts a key name / KeyCode or a table {Key, Mode}
function Keybind:Set(value: any, silent: boolean?, fromConfig: boolean?)
	local key, mode = nil, self.Mode
	if type(value) == "table" then
		key = keyName(value.Key)
		if table.find(MODES, value.Mode) then
			mode = value.Mode
		end
	else
		key = keyName(value)
	end
	local changed = key ~= self.Key or mode ~= self.Mode
	self.Key = key
	self.Mode = mode
	if mode == "Always" then
		self.Active = true
	end
	self:_RenderKey()
	if not changed then
		return
	end
	local out = self:Get()
	self.Changed:Fire(out)
	if self.Flag then
		Import("Config").FlagChanged:Fire(self.Flag, out)
	end
	if not silent and not (fromConfig and self.NoCallbackOnLoad) then
		Utility.SafeCallback(self.Options.ChangedCallback, key or "None")
	end
end

function Keybind:Get(): { Key: string?, Mode: string }
	return { Key = self.Key, Mode = self.Mode }
end

function Keybind:GetState(): boolean
	return self.Active
end

function Keybind:Serialize(): any
	return { Key = self.Key or "None", Mode = self.Mode }
end

function Keybind:Deserialize(value: any)
	if type(value) == "table" or type(value) == "string" then
		self:Set(value, false, true)
	end
end

local _ = Theme

return Keybind
end

-- ==========================================================================
-- Components/Notifications
-- ==========================================================================
__modules["Components/Notifications"] = function()
--[[
	Notifications
	Toasts with type colour, icon, remaining-time bar and smooth stacking. The
	screen corner comes from the theme key NotificationPosition. A short history is
	kept for the bell popover in the topbar.

	  Notifications.Notify({Title, Content, Type = "Info"|"Success"|"Warning"|"Error",
	                        Duration = 5, Icon = "bell", Actions = {{Title, Callback}}})
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Gui = Import("Gui")
local Signal = Import("Signal")
local State = Import("State")

local Create = Utility.Create

local Notifications = {}
Notifications.History = {} :: { { [string]: any } }
Notifications.Added = Signal.new()
Notifications.MaxHistory = 25
Notifications.MaxVisible = 6

local TYPE_COLOR = { Info = "Accent", Success = "Success", Warning = "Warning", Error = "Danger" }
local TYPE_ICON = { Info = "info", Success = "success", Warning = "warning", Error = "error" }

local container: Frame? = nil
local layout: UIListLayout? = nil
local active: { any } = {}

local function width(): number
	return math.min(330, Utility.Viewport().X - 24)
end

local function anchor()
	if not container or not layout then
		return
	end
	local pos = Theme.Values.NotificationPosition
	local top = string.find(pos, "Top") ~= nil
	local left = string.find(pos, "Left") ~= nil
	local inset = Utility.GuiInset()
	container.AnchorPoint = Vector2.new(if left then 0 else 1, if top then 0 else 1)
	container.Position = UDim2.new(if left then 0 else 1, if left then 12 else -12, if top then 0 else 1, if top then inset.Y + 12 else -12)
	container.Size = UDim2.new(0, width(), 1, -(inset.Y + 24))
	layout.VerticalAlignment = if top then Enum.VerticalAlignment.Top else Enum.VerticalAlignment.Bottom
	layout.HorizontalAlignment = if left then Enum.HorizontalAlignment.Left else Enum.HorizontalAlignment.Right
end

local function ensureContainer(): Frame
	if container and container.Parent then
		return container
	end
	container = Create("Frame", {
		Name = "Notifications",
		BackgroundTransparency = 1,
		Parent = Gui.Layer("Notifications"),
	})
	layout = Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
		Parent = container,
	})
	anchor()
	State.Maid:Give(Theme:OnChanged("NotificationPosition", anchor))
	State.Maid:Give(State.ViewportChanged:Connect(anchor))
	return container :: Frame
end

local order = 0

function Notifications.Notify(options: { [string]: any }): { [string]: any }
	local opts = options or {}
	local kind = if TYPE_COLOR[opts.Type] then opts.Type else "Info"
	local colorKey = TYPE_COLOR[kind]
	local duration = tonumber(opts.Duration) or 5
	local parent = ensureContainer()
	local top = string.find(Theme.Values.NotificationPosition, "Top") ~= nil
	local left = string.find(Theme.Values.NotificationPosition, "Left") ~= nil
	order += 1

	local record = {
		Title = tostring(opts.Title or "Notification"),
		Content = tostring(opts.Content or ""),
		Type = kind,
		Time = os.time(),
	}
	table.insert(Notifications.History, 1, record)
	if #Notifications.History > Notifications.MaxHistory then
		table.remove(Notifications.History)
	end
	Notifications.Added:Fire(record)
	Kit.Sound(if kind == "Error" then "Error" else "Notify")

	-- holder animates its height so the stack moves smoothly
	local holder = Create("Frame", {
		Name = "Toast",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		LayoutOrder = if top then order else -order,
		ClipsDescendants = false,
		Parent = parent,
	})
	local card = Create("Frame", {
		Name = "Card",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Position = UDim2.new(if left then -1.2 else 1.2, 0, 0, 0),
		Parent = holder,
	})
	Kit.Panel(card, "NotificationBackground", "Free")
	Kit.Corner(card, 1)
	Kit.Stroke(card, "NotificationBorder", { Always = true })

	local accentBar = Create("Frame", {
		Name = "Accent",
		Size = UDim2.new(0, 3, 1, -16),
		Position = UDim2.fromOffset(0, 8),
		Parent = card,
	})
	Kit.Bind(accentBar, "BackgroundColor3", colorKey)
	Kit.Corner(accentBar, "pill")

	local body = Create("Frame", {
		Name = "Body",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = card,
	})
	Create("UIPadding", {
		PaddingLeft = UDim.new(0, 14),
		PaddingRight = UDim.new(0, 34),
		PaddingTop = UDim.new(0, 12),
		PaddingBottom = UDim.new(0, 14),
		Parent = body,
	})
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3), Parent = body })

	local header = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 18),
		LayoutOrder = 1,
		Parent = body,
	})
	Kit.Icon(opts.Icon or TYPE_ICON[kind], { Size = UDim2.fromOffset(16, 16), Position = UDim2.fromOffset(0, 1), Parent = header }, colorKey)
	Kit.Label({
		Text = record.Title,
		Size = UDim2.new(1, -24, 1, 0),
		Position = UDim2.fromOffset(24, 0),
		Parent = header,
	}, "Heading", "Text")

	if record.Content ~= "" then
		Kit.Label({
			Text = record.Content,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			TextTruncate = Enum.TextTruncate.None,
			TextYAlignment = Enum.TextYAlignment.Top,
			LayoutOrder = 2,
			Parent = body,
		}, "Small", "TextMuted")
	end

	local closeButton = Create("TextButton", {
		Name = "Close",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -8, 0, 8),
		Size = UDim2.fromOffset(20, 20),
		Parent = card,
	})
	Kit.Icon("close", { Size = UDim2.fromOffset(12, 12), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Parent = closeButton }, "TextMuted")

	local bar = Create("Frame", {
		Name = "Time",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 10, 1, -5),
		Size = UDim2.new(1, -20, 0, 2),
		Parent = card,
	})
	Kit.Bind(bar, "BackgroundColor3", colorKey)
	Kit.Bind(bar, "BackgroundTransparency", { colorKey }, function()
		return 0.4
	end)
	Kit.Corner(bar, "pill")

	local closed = false
	local object = {}

	local function close()
		if closed then
			return
		end
		closed = true
		local index = table.find(active, object)
		if index then
			table.remove(active, index)
		end
		Animations.Tween(card, { Position = UDim2.new(if left then -1.2 else 1.2, 0, 0, 0) }, 0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
		task.delay(0.22 / Animations.Speed(), function()
			Animations.Tween(holder, { Size = UDim2.new(1, 0, 0, 0) }, 0.25)
			task.delay(0.3 / Animations.Speed(), function()
				holder:Destroy()
			end)
		end)
	end
	object.Close = close
	object.Destroy = close

	closeButton.MouseButton1Click:Connect(close)

	-- actions (optional buttons)
	if type(opts.Actions) == "table" and #opts.Actions > 0 then
		local actions = Create("Frame", {
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 26),
			LayoutOrder = 3,
			Parent = body,
		})
		Create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 6),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = actions,
		})
		for i, action in opts.Actions do
			local button = Create("TextButton", {
				Size = UDim2.new(0, 0, 1, 0),
				AutomaticSize = Enum.AutomaticSize.X,
				LayoutOrder = i,
				Text = tostring(action.Title or "OK"),
				Parent = actions,
			})
			Kit.Text(button, "Small", if i == 1 then "AccentText" else "Text")
			if i == 1 then
				Kit.AccentFill(button, "Button")
			else
				Kit.Panel(button, "Surface", "Free")
			end
			Kit.Corner(button, 0.6)
			Create("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = button })
			button.MouseButton1Click:Connect(function()
				Utility.SafeCallback(action.Callback)
				close()
			end)
		end
	end

	table.insert(active, object)
	if #active > Notifications.MaxVisible then
		active[1].Close()
	end

	-- animate in once the card has measured its height
	task.defer(function()
		local height = card.AbsoluteSize.Y
		if height <= 0 then
			task.wait()
			height = card.AbsoluteSize.Y
		end
		Animations.Tween(holder, { Size = UDim2.new(1, 0, 0, height) }, 0.3)
		Animations.Tween(card, { Position = UDim2.new() }, 0.45, Enum.EasingStyle.Quint)
		card:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if not closed then
				holder.Size = UDim2.new(1, 0, 0, card.AbsoluteSize.Y)
			end
		end)
		if duration > 0 then
			local tween = Utility.Services.TweenService:Create(bar, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.new(0, 0, 0, 2) })
			tween:Play()
			task.delay(duration, close)
		else
			bar.Visible = false
		end
	end)

	return object
end

function Notifications.ClearHistory()
	table.clear(Notifications.History)
	Notifications.Added:Fire(nil)
end

return Notifications
end

-- ==========================================================================
-- Components/Section
-- ==========================================================================
__modules["Components/Section"] = function()
--[[
	Section / Card
	A titled card inside a page column. All element factory methods live here.

	  local Sec = Tab:AddSection("ESP")
	  local Sec = Page:AddSection({ Title = "Aimbot", Icon = "target", Description = "...",
	                                Side = "Left" | "Right", Collapsible = false })
	  Page:AddCard({...})  -- same as AddSection (title optional)
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Maid = Import("Maid")
local Animations = Import("Animations")

local Create = Utility.Create

local Section = {}
Section.__index = Section

function Section.new(page: any, options: any)
	local opts = if type(options) == "string" then { Title = options } else options or {}
	local self = setmetatable({}, Section)
	self.Page = page
	self.Window = page.Window
	self.Options = opts
	self.Elements = {} :: { any }
	self.Maid = Maid.new()
	self._order = 0
	self.Collapsed = false

	local root = Create("Frame", {
		Name = "Section_" .. tostring(opts.Title or "Card"),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	})
	self.Root = root
	self.Maid:Give(root)
	Kit.Panel(root, "Card", "Panel")
	Kit.Corner(root, 1)
	Kit.Stroke(root, "Border")
	Kit.Padding(root, "Section")
	Kit.List(root, "Vertical", "Gap")

	if opts.Title or opts.Icon then
		local header = Create("TextButton", {
			Name = "Header",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 0,
			Parent = root,
		})
		local offset = 0
		if opts.Icon then
			local badge = Create("Frame", {
				Size = UDim2.fromOffset(26, 26),
				Parent = header,
			})
			Kit.Bind(badge, "BackgroundColor3", opts.IconColor or "Accent")
			Kit.Bind(badge, "BackgroundTransparency", { "Accent" }, function()
				return 0.85
			end)
			Kit.Corner(badge, 0.6)
			Kit.Icon(opts.Icon, {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.fromOffset(14, 14),
				Parent = badge,
			}, opts.IconColor or "Accent")
			offset = 34
		end
		local texts = Create("Frame", {
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(offset, 0),
			Size = UDim2.new(1, -offset - (if opts.Collapsible then 20 else 0), 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Parent = header,
		})
		Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 1), Parent = texts })
		Create("UISizeConstraint", { MinSize = Vector2.new(0, 26), Parent = texts })
		self.TitleLabel = Kit.Label({
			Text = tostring(opts.Title or ""),
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 1,
			Parent = texts,
		}, "Heading", "Text")
		if opts.Description then
			Kit.Label({
				Text = tostring(opts.Description),
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				TextWrapped = true,
				TextTruncate = Enum.TextTruncate.None,
				LayoutOrder = 2,
				Parent = texts,
			}, "Small", "TextMuted")
		end
		if opts.Collapsible then
			local chevron = Kit.Icon("chevron-down", {
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, 0, 0, 6),
				Size = UDim2.fromOffset(12, 12),
				Parent = header,
			}, "TextMuted")
			self.Chevron = chevron
			self.Maid:Give(header.MouseButton1Click:Connect(function()
				self:SetCollapsed(not self.Collapsed)
			end))
		end
		self.Header = header
	end

	local container = Create("Frame", {
		Name = "Container",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = root,
	})
	Kit.List(container, "Vertical", "Gap")
	self.Container = container

	if opts.Collapsed then
		self:SetCollapsed(true)
	end
	return self
end

function Section:_NextOrder(): number
	self._order += 1
	return self._order
end

function Section:_Add(element: any): any
	table.insert(self.Elements, element)
	return element
end

function Section:_RemoveElement(element: any)
	local index = table.find(self.Elements, element)
	if index then
		table.remove(self.Elements, index)
	end
end

function Section:SetCollapsed(collapsed: boolean)
	self.Collapsed = collapsed
	self.Container.Visible = not collapsed
	if self.Chevron then
		Animations.Tween(self.Chevron, { Rotation = if collapsed then -90 else 0 }, 0.2)
	end
end

function Section:SetTitle(text: string)
	if self.TitleLabel then
		self.TitleLabel.Text = text
	end
end

function Section:SetVisible(visible: boolean)
	self.Root.Visible = visible
end

function Section:Destroy()
	for _, element in table.clone(self.Elements) do
		element:Destroy()
	end
	self.Maid:Clean()
	if self.Page then
		self.Page:_RemoveSection(self)
	end
end

------------------------------------------------------------------------------
-- Element factories
------------------------------------------------------------------------------
local function factory(moduleName: string, member: string?, defaults: { [string]: any }?)
	return function(self, options: any)
		local opts = options
		if defaults then
			opts = if type(options) == "table" then table.clone(options) else { Title = options }
			for k, v in defaults do
				if opts[k] == nil then
					opts[k] = v
				end
			end
		end
		local module = Import(moduleName)
		local class = if member then module[member] else module
		return self:_Add(class.new(self, opts))
	end
end

Section.AddButton = factory("Components/Button")
Section.AddToggle = factory("Components/Toggle")
Section.AddCheckbox = factory("Components/Toggle", nil, { Style = "Checkbox" })
Section.AddSlider = factory("Components/Slider")
Section.AddDropdown = factory("Components/Dropdown")
Section.AddTextbox = factory("Components/Textbox")
Section.AddInput = Section.AddTextbox
Section.AddKeybind = factory("Components/Keybind")
Section.AddColorPicker = factory("Components/ColorPicker")
Section.AddColorpicker = Section.AddColorPicker
Section.AddLabel = factory("Components/Display", "Label")
Section.AddParagraph = factory("Components/Display", "Paragraph")
Section.AddDivider = factory("Components/Display", "Divider")
Section.AddTags = factory("Components/Display", "Tags")
Section.AddStatusCard = factory("Components/Display", "StatusCard")
Section.AddStatCard = factory("Components/Chart", "StatCard")
Section.AddChart = factory("Components/Chart", "LineChart")

function Section:AddESPPreview(options: any)
	return self:_Add(Import("ESPPreview").new(self, options))
end

local _ = Theme

return Section
end

-- ==========================================================================
-- Components/Slider
-- ==========================================================================
__modules["Components/Slider"] = function()
--[[
	Slider
	  Section:AddSlider({
	      Title, Description, Flag, Min = 0, Max = 100, Increment = 1, Default = 50,
	      Suffix = "%", Decimals = nil (derived from Increment), Callback = function(v) end,
	      Tooltip, IgnoreConfig, NoCallbackOnLoad,
	  })
	Drag with mouse or touch (ancestor scrolling is locked while dragging), click the
	value to type an exact number.
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Element = Import("Components/Element")

local Create = Utility.Create

local Slider = setmetatable({}, { __index = Element })
Slider.__index = Slider

local TRACK_ZONE = 18 -- vertical space reserved for the track below the title

function Slider.new(section: any, options: { [string]: any })
	local self = Element.new(section, options, "Slider", Slider)
	local o = self.Options
	self.Min = tonumber(o.Min) or 0
	self.Max = tonumber(o.Max) or 100
	if self.Max < self.Min then
		self.Min, self.Max = self.Max, self.Min
	end
	self.Increment = math.max(tonumber(o.Increment) or 1, 0)
	self.Decimals = o.Decimals or (if self.Increment > 0 then Utility.DecimalsOf(self.Increment) else 2)
	self.Suffix = o.Suffix or ""
	self.Value = self:_Clean(tonumber(o.Default) or self.Min)

	self:_BuildRow({ ControlWidth = 86, ExtraHeight = TRACK_ZONE })

	-- value box (click to edit)
	local valueBox = Kit.TextBox({
		Name = "Value",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, 24),
		TextXAlignment = Enum.TextXAlignment.Right,
		Parent = self.Control,
	}, "Mono")
	self.ValueBox = valueBox

	-- track
	local trackHolder = Create("Frame", {
		Name = "TrackHolder",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, -4),
		Size = UDim2.new(1, 0, 0, TRACK_ZONE),
		Parent = self.Main,
	})
	Kit.Padding(trackHolder, "Inner", 0)
	local track = Create("Frame", {
		Name = "Track",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.new(1, 0, 0, 6),
		Parent = trackHolder,
	})
	Kit.Panel(track, "SliderTrack", "Free")
	Kit.Corner(track, "pill")
	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		Parent = track,
	})
	Kit.AccentFill(fill, "Progress", "SliderFill")
	Kit.Corner(fill, "pill")
	local knob = Create("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(14, 14),
		ZIndex = 3,
		Parent = track,
	})
	Kit.Corner(knob, "pill")
	Kit.Bind(knob, "BackgroundColor3", "ToggleKnob")
	local knobStroke = Kit.Stroke(knob, "SliderFill", { Always = true })
	knobStroke.Thickness = 2
	Kit.Bind(knobStroke, "Thickness", { "BorderThickness" }, function()
		return 2
	end)
	local knobScale = Create("UIScale", { Parent = knob })
	self.Track, self.Fill, self.Knob, self.KnobScale = track, fill, knob, knobScale

	-- generous touch hitbox around the track
	local hitbox = Create("TextButton", {
		Name = "Hitbox",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, -6, 0.5, 0),
		Size = UDim2.new(1, 12, 0, 30),
		ZIndex = 4,
		Parent = track,
	})

	local function fromPosition(pos: Vector2)
		local absPos, absSize = track.AbsolutePosition, track.AbsoluteSize
		if absSize.X <= 0 then
			return
		end
		local alpha = math.clamp((pos.X - absPos.X) / absSize.X, 0, 1)
		self:Set(self.Min + (self.Max - self.Min) * alpha, false, false, true)
	end

	self.Maid:Give(Input.Track(hitbox, {
		Threshold = 0,
		MoveBeforeThreshold = true,
		LockScroll = true,
		Began = function(pos)
			if self.Disabled then
				return
			end
			self.Dragging = true
			self:_SetState("Focus", true)
			Animations.Tween(knobScale, { Scale = 1.3 }, 0.2, Enum.EasingStyle.Back)
			fromPosition(pos)
		end,
		Moved = function(pos)
			if self.Dragging then
				fromPosition(pos)
			end
		end,
		Ended = function()
			self.Dragging = false
			self:_SetState("Focus", false)
			Animations.Tween(knobScale, { Scale = 1 }, 0.25, Enum.EasingStyle.Back)
		end,
	}))
	self.Maid:Give(hitbox.MouseEnter:Connect(function()
		if not self.Dragging then
			Animations.Tween(knobScale, { Scale = 1.15 }, 0.15)
		end
	end))
	self.Maid:Give(hitbox.MouseLeave:Connect(function()
		if not self.Dragging then
			Animations.Tween(knobScale, { Scale = 1 }, 0.15)
		end
	end))

	-- typed input
	self.Maid:Give(valueBox.Focused:Connect(function()
		valueBox.Text = Utility.FormatNumber(self.Value, self.Decimals)
		self:_SetState("Focus", true)
	end))
	self.Maid:Give(valueBox.FocusLost:Connect(function()
		self:_SetState("Focus", false)
		local number = tonumber((string.gsub(valueBox.Text, "[^%d%.%-]", "")))
		if number and not self.Disabled then
			self:Set(number)
		end
		self:_RenderText()
	end))

	self:_Render(true)
	self:_Register()
	return self
end

function Slider:_Clean(value: number): number
	local v = math.clamp(value, self.Min, self.Max)
	if self.Increment > 0 then
		v = self.Min + Utility.Round(v - self.Min, self.Increment)
		v = math.clamp(v, self.Min, self.Max)
	end
	return tonumber(Utility.FormatNumber(v, self.Decimals)) or v
end

function Slider:_RenderText()
	if self.ValueBox:IsFocused() then
		return
	end
	self.ValueBox.Text = Utility.FormatNumber(self.Value, self.Decimals) .. self.Suffix
end

function Slider:_Render(instant: boolean?, fast: boolean?)
	local range = self.Max - self.Min
	local alpha = if range > 0 then (self.Value - self.Min) / range else 0
	local fillSize = UDim2.fromScale(alpha, 1)
	local knobPos = UDim2.fromScale(alpha, 0.5)
	if instant then
		self.Fill.Size = fillSize
		self.Knob.Position = knobPos
	else
		local duration = if fast then 0.08 else 0.25
		Animations.Tween(self.Fill, { Size = fillSize }, duration)
		Animations.Tween(self.Knob, { Position = knobPos }, duration)
	end
	self:_RenderText()
end

function Slider:Set(value: any, silent: boolean?, fromConfig: boolean?, dragging: boolean?)
	local number = tonumber(value)
	if not number then
		return
	end
	local clean = self:_Clean(number)
	if clean == self.Value then
		self:_RenderText()
		return
	end
	self.Value = clean
	self:_Render(false, dragging)
	if silent then
		self.Changed:Fire(clean)
	else
		self:_Fire(clean, fromConfig)
	end
end

function Slider:Get(): number
	return self.Value
end

function Slider:SetRange(min: number, max: number, increment: number?)
	self.Min, self.Max = min, max
	if increment then
		self.Increment = increment
		self.Decimals = Utility.DecimalsOf(increment)
	end
	self.Value = self:_Clean(self.Value)
	self:_Render(false)
end

function Slider:Deserialize(value: any)
	if type(value) == "number" then
		self:Set(value, false, true)
	end
end

local _ = Theme

return Slider
end

-- ==========================================================================
-- Components/Tab
-- ==========================================================================
__modules["Components/Tab"] = function()
--[[
	Tab, Sidebar category and Page

	  local Tab  = Win:AddTab({ Title = "Visuals", Icon = "eye", Description = "...", Tags = {...} })
	  local Sec  = Tab:AddSection("ESP")              -- sections on the tab's root page
	  local Cat  = Tab:AddCategory({ Title = "Players", Icon = "user", Collapsed = false })
	  local Page = Cat:AddPage({ Title = "ESP", Icon = "eye", Description = "...", Tags = {"Live"} })
	  local Page2 = Tab:AddPage({ Title = "Misc" })    -- sidebar entry without category
	  Page:AddSection({ Title = "Box", Side = "Right" })
	  Tab:SetBadge(true | 3 | false)

	Pages have a big title, optional tag chips and a 2-column card grid (1 column on
	mobile / narrow windows).
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Maid = Import("Maid")
local Section = Import("Components/Section")
local Display = Import("Components/Display")

local Create = Utility.Create

------------------------------------------------------------------------------
-- Page
------------------------------------------------------------------------------
local Page = {}
Page.__index = Page

function Page.new(window: any, tab: any, options: { [string]: any })
	local self = setmetatable({}, Page)
	self.Window = window
	self.Tab = tab
	self.Options = options
	self.Sections = {} :: { any }
	self.Maid = Maid.new()
	self._alternate = 0

	local scroll = Kit.Scrolling({
		Name = "Page_" .. tostring(options.Title or "Page"),
		Size = UDim2.fromScale(1, 1),
		Visible = false,
		Parent = window.Content,
	})
	self.Scroll = scroll
	self.Maid:Give(scroll)
	Kit.Padding(scroll, "Padding")
	Kit.List(scroll, "Vertical", "Section")

	-- header
	local header = Create("Frame", {
		Name = "Header",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = scroll,
	})
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), Parent = header })
	self.TitleLabel = Kit.Label({
		Text = tostring(options.Title or ""),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = header,
	}, "Display", "Text")
	self.DescriptionLabel = Kit.Label({
		Text = tostring(options.Description or ""),
		Visible = options.Description ~= nil,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		TextTruncate = Enum.TextTruncate.None,
		LayoutOrder = 2,
		Parent = header,
	}, "Small", "TextMuted")
	local tagRow = Create("Frame", {
		Name = "Tags",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 3,
		Visible = false,
		Parent = header,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		Wraps = true,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 6),
		Parent = tagRow,
	})
	Create("UIPadding", { PaddingTop = UDim.new(0, 4), Parent = tagRow })
	self.TagRow = tagRow
	self.Header = header
	if options.Tags then
		self:SetTags(options.Tags)
	end

	-- columns
	local columns = Create("Frame", {
		Name = "Columns",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Parent = scroll,
	})
	local function column(name: string): Frame
		local col = Create("Frame", {
			Name = name,
			BackgroundTransparency = 1,
			Size = UDim2.new(0.5, -6, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Parent = columns,
		})
		Kit.List(col, "Vertical", "Section")
		return col
	end
	self.Columns = columns
	self.Left = column("Left")
	self.Right = column("Right")
	self.SingleColumn = false
	self:_Relayout(true)
	return self
end

function Page:SetTags(list: { any })
	for _, child in self.TagRow:GetChildren() do
		if child:IsA("Frame") then
			child:Destroy()
		end
	end
	Display.BuildChips(self.TagRow, list)
	self.TagRow.Visible = #list > 0
end

function Page:SetTitle(text: string)
	self.TitleLabel.Text = text
end

function Page:SetDescription(text: string?)
	self.DescriptionLabel.Text = text or ""
	self.DescriptionLabel.Visible = text ~= nil and text ~= ""
end

function Page:AddSection(options: any)
	local opts = if type(options) == "string" then { Title = options } else options or {}
	local section = Section.new(self, opts)
	local side = opts.Side
	if side ~= "Left" and side ~= "Right" then
		self._alternate += 1
		side = if self._alternate % 2 == 1 then "Left" else "Right"
	end
	section.Side = side
	table.insert(self.Sections, section)
	section.Root.LayoutOrder = #self.Sections
	section.Root.Parent = if self.SingleColumn or side == "Left" then self.Left else self.Right
	if self.Tab and self.Tab._OnRootContent and self == self.Tab.RootPage then
		self.Tab:_OnRootContent()
	end
	return section
end
Page.AddCard = Page.AddSection

function Page:_RemoveSection(section: any)
	local index = table.find(self.Sections, section)
	if index then
		table.remove(self.Sections, index)
	end
end

-- Switches between 1 and 2 columns. Sections keep their creation order.
function Page:_Relayout(force: boolean?)
	local single = self.Window:IsSingleColumn()
	if single == self.SingleColumn and not force then
		return
	end
	self.SingleColumn = single
	local gap = Theme:Metric("Section")
	if single then
		self.Left.Size = UDim2.new(1, 0, 0, 0)
		self.Right.Visible = false
		for index, section in self.Sections do
			section.Root.LayoutOrder = index
			section.Root.Parent = self.Left
		end
	else
		self.Left.Size = UDim2.new(0.5, -gap / 2, 0, 0)
		self.Right.Size = UDim2.new(0.5, -gap / 2, 0, 0)
		self.Right.Position = UDim2.new(0.5, gap / 2, 0, 0)
		self.Right.Visible = true
		for index, section in self.Sections do
			section.Root.LayoutOrder = index
			section.Root.Parent = if section.Side == "Right" then self.Right else self.Left
		end
	end
end

function Page:Show(animated: boolean?)
	local scroll = self.Scroll
	scroll.Visible = true
	self:_Relayout()
	if animated ~= false and Animations.Enabled() then
		scroll.Position = UDim2.fromOffset(0, 14)
		Animations.Tween(scroll, { Position = UDim2.new() }, 0.35)
	else
		scroll.Position = UDim2.new()
	end
end

function Page:Hide()
	self.Scroll.Visible = false
end

function Page:Select()
	self.Window:SelectTab(self.Tab)
	self.Tab:ShowPage(self)
end

function Page:Destroy()
	for _, section in table.clone(self.Sections) do
		section:Destroy()
	end
	self.Maid:Clean()
end

------------------------------------------------------------------------------
-- Sidebar entry button (shared by categories and loose pages)
------------------------------------------------------------------------------
local function entryButton(tab: any, page: any, options: { [string]: any }, parent: Instance, order: number)
	local button = Create("TextButton", {
		Name = "Entry_" .. tostring(options.Title),
		Size = UDim2.new(1, 0, 0, 34),
		LayoutOrder = order,
		Parent = parent,
	})
	Kit.Bind(button, "Size", { "Spacing" }, function(T)
		return UDim2.new(1, 0, 0, math.max(Theme:Metric("Row", T) - 4, 30))
	end)
	Kit.Corner(button, 0.7)
	local hovered = false
	local function isActive(): boolean
		return tab.ActivePage == page
	end
	Kit.Bind(button, "BackgroundColor3", { "Surface", "Text" }, function(T)
		return if hovered and not isActive() then Utility.Mix(T.Surface, T.Text, 0.03) else T.Surface
	end)
	Kit.Bind(button, "BackgroundTransparency", { "SurfaceTransparency", "PanelTransparency" }, function(T)
		if isActive() then
			return Theme:Alpha("Surface", "Panel", T)
		end
		return if hovered then 0.4 else 1
	end)
	local bar = Create("Frame", {
		Name = "Bar",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(0, 3, 0, 0),
		Parent = button,
	})
	Kit.AccentFill(bar, "Accent")
	Kit.Corner(bar, "pill")
	local icon = Kit.Icon(options.Icon or "chevron-right", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 14, 0.5, 0),
		Size = UDim2.fromOffset(15, 15),
		Parent = button,
	}, "TextMuted")
	local label = Kit.Label({
		Text = tostring(options.Title or "Page"),
		Position = UDim2.fromOffset(38, 0),
		Size = UDim2.new(1, -44, 1, 0),
		Parent = button,
	}, "Body", "TextMuted")
	Kit.Bind(label, "TextColor3", { "Text", "TextMuted" }, function(T)
		return if isActive() or hovered then T.Text else T.TextMuted
	end)
	local entry = { Button = button, Bar = bar, Icon = icon, Label = label }
	function entry.Refresh(instant: boolean?)
		local active = isActive()
		Kit.Refresh(button, nil, instant)
		Kit.Refresh(label, nil, instant)
		Kit.SetIconColor(icon, if active then "Accent" else "TextMuted")
		local size = if active then UDim2.new(0, 3, 0.55, 0) else UDim2.new(0, 3, 0, 0)
		if instant then
			bar.Size = size
		else
			Animations.Tween(bar, { Size = size }, 0.3, Enum.EasingStyle.Back)
		end
	end
	button.MouseEnter:Connect(function()
		hovered = true
		entry.Refresh()
	end)
	button.MouseLeave:Connect(function()
		hovered = false
		entry.Refresh()
	end)
	button.MouseButton1Click:Connect(function()
		Kit.Sound("Click")
		tab:ShowPage(page)
		tab.Window:CloseDrawer()
	end)
	Animations.AttachPress(button, button, 0.97)
	entry.Refresh(true)
	return entry
end

------------------------------------------------------------------------------
-- Category
------------------------------------------------------------------------------
local Category = {}
Category.__index = Category

function Category.new(tab: any, options: { [string]: any }, order: number)
	local self = setmetatable({}, Category)
	self.Tab = tab
	self.Window = tab.Window
	self.Options = options
	self.Pages = {} :: { any }
	self.Collapsed = false

	local root = Create("Frame", {
		Name = "Category_" .. tostring(options.Title),
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = order,
		Parent = tab.SidebarList,
	})
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = root })
	self.Root = root

	local header = Create("TextButton", {
		Name = "Header",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 30),
		LayoutOrder = 1,
		Parent = root,
	})
	local icon = Kit.Icon(options.Icon or "folder", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 10, 0.5, 0),
		Size = UDim2.fromOffset(14, 14),
		Parent = header,
	}, "TextMuted")
	self.Icon = icon
	Kit.Label({
		Text = string.upper(tostring(options.Title or "Category")),
		Position = UDim2.fromOffset(32, 0),
		Size = UDim2.new(1, -56, 1, 0),
		Parent = header,
	}, "Tiny", "TextMuted")
	local chevron = Kit.Icon("chevron-down", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		Size = UDim2.fromOffset(11, 11),
		Parent = header,
	}, "TextMuted")
	self.Chevron = chevron

	local entries = Create("Frame", {
		Name = "Entries",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		ClipsDescendants = true,
		LayoutOrder = 2,
		Parent = root,
	})
	local list = Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = entries })
	self.Entries = entries
	self.List = list
	list:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		if not self.Collapsed and not self._animating then
			entries.Size = UDim2.new(1, 0, 0, list.AbsoluteContentSize.Y)
		end
	end)

	header.MouseButton1Click:Connect(function()
		self:SetCollapsed(not self.Collapsed)
	end)
	if options.Collapsed then
		self:SetCollapsed(true, true)
	end
	return self
end

function Category:AddPage(options: any)
	local opts = if type(options) == "string" then { Title = options } else options or {}
	local page = Page.new(self.Window, self.Tab, opts)
	page.Category = self
	page.Entry = entryButton(self.Tab, page, opts, self.Entries, #self.Pages + 1)
	table.insert(self.Pages, page)
	self.Tab:_RegisterPage(page)
	return page
end

function Category:SetCollapsed(collapsed: boolean, instant: boolean?)
	self.Collapsed = collapsed
	local target = if collapsed then 0 else self.List.AbsoluteContentSize.Y
	Animations.Tween(self.Chevron, { Rotation = if collapsed then -90 else 0 }, 0.2)
	if instant then
		self.Entries.Size = UDim2.new(1, 0, 0, target)
		return
	end
	self._animating = true
	local tween = Animations.Tween(self.Entries, { Size = UDim2.new(1, 0, 0, target) }, 0.3)
	local function done()
		self._animating = false
		if not self.Collapsed then
			self.Entries.Size = UDim2.new(1, 0, 0, self.List.AbsoluteContentSize.Y)
		end
	end
	if tween then
		tween.Completed:Once(done)
	else
		done()
	end
end

------------------------------------------------------------------------------
-- Tab
------------------------------------------------------------------------------
local Tab = {}
Tab.__index = Tab

function Tab.new(window: any, options: any)
	local opts = if type(options) == "string" then { Title = options } else options or {}
	local self = setmetatable({}, Tab)
	self.Window = window
	self.Options = opts
	self.Categories = {} :: { any }
	self.Pages = {} :: { any }
	self.LooseEntries = 0
	self.Maid = Maid.new()
	self.Badge = false

	-- tab button ---------------------------------------------------------------
	local button = Create("TextButton", {
		Name = "Tab_" .. tostring(opts.Title),
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = #window.Tabs + 1,
		Parent = window.TabStrip,
	})
	self.Button = button
	self.Maid:Give(button)
	Kit.Corner(button, 0.7)
	local hovered = false
	Kit.Bind(button, "BackgroundColor3", { "Surface", "Text" }, function(T)
		return if hovered then Utility.Mix(T.Surface, T.Text, 0.03) else T.Surface
	end)
	Kit.Bind(button, "BackgroundTransparency", { "SurfaceTransparency", "PanelTransparency" }, function(T)
		if window.ActiveTab == self then
			return Theme:Alpha("Surface", "Panel", T)
		end
		return if hovered then 0.5 else 1
	end)
	local content = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		Parent = button,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 7),
		Parent = content,
	})
	Create("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12), Parent = content })
	self.ContentHolder = content
	if opts.Icon then
		self.Icon = Kit.Icon(opts.Icon, { Size = UDim2.fromOffset(15, 15), LayoutOrder = 1, Parent = content }, "TextMuted")
	end
	self.Label = Kit.Label({
		Text = tostring(opts.Title or "Tab"),
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Parent = content,
	}, "Heading", "TextMuted")
	Kit.Bind(self.Label, "TextColor3", { "Text", "TextMuted" }, function(T)
		return if window.ActiveTab == self or hovered then T.Text else T.TextMuted
	end)
	local dot = Create("Frame", {
		Name = "Badge",
		Size = UDim2.fromOffset(7, 7),
		LayoutOrder = 3,
		Visible = false,
		Parent = content,
	})
	Kit.Corner(dot, "pill")
	Kit.Bind(dot, "BackgroundColor3", "Danger")
	self.BadgeDot = dot
	local indicator = Create("Frame", {
		Name = "Indicator",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, 0),
		Size = UDim2.new(0, 0, 0, 2),
		ZIndex = 2,
		Parent = button,
	})
	Kit.AccentFill(indicator, "Accent")
	Kit.Corner(indicator, "pill")
	self.Indicator = indicator

	button.MouseEnter:Connect(function()
		hovered = true
		self:_RefreshButton()
	end)
	button.MouseLeave:Connect(function()
		hovered = false
		self:_RefreshButton()
	end)
	button.MouseButton1Click:Connect(function()
		Kit.Sound("Click")
		window:SelectTab(self)
	end)
	Animations.AttachPress(button, button, 0.95)

	-- sidebar list -----------------------------------------------------------
	local sidebarList = Kit.Scrolling({
		Name = "Sidebar_" .. tostring(opts.Title),
		Size = UDim2.fromScale(1, 1),
		Visible = false,
		Parent = window.SidebarLists,
	})
	Kit.Padding(sidebarList, 8)
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6), Parent = sidebarList })
	self.SidebarList = sidebarList
	self.Maid:Give(sidebarList)
	local loose = Create("Frame", {
		Name = "Pages",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 0,
		Parent = sidebarList,
	})
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = loose })
	self.LooseList = loose

	-- root page --------------------------------------------------------------
	self.RootPage = Page.new(window, self, {
		Title = opts.PageTitle or opts.Title,
		Description = opts.Description,
		Tags = opts.Tags,
	})
	table.insert(self.Pages, self.RootPage)
	self.ActivePage = self.RootPage
	return self
end

function Tab:_ApplyMode(mode: string)
	-- "Top": horizontal strip with bottom indicator; "Sidebar": vertical list with left bar
	local window = self.Window
	if mode == "Sidebar" then
		self.Button.Parent = window.SidebarTabs
		self.Button.AutomaticSize = Enum.AutomaticSize.None
		self.Button.Size = UDim2.new(1, 0, 0, 34)
		self.Indicator.AnchorPoint = Vector2.new(0, 0.5)
		self.Indicator.Position = UDim2.new(0, 0, 0.5, 0)
	else
		self.Button.Parent = window.TabStrip
		self.Button.AutomaticSize = Enum.AutomaticSize.X
		self.Button.Size = UDim2.new(0, 0, 1, -12)
		self.Indicator.AnchorPoint = Vector2.new(0.5, 1)
		self.Indicator.Position = UDim2.new(0.5, 0, 1, 0)
	end
	self.Mode = mode
	self:_RefreshButton(true)
end

function Tab:_RefreshButton(instant: boolean?)
	local active = self.Window.ActiveTab == self
	Kit.Refresh(self.Button, nil, instant)
	Kit.Refresh(self.Label, nil, instant)
	if self.Icon then
		Kit.SetIconColor(self.Icon, if active then "Accent" else "TextMuted")
	end
	local target
	if self.Mode == "Sidebar" then
		target = if active then UDim2.new(0, 3, 0.55, 0) else UDim2.new(0, 3, 0, 0)
	else
		target = if active then UDim2.new(0.6, 0, 0, 2) else UDim2.new(0, 0, 0, 2)
	end
	if instant then
		self.Indicator.Size = target
	else
		Animations.Tween(self.Indicator, { Size = target }, 0.35, Enum.EasingStyle.Back)
	end
end

function Tab:_RegisterPage(page: any)
	table.insert(self.Pages, page)
	self:_OnRootContent()
	if self.ActivePage == self.RootPage and #self.RootPage.Sections == 0 then
		-- first real page becomes the default when the root page is empty
		self.ActivePage = page
	end
	if self.Window.ActiveTab == self then
		self.Window:_Layout()
		self:ShowPage(self.ActivePage, false)
	end
	self:_RefreshEntries(true)
end

-- Adds a sidebar entry for the root page once the tab uses a sidebar AND has root content
function Tab:_OnRootContent()
	if self.RootEntry or #self.Pages <= 1 or #self.RootPage.Sections == 0 then
		return
	end
	self.RootEntry = entryButton(self, self.RootPage, {
		Title = self.Options.OverviewTitle or self.Options.Title,
		Icon = self.Options.Icon or "home",
	}, self.LooseList, -1)
	self.RootPage.Entry = self.RootEntry
end

function Tab:HasSidebar(): boolean
	return #self.Pages > 1
end

function Tab:AddCategory(options: any)
	local opts = if type(options) == "string" then { Title = options } else options or {}
	local category = Category.new(self, opts, #self.Categories + 1)
	table.insert(self.Categories, category)
	return category
end

function Tab:AddPage(options: any)
	local opts = if type(options) == "string" then { Title = options } else options or {}
	local page = Page.new(self.Window, self, opts)
	self.LooseEntries += 1
	page.Entry = entryButton(self, page, opts, self.LooseList, self.LooseEntries)
	self:_RegisterPage(page)
	return page
end

function Tab:AddSection(options: any)
	return self.RootPage:AddSection(options)
end
Tab.AddCard = Tab.AddSection

function Tab:_RefreshEntries(instant: boolean?)
	for _, page in self.Pages do
		if page.Entry then
			page.Entry.Refresh(instant)
		end
	end
end

function Tab:ShowPage(page: any, animated: boolean?)
	if self.ActivePage and self.ActivePage ~= page then
		self.ActivePage:Hide()
	end
	self.ActivePage = page
	if self.Window.ActiveTab == self then
		page:Show(animated)
	end
	self:_RefreshEntries()
end

function Tab:_Show()
	self.SidebarList.Visible = true
	for _, page in self.Pages do
		if page ~= self.ActivePage then
			page:Hide()
		end
	end
	self.ActivePage:Show()
	self:_RefreshEntries(true)
	self:_RefreshButton()
end

function Tab:_Hide()
	self.SidebarList.Visible = false
	for _, page in self.Pages do
		page:Hide()
	end
	self:_RefreshButton()
end

function Tab:Select()
	self.Window:SelectTab(self)
end

function Tab:SetBadge(value: any)
	self.Badge = value
	self.BadgeDot.Visible = value ~= nil and value ~= false and value ~= 0
end

function Tab:SetTitle(text: string)
	self.Options.Title = text
	self.Label.Text = text
	self.RootPage:SetTitle(text)
end

function Tab:Destroy()
	for _, page in self.Pages do
		page:Destroy()
	end
	self.Maid:Clean()
end

return Tab
end

-- ==========================================================================
-- Components/Textbox
-- ==========================================================================
__modules["Components/Textbox"] = function()
--[[
	Textbox
	  Section:AddTextbox({
	      Title, Description, Flag, Default = "", Placeholder = "Type...",
	      Numeric = false, Min = nil, Max = nil, MaxLength = nil,
	      Finished = true,          -- callback only on focus lost (false = every change)
	      ClearOnFocus = false, Callback = function(text) end,
	  })
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Element = Import("Components/Element")

local Create = Utility.Create

local Textbox = setmetatable({}, { __index = Element })
Textbox.__index = Textbox

function Textbox.new(section: any, options: { [string]: any })
	local self = Element.new(section, options, "Textbox", Textbox)
	local o = self.Options
	self.Numeric = o.Numeric == true
	self.Finished = o.Finished ~= false
	self.Value = self:_Clean(o.Default)

	self:_BuildRow({ ControlWidth = o.Width or 160 })

	local field = Create("Frame", {
		Name = "Field",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.new(1, 0, 0, 28),
		Parent = self.Control,
	})
	Kit.Bind(field, "Size", { "Spacing" }, function(T)
		return UDim2.new(1, 0, 0, math.max(Theme:Metric("Row", T) - 12, 26))
	end)
	Kit.Panel(field, "Input", "Panel")
	Kit.Corner(field, 0.6)
	local stroke = Kit.Stroke(field, "Border", {
		Deps = { "Border", "Accent" },
		Compute = function(T)
			return if self.State.Focus then T.Accent else T.Border
		end,
	})
	table.insert(self._stateful, stroke)

	local box = Kit.TextBox({
		Name = "Input",
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -20, 1, 0),
		PlaceholderText = o.Placeholder or "Type...",
		Text = self.Value,
		ClearTextOnFocus = o.ClearOnFocus == true,
		Parent = field,
	}, if self.Numeric then "Mono" else "Small")
	self.Input = box

	self.Maid:Give(box.Focused:Connect(function()
		self:_SetState("Focus", true)
	end))
	self.Maid:Give(box.FocusLost:Connect(function(enterPressed)
		self:_SetState("Focus", false)
		if self.Disabled then
			box.Text = self.Value
			return
		end
		self:Set(box.Text)
		if enterPressed and o.OnEnter then
			Utility.SafeCallback(o.OnEnter, self.Value)
		end
	end))
	self.Maid:Give(box:GetPropertyChangedSignal("Text"):Connect(function()
		local text = box.Text
		if o.MaxLength and #text > o.MaxLength then
			box.Text = string.sub(text, 1, o.MaxLength)
			return
		end
		if self.Numeric then
			local filtered = string.gsub(text, "[^%d%.%-]", "")
			if filtered ~= text then
				box.Text = filtered
				return
			end
		end
		if not self.Finished and box:IsFocused() then
			self:Set(text)
		end
	end))

	self:_Register()
	return self
end

function Textbox:_Clean(value: any): string
	local text = if value == nil then "" else tostring(value)
	if self.Numeric then
		local number = tonumber(text)
		if not number then
			return if text == "" then "" else self.Value or ""
		end
		local o = self.Options
		if o.Min then
			number = math.max(number, o.Min)
		end
		if o.Max then
			number = math.min(number, o.Max)
		end
		return tostring(number)
	end
	return text
end

function Textbox:Set(value: any, silent: boolean?, fromConfig: boolean?)
	local clean = self:_Clean(value)
	if not self.Input:IsFocused() or self.Finished then
		self.Input.Text = clean
	end
	if clean == self.Value then
		return
	end
	self.Value = clean
	local out: any = if self.Numeric then tonumber(clean) else clean
	if silent then
		self.Changed:Fire(out)
	else
		self:_Fire(out, fromConfig)
	end
end

function Textbox:Get(): any
	if self.Numeric then
		return tonumber(self.Value)
	end
	return self.Value
end

function Textbox:Serialize(): any
	return self.Value
end

function Textbox:Deserialize(value: any)
	if type(value) == "string" or type(value) == "number" then
		self:Set(value, false, true)
	end
end

function Textbox:Focus()
	self.Input:CaptureFocus()
end

return Textbox
end

