-- Components/Toggle
-- ==========================================================================
__modules["Components/Toggle"] = function()
--[[
	Toggle (switch) + Checkbox variant
	  Section:AddToggle({
	      Title, Description, Flag, Default = false, Callback = function(state) end,
	      Style = "Switch" | "Checkbox",
	      Pinnable = true,          -- pin icon / long-press -> mobile quick toggle
	      QuickTitle = "Box",       -- short label for the quick toggle
	      Icon = "eye",             -- icon on the quick toggle
	      Tooltip, IgnoreConfig, NoCallbackOnLoad,
	  })
	  Toggle:Set(bool) :Get() :Toggle() :SetPinned(bool)
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Element = Import("Components/Element")

local Create = Utility.Create

local Toggle = setmetatable({}, { __index = Element })
Toggle.__index = Toggle

function Toggle.new(section: any, options: { [string]: any })
	local self = Element.new(section, options, "Toggle", Toggle)
	local o = self.Options
	self.Value = o.Default == true
	self.Style = if o.Style == "Checkbox" then "Checkbox" else "Switch"
	self.Pinnable = o.Pinnable == true

	local controlWidth = (if self.Style == "Checkbox" then 30 else 50) + (if self.Pinnable then 30 else 0) + 12
	self:_BuildRow({ ControlWidth = controlWidth })

	-- the whole row is clickable
	local hitbox = Kit.Hitbox(self.Main, 2)
	self.Hitbox = hitbox

	local control = self.Control
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
		Parent = control,
	})

	if self.Pinnable then
		local pin = Create("TextButton", {
			Name = "Pin",
			Size = UDim2.fromOffset(22, 22),
			BackgroundTransparency = 1,
			LayoutOrder = 1,
			ZIndex = 3,
			Parent = control,
		})
		self.PinIcon = Kit.Icon("pin", {
			Size = UDim2.fromOffset(14, 14),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 3,
			Parent = pin,
		}, "TextMuted")
		self.Maid:Give(pin.MouseButton1Click:Connect(function()
			if not self.Disabled then
				self:SetPinned(not self:IsPinned())
			end
		end))
		Animations.AttachPress(pin, pin, 0.85)
	end

	if self.Style == "Switch" then
		local track = Create("Frame", {
			Name = "Track",
			Size = UDim2.fromOffset(40, 22),
			LayoutOrder = 2,
			ZIndex = 2,
			Parent = control,
		})
		Kit.Corner(track, "pill")
		self:_Stateful(track, "BackgroundColor3", { "ToggleOn", "ToggleOff", "ProgressGradient", "AccentGradient" }, function(T)
			if not self.Value then
				return T.ToggleOff
			end
			return if Kit.GradientOn(T, "Progress") then Kit.IDENTITY else T.ToggleOn
		end)
		self:_Stateful(track, "BackgroundTransparency", { "ToggleOnTransparency", "ToggleOffTransparency" }, function(T)
			return if self.Value then T.ToggleOnTransparency else T.ToggleOffTransparency
		end)
		local gradient = Kit.Gradient(track, "Progress", "ToggleOn", function()
			return self.Value
		end)
		table.insert(self._stateful, gradient)
		local knob = Create("Frame", {
			Name = "Knob",
			AnchorPoint = Vector2.new(0, 0.5),
			Size = UDim2.fromOffset(16, 16),
			Position = UDim2.new(0, 3, 0.5, 0),
			ZIndex = 3,
			Parent = track,
		})
		Kit.Corner(knob, "pill")
		Kit.Bind(knob, "BackgroundColor3", "ToggleKnob")
		self.Track = track
		self.Knob = knob
	else
		local box = Create("Frame", {
			Name = "Box",
			Size = UDim2.fromOffset(22, 22),
			LayoutOrder = 2,
			ZIndex = 2,
			Parent = control,
		})
		Kit.Corner(box, 0.5)
		self:_Stateful(box, "BackgroundColor3", { "ToggleOn", "Input" }, function(T)
			return if self.Value then T.ToggleOn else T.Input
		end)
		local stroke = Kit.Stroke(box, "Border", {
			Always = true,
			Deps = { "Border", "ToggleOn" },
			Compute = function(T)
				return if self.Value then T.ToggleOn else T.Border
			end,
		})
		table.insert(self._stateful, stroke)
		local check = Kit.Icon("check", {
			Size = UDim2.fromOffset(14, 14),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 3,
			Parent = box,
		}, "AccentText")
		self.CheckScale = Create("UIScale", { Scale = if self.Value then 1 else 0, Parent = check })
		self.Box = box
	end

	Animations.AttachPress(hitbox, self.Root, 0.97)
	self.Maid:Give(Input.Track(hitbox, {
		LongPress = 0.5,
		LongPressed = function(pos)
			if self.Pinnable and Theme.TouchMode then
				self:SetPinned(not self:IsPinned())
			else
				self:_ShowTouchTooltip(pos)
			end
		end,
		Tap = function()
			if not self.Disabled then
				Kit.Sound("Toggle")
				self:Toggle()
			end
		end,
	}))

	self:_Render(true)
	self:_Register()
	if self.Pinnable then
		Import("Mobile/QuickToggles").Attach(self)
	end
	return self
end

function Toggle:_Render(instant: boolean?)
	for _, inst in self._stateful do
		Kit.Refresh(inst, nil, instant)
	end
	if self.Knob then
		local target = if self.Value then UDim2.new(1, -19, 0.5, 0) else UDim2.new(0, 3, 0.5, 0)
		if instant then
			self.Knob.Position = target
		else
			Animations.Tween(self.Knob, { Position = target }, 0.3, Enum.EasingStyle.Back)
			-- squash & stretch while moving
			self.Knob.Size = UDim2.fromOffset(20, 16)
			Animations.Tween(self.Knob, { Size = UDim2.fromOffset(16, 16) }, 0.3)
		end
	end
	if self.CheckScale then
		if instant then
			self.CheckScale.Scale = if self.Value then 1 else 0
		else
			Animations.Tween(self.CheckScale, { Scale = if self.Value then 1 else 0 }, 0.25, Enum.EasingStyle.Back)
		end
	end
end

function Toggle:Set(value: any, silent: boolean?, fromConfig: boolean?)
	local state = value == true
	if state == self.Value then
		return
	end
	self.Value = state
	self:_Render(false)
	if not silent then
		self:_Fire(state, fromConfig)
	else
		self.Changed:Fire(state)
	end
end

function Toggle:Get(): boolean
	return self.Value
end

function Toggle:Toggle()
	self:Set(not self.Value)
end

function Toggle:Deserialize(value: any)
	if type(value) == "boolean" then
		self:Set(value, false, true)
	end
end

------------------------------------------------------------------------------
-- Pinning (mobile quick toggles)
------------------------------------------------------------------------------
function Toggle:IsPinned(): boolean
	return Import("Mobile/QuickToggles").IsPinned(self)
end

function Toggle:SetPinned(pinned: boolean)
	if not self.Pinnable then
		return
	end
	Import("Mobile/QuickToggles").SetPinned(self, pinned)
end

-- called by QuickToggles when the pin state changes
function Toggle:_PinChanged(pinned: boolean)
	if self.PinIcon then
		Kit.SetIconColor(self.PinIcon, if pinned then "Accent" else "TextMuted")
	end
end

return Toggle
end

-- ==========================================================================
-- Components/Tooltip
-- ==========================================================================
__modules["Components/Tooltip"] = function()
--[[
	Tooltip
	One shared tooltip bubble. Desktop: hover delay, follows the mouse.
	Mobile: Tooltip.ShowAt(text, position) is triggered by a long-press.
	Disabled globally through the theme key TooltipsEnabled.
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Gui = Import("Gui")

local Create = Utility.Create
local UserInputService = Utility.Services.UserInputService

local Tooltip = {}

local bubble: Frame? = nil
local label: TextLabel? = nil
local scale: UIScale? = nil
local followConnection: RBXScriptConnection? = nil
local token = 0

local function ensure(): Frame
	if bubble and bubble.Parent then
		return bubble
	end
	bubble = Create("Frame", {
		Name = "Tooltip",
		AutomaticSize = Enum.AutomaticSize.XY,
		Size = UDim2.fromOffset(0, 0),
		Visible = false,
		Parent = Gui.Layer("Tooltip"),
	})
	local b = bubble :: Frame
	Kit.Panel(b, "Tooltip", "Free")
	Kit.Corner(b, 0.6)
	Kit.Stroke(b, "Border", { Always = true })
	Create("UIPadding", {
		PaddingLeft = UDim.new(0, 9),
		PaddingRight = UDim.new(0, 9),
		PaddingTop = UDim.new(0, 6),
		PaddingBottom = UDim.new(0, 6),
		Parent = b,
	})
	scale = Create("UIScale", { Parent = b })
	label = Kit.Label({
		AutomaticSize = Enum.AutomaticSize.XY,
		Size = UDim2.fromOffset(0, 0),
		TextWrapped = true,
		TextTruncate = Enum.TextTruncate.None,
		Parent = b,
	}, "Small", "Text")
	Create("UISizeConstraint", { MaxSize = Vector2.new(260, math.huge), Parent = label })
	return b
end

local function place(position: Vector2)
	local b = ensure()
	local viewport = Utility.Viewport()
	local size = b.AbsoluteSize
	local x = math.clamp(position.X + 14, 6, viewport.X - size.X - 6)
	local y = position.Y + 18
	if y + size.Y > viewport.Y - 6 then
		y = position.Y - size.Y - 10
	end
	b.Position = UDim2.fromOffset(x, y)
end

function Tooltip.ShowAt(text: string, position: Vector2, autoHide: number?)
	if not Theme.Values.TooltipsEnabled or text == nil or text == "" then
		return
	end
	local b = ensure()
	token += 1
	local my = token;
	(label :: TextLabel).Text = text
	b.Visible = true
	place(position)
	if scale then
		scale.Scale = 0.9
		Animations.Tween(scale, { Scale = 1 }, 0.18, Enum.EasingStyle.Back)
	end
	if autoHide then
		task.delay(autoHide, function()
			if token == my then
				Tooltip.Hide()
			end
		end)
	end
end

function Tooltip.Hide()
	token += 1
	if followConnection then
		followConnection:Disconnect()
		followConnection = nil
	end
	if bubble then
		bubble.Visible = false
	end
end

-- Attaches hover behaviour. `text` may be a string or a function returning one.
function Tooltip.Attach(gui: GuiObject, text: any): () -> ()
	local connections = {}
	local hovering = false
	local function resolve(): string?
		if type(text) == "function" then
			return text()
		end
		return text
	end
	table.insert(connections, gui.MouseEnter:Connect(function()
		if UserInputService.TouchEnabled and not UserInputService.MouseEnabled then
			return
		end
		hovering = true
		token += 1
		local my = token
		task.delay(0.4, function()
			if hovering and token == my then
				local value = resolve()
				if value and value ~= "" then
					Tooltip.ShowAt(value, UserInputService:GetMouseLocation())
					local showToken = token
					if followConnection then
						followConnection:Disconnect()
					end
					followConnection = UserInputService.InputChanged:Connect(function(input)
						if input.UserInputType == Enum.UserInputType.MouseMovement and token == showToken then
							place(UserInputService:GetMouseLocation())
						end
					end)
				end
			end
		end)
	end))
	table.insert(connections, gui.MouseLeave:Connect(function()
		hovering = false
		Tooltip.Hide()
	end))
	return function()
		hovering = false
		for _, c in connections do
			c:Disconnect()
		end
	end
end

return Tooltip
end

-- ==========================================================================
-- Components/Window
-- ==========================================================================
__modules["Components/Window"] = function()
--[[
	Window
	  local Win = UI:CreateWindow({
	      Title = "Nova", Subtitle = "Script Hub", Logo = "rbxassetid://...",
	      Theme = "Midnight" | { Preset = "Mint", Accent = Color3.fromRGB(...), CornerRadius = 12 },
	      Size = Vector2.new(780, 520), ToggleKey = Enum.KeyCode.RightShift,
	      FloatingButton = "Auto" | true | false, CloseBehavior = "Hide" | "Destroy",
	      Notifications = true,
	  })
	Layout: Topbar (logo/title | tabs | user, bell, minimize, close), Body (Sidebar |
	Content). Draggable via the topbar, resizable via the corner grip, minimizable,
	keybind to hide/show. On touch devices / narrow windows the sidebar becomes a drawer
	and pages use a single column.
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Maid = Import("Maid")
local Signal = Import("Signal")
local State = Import("State")
local Gui = Import("Gui")
local Config = Import("Config")
local Constants = Import("Constants")
local Tab = Import("Components/Tab")
local Notifications = Import("Components/Notifications")
local Dialog = Import("Components/Dialog")

local Create = Utility.Create
local UserInputService = Utility.Services.UserInputService
local Players = Utility.Services.Players

local Window = {}
Window.__index = Window

local TOPBAR_HEIGHT = 54
local MOBILE_TOPBAR_HEIGHT = 50

local LAYOUT_KEYS = {
	"WindowWidth",
	"WindowHeight",
	"UIScale",
	"SidebarWidth",
	"SidebarPosition",
	"TabPosition",
	"ShowAvatar",
	"ShowUsername",
	"Spacing",
	"TextScale",
}

------------------------------------------------------------------------------
-- Construction
------------------------------------------------------------------------------
function Window.new(options: { [string]: any }?)
	local o = options or {}
	local self = setmetatable({}, Window)
	self.Options = o
	self.Maid = Maid.new()
	self.Tabs = {} :: { any }
	self.ActiveTab = nil :: any
	self.Visible = false
	self.Minimized = false
	self.DrawerOpen = false
	self.Opened = Signal.new()
	self.Closed = Signal.new()
	self.CloseBehavior = o.CloseBehavior or "Hide"
	self.ToggleKey = Window._KeyName(o.ToggleKey) or Constants.DefaultToggleKey

	self:_ApplyThemeOptions(o)

	local layer = Gui.Layer("Windows")

	-- holder (theme scale) > inner (open/close pop scale) > shadow + main
	local holder = Create("Frame", {
		Name = "Window",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(Theme.Values.WindowWidth, Theme.Values.WindowHeight),
		Visible = false,
		Parent = layer,
	})
	self.Holder = holder
	self.Maid:Give(holder)
	self.Scale = Create("UIScale", { Parent = holder })

	local inner = Create("Frame", {
		Name = "Inner",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Parent = holder,
	})
	self.PopScale = Create("UIScale", { Parent = inner })
	Kit.Shadow(inner)

	local main = Create("Frame", {
		Name = "Main",
		Size = UDim2.fromScale(1, 1),
		ClipsDescendants = true,
		ZIndex = 1,
		Parent = inner,
	})
	self.Main = main
	Kit.Bind(main, "BackgroundColor3", { "Background", "BackgroundMode" }, function(T)
		return if T.BackgroundMode == "Gradient" then Kit.IDENTITY else T.Background
	end)
	Kit.Bind(main, "BackgroundTransparency", Theme.AlphaDeps("Background", "Window"), function(T)
		return Theme:Alpha("Background", "Window", T)
	end)
	Kit.Corner(main, 1.3)
	Kit.Stroke(main, "Border")

	-- background gradient / image
	local bgGradient = Create("UIGradient", { Parent = main })
	Kit.Bind(bgGradient, "Enabled", { "BackgroundMode" }, function(T)
		return T.BackgroundMode == "Gradient"
	end, { NoTween = true })
	Kit.Bind(bgGradient, "Color", { "BackgroundGradientStart", "BackgroundGradientEnd" }, function(T)
		return ColorSequence.new(T.BackgroundGradientStart, T.BackgroundGradientEnd)
	end, { NoTween = true })
	Kit.Bind(bgGradient, "Rotation", { "BackgroundGradientRotation" }, nil, { NoTween = true })
	Kit.AnimatedGradients[bgGradient] = true

	local bgImage = Create("ImageLabel", {
		Name = "BackgroundImage",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 1,
		Parent = main,
	})
	Kit.Corner(bgImage, 1.3)
	Kit.Bind(bgImage, "Visible", { "BackgroundMode", "BackgroundImage" }, function(T)
		return T.BackgroundMode == "Image" and T.BackgroundImage ~= ""
	end, { NoTween = true })
	Kit.Bind(bgImage, "Image", { "BackgroundImage" }, nil, { NoTween = true })
	Kit.Bind(bgImage, "ImageTransparency", { "BackgroundImageTransparency", "WindowTransparency" }, function(T)
		return 1 - (1 - T.BackgroundImageTransparency) * (1 - T.WindowTransparency)
	end)
	Kit.Bind(bgImage, "ScaleType", { "BackgroundImageScale" }, function(T)
		return (Enum.ScaleType :: any)[T.BackgroundImageScale] or Enum.ScaleType.Crop
	end, { NoTween = true })
	Kit.Bind(bgImage, "TileSize", { "BackgroundImageTileSize" }, function(T)
		return UDim2.fromOffset(T.BackgroundImageTileSize, T.BackgroundImageTileSize)
	end, { NoTween = true })

	self:_BuildTopbar()
	self:_BuildBody()
	self:_BuildResize()

	-- dialog layer (inside the window, above everything)
	local dialogLayer = Create("Frame", {
		Name = "DialogLayer",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 20,
		Visible = false,
		Parent = main,
	})
	self.DialogLayer = dialogLayer

	self:_Connect()
	self:_Layout(true)

	-- config provider: window state
	Config:RegisterProvider("Window", function()
		local p = holder.Position
		return {
			Position = { p.X.Scale, p.X.Offset, p.Y.Scale, p.Y.Offset },
			Minimized = self.Minimized,
			ToggleKey = self.ToggleKey,
		}
	end, function(data)
		if type(data) ~= "table" then
			return
		end
		if type(data.Position) == "table" and #data.Position == 4 then
			local p = data.Position
			if type(p[1]) == "number" and type(p[2]) == "number" and type(p[3]) == "number" and type(p[4]) == "number" then
				holder.Position = UDim2.new(p[1], p[2], p[3], p[4])
				self:_ClampPosition()
			end
		end
		if type(data.ToggleKey) == "string" then
			self:SetToggleKey(data.ToggleKey)
		end
		if type(data.Minimized) == "boolean" then
			self:Minimize(data.Minimized)
		end
	end)

	table.insert(State.Windows, self)
	State.MainWindow = State.MainWindow or self
	return self
end

function Window._KeyName(value: any): string?
	if typeof(value) == "EnumItem" then
		return value.Name
	end
	if type(value) == "string" and value ~= "" then
		local ok = pcall(function()
			return (Enum.KeyCode :: any)[value]
		end)
		return if ok then value else nil
	end
	return nil
end

function Window:_ApplyThemeOptions(o: { [string]: any })
	local themeOption = o.Theme
	if type(themeOption) == "string" then
		Theme:ApplyPreset(themeOption, true)
	elseif type(themeOption) == "table" then
		if type(themeOption.Preset) == "string" then
			Theme:ApplyPreset(themeOption.Preset, true)
		end
		local overrides = {}
		for key, value in themeOption do
			if key ~= "Preset" then
				overrides[key] = value
			end
		end
		Theme:SetDefaults(overrides)
	end
	local branding = {}
	if o.Title then
		branding.Title = o.Title
	end
	if o.Subtitle then
		branding.Subtitle = o.Subtitle
	end
	if o.Logo then
		branding.Logo = o.Logo
	end
	if typeof(o.Size) == "Vector2" then
		branding.WindowWidth = o.Size.X
		branding.WindowHeight = o.Size.Y
	end
	if next(branding) then
		Theme:SetDefaults(branding)
	end
end

