------------------------------------------------------------------------------
-- Resize grip
------------------------------------------------------------------------------
function Window:_BuildResize()
	local grip = Create("TextButton", {
		Name = "Resize",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.fromScale(1, 1),
		Size = UDim2.fromOffset(22, 22),
		ZIndex = 15,
		Parent = self.Main,
	})
	for i = 1, 3 do
		local dot = Create("Frame", {
			AnchorPoint = Vector2.new(1, 1),
			Position = UDim2.new(1, -4 - (i - 1) * 4, 1, -4),
			Size = UDim2.fromOffset(2, 2 + (i - 1) * 4),
			ZIndex = 15,
			Parent = grip,
		})
		Kit.Bind(dot, "BackgroundColor3", "TextMuted")
		Kit.Bind(dot, "BackgroundTransparency", { "TextMuted" }, function()
			return 0.4
		end)
	end
	self.Grip = grip
	local startSize = Vector2.zero
	local startPos = UDim2.new()
	self.Maid:Give(Input.Track(grip, {
		Threshold = 1,
		Began = function()
			startSize = Vector2.new(Theme.Values.WindowWidth, Theme.Values.WindowHeight)
			startPos = self.Holder.Position
		end,
		Moved = function(_, _, total)
			local scale = math.max(self.Scale.Scale, 0.01)
			local minSize, maxSize = Constants.MinWindowSize, Constants.MaxWindowSize
			local w = math.clamp(startSize.X + total.X / scale, minSize.X, maxSize.X)
			local h = math.clamp(startSize.Y + total.Y / scale, minSize.Y, maxSize.Y)
			local dw, dh = (w - startSize.X) * scale, (h - startSize.Y) * scale
			-- anchor is centered: move by half the growth so the top-left corner stays
			self.Holder.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + dw / 2, startPos.Y.Scale, startPos.Y.Offset + dh / 2)
			self._resizing = true
			Theme:SetMany({ WindowWidth = math.floor(w), WindowHeight = math.floor(h) }, true)
		end,
		Ended = function()
			self._resizing = false
			self:_Layout(true)
		end,
	}))
end

------------------------------------------------------------------------------
-- Connections
------------------------------------------------------------------------------
function Window:_Connect()
	self.Maid:Give(Theme:OnChanged(LAYOUT_KEYS, function(_, instant)
		self:_Layout(instant or self._resizing)
	end))
	self.Maid:Give(State.ViewportChanged:Connect(function()
		self:_Layout(true)
		self:_ClampPosition()
	end))
	self.Maid:Give(State.DeviceChanged:Connect(function()
		self:_Layout(true)
	end))
	self.Maid:Give(Theme:OnChanged({ "Blur", "BlurSize" }, function()
		self:_UpdateBlur()
	end))
	self.Maid:Give(UserInputService.InputBegan:Connect(function(input, processed)
		if processed or input.UserInputType ~= Enum.UserInputType.Keyboard then
			return
		end
		if input.KeyCode.Name == self.ToggleKey then
			self:Toggle()
		end
	end))
	-- animated gradients: one Heartbeat while enabled and the window is visible
	self.Maid:Give(Theme:OnChanged({ "GradientAnimated" }, function()
		self:_UpdateGradientAnimation()
	end))
	self.Maid:Give(function()
		if self._gradientConnection then
			self._gradientConnection:Disconnect()
		end
	end)
end

function Window:_UpdateGradientAnimation()
	local shouldRun = Theme.Values.GradientAnimated and self.Visible
	if shouldRun and not self._gradientConnection then
		local rotation = 0
		self._gradientConnection = Utility.Services.RunService.Heartbeat:Connect(function(dt)
			rotation = (rotation + dt * 60 * Theme.Values.GradientSpeed) % 360
			local base = Theme.Values.AccentGradientRotation
			for gradient in Kit.AnimatedGradients do
				if gradient.Parent and gradient.Enabled then
					gradient.Rotation = base + rotation
				end
			end
		end)
	elseif not shouldRun and self._gradientConnection then
		self._gradientConnection:Disconnect()
		self._gradientConnection = nil
		local base = Theme.Values.AccentGradientRotation
		for gradient in Kit.AnimatedGradients do
			if gradient.Parent then
				gradient.Rotation = base
			end
		end
	end
end

------------------------------------------------------------------------------
-- Layout
------------------------------------------------------------------------------
function Window:IsSingleColumn(): boolean
	if State.IsMobile then
		return true
	end
	local content = self.Content
	if content and content.AbsoluteSize.X > 0 then
		return content.AbsoluteSize.X / math.max(self.Scale.Scale, 0.01) < 520
	end
	return Theme.Values.WindowWidth - Theme.Values.SidebarWidth < 520
end

function Window:IsDrawerMode(): boolean
	return State.IsMobile or self.WindowSize.X < 600
end

function Window:_Layout(instant: boolean?)
	local T = Theme.Values
	local vp = Utility.Viewport()
	local inset = Utility.GuiInset()
	local mobile = State.IsMobile

	-- scale: theme scale x automatic fit (desktop only; mobile keeps 1:1 for touch sizes)
	local scale = T.UIScale
	if not mobile then
		scale *= math.min(1, (vp.X - 40) / T.WindowWidth, (vp.Y - inset.Y - 40) / T.WindowHeight)
	end
	scale = math.max(scale, 0.3)
	self.Scale.Scale = scale

	local width = T.WindowWidth
	local height = T.WindowHeight
	if mobile then
		width = math.min(width, (vp.X - 16) / scale)
		height = math.min(height, (vp.Y - inset.Y - 16) / scale)
	end
	self.WindowSize = Vector2.new(width, height)
	local topbarHeight = if mobile then MOBILE_TOPBAR_HEIGHT else TOPBAR_HEIGHT
	self.TopbarHeight = topbarHeight

	local holderSize = UDim2.fromOffset(width, if self.Minimized then topbarHeight else height)
	if instant then
		self.Holder.Size = holderSize
	else
		Animations.Tween(self.Holder, { Size = holderSize }, 0.3)
	end

	self.Topbar.Size = UDim2.new(1, 0, 0, topbarHeight)
	self.Body.Position = UDim2.fromOffset(0, topbarHeight)
	self.Body.Size = UDim2.new(1, 0, 1, -topbarHeight)

	-- tabs placement
	local drawer = self:IsDrawerMode()
	local tabsInSidebar = T.TabPosition == "Sidebar"
	local mode = if tabsInSidebar then "Sidebar" else "Top"
	if self.TabMode ~= mode then
		self.TabMode = mode
		for _, tab in self.Tabs do
			tab:_ApplyMode(mode)
		end
	end
	self.SidebarTabs.Visible = tabsInSidebar
	self.TabStrip.Visible = not tabsInSidebar

	-- topbar elements
	local narrow = width < 700
	self.UserBox.Visible = T.ShowAvatar or T.ShowUsername
	self.Avatar.Visible = T.ShowAvatar
	self.UserNames.Visible = T.ShowUsername and not narrow and not mobile
	self.Titles.Visible = not (mobile and width < 560)

	-- sidebar
	local hasSidebar = tabsInSidebar or (self.ActiveTab ~= nil and self.ActiveTab:HasSidebar())
	self.HasSidebar = hasSidebar
	self.MenuButton.Visible = drawer and hasSidebar
	local sidebarWidth = math.min(T.SidebarWidth, width * (if drawer then 0.82 else 0.45))
	local right = T.SidebarPosition == "Right"
	local sidebar = self.Sidebar
	sidebar.AnchorPoint = Vector2.new(if right then 1 else 0, 0)
	self.SidebarEdge.AnchorPoint = Vector2.new(if right then 0 else 1, 0)
	self.SidebarEdge.Position = UDim2.fromScale(if right then 0 else 1, 0)

	local sidebarPos, contentPos, contentSize
	if drawer or not hasSidebar then
		-- sidebar is an overlay drawer (or hidden)
		local open = drawer and hasSidebar and self.DrawerOpen
		local hiddenX = if right then UDim2.new(1, sidebarWidth + 2, 0, 0) else UDim2.new(0, -sidebarWidth - 2, 0, 0)
		local shownX = if right then UDim2.fromScale(1, 0) else UDim2.fromScale(0, 0)
		sidebarPos = if open then shownX else hiddenX
		contentPos = UDim2.new()
		contentSize = UDim2.fromScale(1, 1)
		self.Backdrop.Visible = open
		Animations.Tween(self.Backdrop, { BackgroundTransparency = if open then Theme:Alpha("Overlay", "Free") else 1 }, 0.25)
		if not open and not (drawer and hasSidebar) then
			self.DrawerOpen = false
		end
	else
		self.DrawerOpen = false
		self.Backdrop.Visible = false
		sidebarPos = if right then UDim2.fromScale(1, 0) else UDim2.fromScale(0, 0)
		contentPos = if right then UDim2.new() else UDim2.fromOffset(sidebarWidth, 0)
		contentSize = UDim2.new(1, -sidebarWidth, 1, 0)
	end
	local sidebarSize = UDim2.new(0, sidebarWidth, 1, 0)
	if instant then
		sidebar.Position, sidebar.Size = sidebarPos, sidebarSize
		self.Content.Position, self.Content.Size = contentPos, contentSize
	else
		Animations.Tween(sidebar, { Position = sidebarPos, Size = sidebarSize }, 0.35)
		Animations.Tween(self.Content, { Position = contentPos, Size = contentSize }, 0.35)
	end

	-- tab strip sits between the left and right topbar groups
	task.defer(function()
		self:_LayoutTopbar()
		self:_LayoutSidebarInner()
		for _, tab in self.Tabs do
			for _, page in tab.Pages do
				page:_Relayout()
			end
		end
	end)
end

function Window:_LayoutTopbar()
	local scale = math.max(self.Scale.Scale, 0.01)
	local leftWidth = self.TopLeft.AbsoluteSize.X / scale
	local rightWidth = self.TopRight.AbsoluteSize.X / scale
	self.TabStrip.Position = UDim2.fromOffset(leftWidth + 6, 0)
	self.TabStrip.Size = UDim2.new(1, -(leftWidth + rightWidth + 12), 1, 0)
end

-- Keeps at least part of the topbar on screen
function Window:_ClampPosition(animated: boolean?)
	local holder = self.Holder
	local vp = Utility.Viewport()
	local inset = Utility.GuiInset()
	local size = holder.AbsoluteSize
	local pos = holder.AbsolutePosition
	local minX, maxX = -size.X + 80, vp.X - 80
	local minY, maxY = inset.Y, vp.Y - 40
	local cx, cy = math.clamp(pos.X, minX, maxX), math.clamp(pos.Y, minY, maxY)
	if cx ~= pos.X or cy ~= pos.Y then
		local p = holder.Position
		local target = UDim2.new(p.X.Scale, p.X.Offset + (cx - pos.X), p.Y.Scale, p.Y.Offset + (cy - pos.Y))
		if animated then
			Animations.Tween(holder, { Position = target }, 0.3)
		else
			holder.Position = target
		end
	end
end

------------------------------------------------------------------------------
-- Drawer
------------------------------------------------------------------------------
function Window:OpenDrawer()
	if not self:IsDrawerMode() or not self.HasSidebar then
		return
	end
	self.DrawerOpen = true
	self:_Layout()
end

function Window:CloseDrawer()
	if not self.DrawerOpen then
		return
	end
	self.DrawerOpen = false
	self:_Layout()
end

function Window:ToggleDrawer()
	if self.DrawerOpen then
		self:CloseDrawer()
	else
		self:OpenDrawer()
	end
end

------------------------------------------------------------------------------
-- Tabs
------------------------------------------------------------------------------
function Window:AddTab(options: any)
	local tab = Tab.new(self, options)
	table.insert(self.Tabs, tab)
	tab:_ApplyMode(self.TabMode or "Top")
	if not self.ActiveTab then
		self:SelectTab(tab)
	else
		tab:_Hide()
	end
	return tab
end

function Window:SelectTab(tab: any)
	if self.ActiveTab == tab then
		return
	end
	local previous = self.ActiveTab
	self.ActiveTab = tab
	if previous then
		previous:_Hide()
	end
	tab:_Show()
	self:_Layout()
end

------------------------------------------------------------------------------
-- Visibility
------------------------------------------------------------------------------
function Window:_UpdateBlur()
	local enabled = Theme.Values.Blur and self.Visible and not self.Minimized
	local lighting = Utility.Services.Lighting
	if enabled then
		if not self.BlurEffect or not self.BlurEffect.Parent then
			local ok, blur = pcall(function()
				return Create("BlurEffect", { Name = Constants.Id .. "Blur", Size = 0, Parent = lighting })
			end)
			if ok then
				self.BlurEffect = blur
				self.Maid:Give(blur)
			end
		end
		if self.BlurEffect then
			Animations.Tween(self.BlurEffect, { Size = Theme.Values.BlurSize }, 0.35)
		end
	elseif self.BlurEffect then
		local blur = self.BlurEffect
		local tween = Animations.Tween(blur, { Size = 0 }, 0.25)
		if tween then
			tween.Completed:Once(function()
				if blur.Size == 0 and not (Theme.Values.Blur and self.Visible) then
					blur:Destroy()
					if self.BlurEffect == blur then
						self.BlurEffect = nil
					end
				end
			end)
		else
			blur:Destroy()
			self.BlurEffect = nil
		end
	end
end

function Window:SetVisible(visible: boolean, instant: boolean?)
	if self.Visible == visible and not instant then
		return
	end
	self.Visible = visible
	self._visToken = (self._visToken or 0) + 1
	local token = self._visToken
	if visible then
		self.Holder.Visible = true
		if instant or not Animations.Enabled() then
			self.PopScale.Scale = 1
		else
			self.PopScale.Scale = 0.85
			Animations.Tween(self.PopScale, { Scale = 1 }, 0.45, Enum.EasingStyle.Back)
		end
		self.Opened:Fire()
	else
		Import("Components/Tooltip").Hide()
		local tween = if instant then nil else Animations.Tween(self.PopScale, { Scale = 0.85 }, 0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
		local function hide()
			if self._visToken == token then
				self.Holder.Visible = false
			end
		end
		if tween then
			tween.Completed:Once(hide)
		else
			hide()
		end
		self.Closed:Fire()
		Config:SaveOnClose()
	end
	self:_UpdateBlur()
	self:_UpdateGradientAnimation()
end

function Window:Toggle()
	self:SetVisible(not self.Visible)
end

function Window:Minimize(state: boolean?)
	local minimized = if state == nil then not self.Minimized else state
	self.Minimized = minimized
	self.Body.Visible = true
	self.Grip.Visible = not minimized
	local height = if minimized then self.TopbarHeight or TOPBAR_HEIGHT else self.WindowSize.Y
	local tween = Animations.Tween(self.Holder, { Size = UDim2.fromOffset(self.WindowSize.X, height) }, 0.35)
	local function done()
		if self.Minimized then
			self.Body.Visible = false
		end
	end
	if tween then
		tween.Completed:Once(done)
	else
		done()
	end
	self:_UpdateBlur()
end

function Window:SetToggleKey(key: any)
	local name = Window._KeyName(key)
	if name then
		self.ToggleKey = name
	end
end

------------------------------------------------------------------------------
-- Notifications popover (bell)
------------------------------------------------------------------------------
function Window:ToggleNotificationPanel()
	if not self.BellPanel then
		local panel = Create("Frame", {
			Name = "NotificationPanel",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -12, 0, (self.TopbarHeight or TOPBAR_HEIGHT) + 6),
			Size = UDim2.fromOffset(280, 260),
			Visible = false,
			ZIndex = 18,
			Parent = self.Main,
		})
		Kit.Panel(panel, "Card", "Free")
		Kit.Corner(panel, 1)
		Kit.Stroke(panel, "Border", { Always = true })
		Kit.Label({
			Text = "Notifications",
			Position = UDim2.fromOffset(12, 8),
			Size = UDim2.new(1, -24, 0, 20),
			ZIndex = 18,
			Parent = panel,
		}, "Heading", "Text")
		local list = Kit.Scrolling({
			Position = UDim2.fromOffset(0, 34),
			Size = UDim2.new(1, 0, 1, -40),
			ZIndex = 18,
			Parent = panel,
		})
		Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), Parent = list })
		Create("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = list })
		self.BellPanel, self.BellList = panel, list
		self.BellScale = Create("UIScale", { Parent = panel })
	end
	local panel = self.BellPanel
	if panel.Visible then
		panel.Visible = false
		return
	end
	for _, child in self.BellList:GetChildren() do
		if child:IsA("Frame") then
			child:Destroy()
		end
	end
	local colors = { Info = "Accent", Success = "Success", Warning = "Warning", Error = "Danger" }
	if #Notifications.History == 0 then
		local empty = Create("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 30), Parent = self.BellList })
		Kit.Label({ Text = "No notifications yet", Size = UDim2.fromScale(1, 1), ZIndex = 18, Parent = empty }, "Small", "TextMuted")
	end
	for index, record in Notifications.History do
		local item = Create("Frame", {
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = index,
			ZIndex = 18,
			Parent = self.BellList,
		})
		Kit.Panel(item, "Surface", "Free")
		Kit.Corner(item, 0.6)
		Kit.Padding(item, 8)
		Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = item })
		Kit.Label({
			Text = record.Title,
			Size = UDim2.new(1, 0, 0, 16),
			LayoutOrder = 1,
			ZIndex = 18,
			Parent = item,
		}, "Small", colors[record.Type] or "Accent")
		if record.Content ~= "" then
			Kit.Label({
				Text = record.Content,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				TextWrapped = true,
				TextTruncate = Enum.TextTruncate.None,
				LayoutOrder = 2,
				ZIndex = 18,
				Parent = item,
			}, "Tiny", "TextMuted")
		end
	end
	panel.Position = UDim2.new(1, -12, 0, (self.TopbarHeight or TOPBAR_HEIGHT) + 6)
	panel.Visible = true
	self.BellDot.Visible = false
	self.BellScale.Scale = 0.9
	Animations.Tween(self.BellScale, { Scale = 1 }, 0.25, Enum.EasingStyle.Back)
end

------------------------------------------------------------------------------
-- Convenience API
------------------------------------------------------------------------------
function Window:Notify(options: { [string]: any })
	return Notifications.Notify(options)
end

function Window:Dialog(options: { [string]: any })
	return Dialog.new(self, options)
end

function Window:Confirm(title: string, content: string?, confirmText: string?, style: string?): boolean
	return Dialog.Confirm(self, title, content, confirmText, style)
end

function Window:Prompt(title: string, content: string?, placeholder: string?, default: string?): string?
	return Dialog.Prompt(self, title, content, placeholder, default)
end

function Window:AddThemeTab(options: { [string]: any }?)
	return Import("Tabs/AppearanceTab").Build(self, options or {})
end

function Window:AddConfigTab(options: { [string]: any }?)
	return Import("Tabs/ConfigTab").Build(self, options or {})
end

function Window:Destroy()
	if self.Destroyed then
		return
	end
	self.Destroyed = true
	Config:SaveOnClose()
	for _, tab in self.Tabs do
		tab:Destroy()
	end
	self.Maid:Clean()
	local index = table.find(State.Windows, self)
	if index then
		table.remove(State.Windows, index)
	end
	if State.MainWindow == self then
		State.MainWindow = State.Windows[1]
	end
end

return Window
end

-- ==========================================================================
-- Config
-- ==========================================================================
__modules["Config"] = function()
--[[
	Config
	Flag registry + persistence.

	Every element created with a `Flag` registers itself here. Elements implement
	  element.Type                 ("Toggle", "Slider", ...)
	  element:Serialize()   -> JSON-safe value
	  element:Deserialize(v)       (applies the value and fires the callback unless
	                                element.NoCallbackOnLoad is set)
	Elements with `IgnoreConfig = true` are reachable through UI:GetFlag but never
	saved or loaded.

	Additional state (theme, window, mobile buttons...) is stored through
	"providers": Config:RegisterProvider(name, saveFn, loadFn).

	Storage: writefile/readfile/... (all wrapped in pcall) with an in-memory
	fallback so everything keeps working for the session when the executor has no
	file API.

	Layout on disk:
	  <Id>/settings.json
	  <Id>/themes/<name>.json
	  <Id>/<GameName_PlaceId>/configs/<name>.json
]]

local Utility = Import("Utility")
local Constants = Import("Constants")
local Signal = Import("Signal")
local Theme = Import("Theme")

local Config = {}

Config.Flags = {} :: { [string]: any } -- flag -> element
Config.Pending = {} :: { [string]: any } -- flag -> {Type, Value} waiting for its element
Config.Providers = {} :: { [string]: { Save: () -> any, Load: (any) -> () } }
Config.PendingProviders = {} :: { [string]: any }
Config.ReservedKeys = { Version = true, Library = true, Name = true, SavedAt = true, Game = true, Flags = true, Theme = true }
Config.Changed = Signal.new() -- config list / autoload changed
Config.Saved = Signal.new() -- (name, timestamp)
Config.Loaded = Signal.new() -- (name)
Config.FlagChanged = Signal.new() -- (flag, value) - fired by elements
Config.Current = nil :: string?
Config.LastSaved = nil :: number?
Config.Initialized = false
Config.Loading = false

Config.Settings = {
	Version = Constants.ConfigVersion,
	Autoload = {} :: { [string]: string },
	AutoSave = false,
	AutoSaveInterval = 60,
	SaveOnClose = true,
	DeviceMode = "Auto",
	RememberedKey = nil :: string?,
	LastThemes = {} :: { [string]: any },
}

------------------------------------------------------------------------------
-- File system abstraction (pcall everywhere + session fallback)
------------------------------------------------------------------------------
local FS = {}
Config.FS = FS
FS.Memory = {} :: { [string]: string }

local function fn(name: string): any
	local env = (typeof(getgenv) == "function" and getgenv()) or nil
	local value = env and env[name]
	if type(value) ~= "function" then
		if name == "writefile" then
			value = writefile
		elseif name == "readfile" then
			value = readfile
		elseif name == "isfile" then
			value = isfile
		elseif name == "isfolder" then
			value = isfolder
		elseif name == "makefolder" then
			value = makefolder
		elseif name == "listfiles" then
			value = listfiles
		elseif name == "delfile" then
			value = delfile
		end
	end
	return if type(value) == "function" then value else nil
end

FS.Available = fn("writefile") ~= nil and fn("readfile") ~= nil and fn("isfile") ~= nil

function FS.MakeFolder(path: string)
	if not FS.Available then
		return
	end
	local isfolderFn, makefolderFn = fn("isfolder"), fn("makefolder")
	if not makefolderFn then
		return
	end
	pcall(function()
		if not isfolderFn or not isfolderFn(path) then
			makefolderFn(path)
		end
	end)
end

function FS.Write(path: string, content: string): boolean
	if FS.Available then
		local ok = pcall(fn("writefile"), path, content)
		if ok then
			FS.Memory[path] = nil
			return true
		end
	end
	FS.Memory[path] = content
	return true
end

function FS.Read(path: string): string?
	if FS.Memory[path] then
		return FS.Memory[path]
	end
	if FS.Available then
		local ok, result = pcall(function()
			if fn("isfile")(path) then
				return fn("readfile")(path)
			end
			return nil
		end)
		if ok and type(result) == "string" then
			return result
		end
	end
	return nil
end

function FS.Exists(path: string): boolean
	if FS.Memory[path] then
		return true
	end
	if FS.Available then
		local ok, result = pcall(fn("isfile"), path)
		return ok and result == true
	end
	return false
end

function FS.Delete(path: string)
	FS.Memory[path] = nil
	local delfileFn = fn("delfile")
	if FS.Available and delfileFn then
		pcall(delfileFn, path)
	end
end

-- Lists "*.json" file names (without extension) inside a folder
function FS.List(folder: string): { string }
	local names: { string } = {}
	local seen: { [string]: boolean } = {}
	local listfilesFn = fn("listfiles")
	if FS.Available and listfilesFn then
		local ok, files = pcall(listfilesFn, folder)
		if ok and type(files) == "table" then
			for _, file in files do
				local name = string.match(tostring(file), "([^/\\]+)%.json$")
				if name and not seen[name] then
					seen[name] = true
					table.insert(names, name)
				end
			end
		end
	end
	local prefix = folder .. "/"
	for path in FS.Memory do
		if string.sub(path, 1, #prefix) == prefix then
			local name = string.match(string.sub(path, #prefix + 1), "^([^/\\]+)%.json$")
			if name and not seen[name] then
				seen[name] = true
				table.insert(names, name)
			end
		end
	end
	table.sort(names, function(a, b)
		return string.lower(a) < string.lower(b)
	end)
	return names
end

------------------------------------------------------------------------------
-- Paths / init
------------------------------------------------------------------------------
Config.Root = Constants.Id
Config.GameKey = "Game"

function Config:Paths()
	local root = Config.Root
	local gameFolder = root .. "/" .. Config.GameKey
	return {
		Root = root,
		Game = gameFolder,
		Configs = gameFolder .. "/configs",
		Themes = root .. "/themes",
		Settings = root .. "/settings.json",
	}
end

function Config:Init()
	if Config.Initialized then
		return
	end
	Config.Initialized = true
	Config.GameKey = Utility.GameKey()
	local paths = Config:Paths()
	FS.MakeFolder(paths.Root)
	FS.MakeFolder(paths.Game)
	FS.MakeFolder(paths.Configs)
	FS.MakeFolder(paths.Themes)
	Config:LoadSettings()
end

local function notify(title: string, content: string, kind: string?)
	pcall(function()
		Import("Components/Notifications").Notify({ Title = title, Content = content, Type = kind or "Info", Duration = 5 })
	end)
end
Config._notify = notify

------------------------------------------------------------------------------
-- Settings
------------------------------------------------------------------------------
function Config:LoadSettings()
	local text = FS.Read(Config:Paths().Settings)
	if not text then
		return
	end
	local ok, data = Utility.JSONDecode(text)
	if not ok or type(data) ~= "table" then
		notify("Settings", "settings.json is damaged and was reset.", "Warning")
		return
	end
	local s = Config.Settings
	if type(data.Autoload) == "table" then
		for k, v in data.Autoload do
			if type(k) == "string" and type(v) == "string" then
				s.Autoload[k] = v
			end
		end
	end
	if type(data.AutoSave) == "boolean" then
		s.AutoSave = data.AutoSave
	end
	if type(data.AutoSaveInterval) == "number" then
		s.AutoSaveInterval = math.clamp(data.AutoSaveInterval, 10, 3600)
	end
	if type(data.SaveOnClose) == "boolean" then
		s.SaveOnClose = data.SaveOnClose
	end
	if data.DeviceMode == "Auto" or data.DeviceMode == "Mobile" or data.DeviceMode == "Desktop" then
		s.DeviceMode = data.DeviceMode
	end
	if type(data.RememberedKey) == "string" then
		s.RememberedKey = data.RememberedKey
	end
end

function Config:SaveSettings()
	local ok, json = Utility.JSONEncode(Config.Settings)
	if ok then
		FS.Write(Config:Paths().Settings, json)
	end
end

------------------------------------------------------------------------------
-- Flags
------------------------------------------------------------------------------
function Config:Register(element: any)
	local flag = element.Flag
	if type(flag) ~= "string" or flag == "" then
		return
	end
	if Config.Flags[flag] and Config.Flags[flag] ~= element then
		warn(string.format("[%s] duplicate flag '%s' - the newer element wins", Constants.Name, flag))
	end
	Config.Flags[flag] = element
	if element.IgnoreConfig then
		return
	end
	local pending = Config.Pending[flag]
	if pending ~= nil then
		Config.Pending[flag] = nil
		if pending.Type == nil or pending.Type == element.Type then
			local ok, err = pcall(element.Deserialize, element, pending.Value)
			if not ok then
				warn("[" .. Constants.Name .. "] failed to apply flag " .. flag .. ": " .. tostring(err))
			end
		end
	end
end

function Config:Unregister(element: any)
	local flag = element.Flag
	if flag and Config.Flags[flag] == element then
		Config.Flags[flag] = nil
	end
end

function Config:GetFlag(flag: string): any
	local element = Config.Flags[flag]
	if element then
		return element:Get()
	end
	return nil
end

function Config:RegisterProvider(name: string, save: () -> any, load: (any) -> ())
	Config.Providers[name] = { Save = save, Load = load }
	-- data loaded before the provider existed (e.g. autoload) is applied now
	local pending = Config.PendingProviders[name]
	if pending ~= nil then
		Config.PendingProviders[name] = nil
		local ok, err = pcall(load, pending)
		if not ok then
			warn("[" .. Constants.Name .. "] " .. name .. ": " .. tostring(err))
		end
	end
end

------------------------------------------------------------------------------
-- Collect / apply
------------------------------------------------------------------------------
function Config:Collect(name: string?): { [string]: any }
	local flags = {}
	for flag, element in Config.Flags do
		if not element.IgnoreConfig then
			local ok, value = pcall(element.Serialize, element)
			if ok and value ~= nil then
				flags[flag] = { Type = element.Type, Value = value }
			end
		end
	end
	-- keep values of flags whose elements are not created (yet)
	for flag, entry in Config.Pending do
		if flags[flag] == nil then
			flags[flag] = entry
		end
	end
	local data: { [string]: any } = {
		Version = Constants.ConfigVersion,
		Library = Constants.Id,
		Name = name or Config.Current or "default",
		SavedAt = os.time(),
		Game = { PlaceId = game.PlaceId, Key = Config.GameKey },
		Flags = flags,
		Theme = Theme:Serialize(),
	}
	for providerName, value in Config.PendingProviders do
		data[providerName] = value
	end
	for providerName, provider in Config.Providers do
		local ok, value = pcall(provider.Save)
		if ok and value ~= nil then
			data[providerName] = value
		end
	end
	return data
end

-- Upgrades older formats in place. Unknown keys are left alone (ignored later).
function Config.Migrate(data: { [string]: any }): { [string]: any }
	local version = tonumber(data.Version) or 0
	if version < 1 then
		-- v0: flat { flag = value } table without metadata
		if type(data.Flags) ~= "table" then
			local flags = {}
			for key, value in data do
				if type(key) == "string" and key ~= "Theme" and key ~= "Version" then
					flags[key] = { Value = value }
				end
			end
			data = { Flags = flags, Theme = data.Theme }
		end
		data.Version = 1
	end
	return data
end

function Config:Apply(raw: any, options: { [string]: any }?): (boolean, string?)
	if type(raw) ~= "table" then
		return false, "config is not a table"
	end
	local data = Config.Migrate(raw)
	if (tonumber(data.Version) or 0) > Constants.ConfigVersion then
		notify("Config", "This config was made with a newer version - loading what is compatible.", "Warning")
	end
	local opts = options or {}
	Config.Loading = true
	if opts.Theme ~= false and type(data.Theme) == "table" then
		Theme:ApplySerialized(data.Theme, opts.Instant)
	end
	if type(data.Flags) == "table" then
		for flag, entry in data.Flags do
			if type(flag) == "string" then
				local value = if type(entry) == "table" and entry.Value ~= nil then entry.Value else entry
				local entryType = if type(entry) == "table" then entry.Type else nil
				local element = Config.Flags[flag]
				if element then
					if not element.IgnoreConfig and (entryType == nil or entryType == element.Type) then
						local ok, err = pcall(element.Deserialize, element, value)
						if not ok then
							warn("[" .. Constants.Name .. "] flag " .. flag .. ": " .. tostring(err))
						end
					end
				else
					Config.Pending[flag] = { Type = entryType, Value = value }
				end
			end
		end
	end
	for key, value in data do
		if type(key) == "string" and not Config.ReservedKeys[key] then
			local provider = Config.Providers[key]
			if provider then
				local ok, err = pcall(provider.Load, value)
				if not ok then
					warn("[" .. Constants.Name .. "] " .. key .. ": " .. tostring(err))
				end
			else
				Config.PendingProviders[key] = value
			end
		end
	end
	Config.Loading = false
	return true
end

------------------------------------------------------------------------------
-- Public API
------------------------------------------------------------------------------
local function configPath(name: string): string
	return Config:Paths().Configs .. "/" .. name .. ".json"
end

function Config:List(): { string }
	Config:Init()
	return FS.List(Config:Paths().Configs)
end

function Config:Exists(name: string): boolean
	return FS.Exists(configPath(Utility.SanitizeFileName(name)))
end

function Config:Save(name: string?): (boolean, string?)
	Config:Init()
	local clean = Utility.SanitizeFileName(name or Config.Current or "default")
	if clean == "" then
		return false, "invalid name"
	end
	local ok, json = Utility.JSONEncode(Config:Collect(clean))
	if not ok then
		notify("Config", "Could not encode config: " .. tostring(json), "Error")
		return false, json
	end
	FS.Write(configPath(clean), json)
	Config.Current = clean
	Config.LastSaved = os.time()
	Config.Saved:Fire(clean, Config.LastSaved)
	Config.Changed:Fire()
	return true, nil
end

function Config:Load(name: string, options: { [string]: any }?): (boolean, string?)
	Config:Init()
	local clean = Utility.SanitizeFileName(name or "")
	local text = FS.Read(configPath(clean))
	if not text then
		notify("Config", "Config '" .. clean .. "' does not exist.", "Error")
		return false, "missing"
	end
	local ok, data = Utility.JSONDecode(text)
	if not ok or type(data) ~= "table" then
		notify("Config", "Config '" .. clean .. "' is damaged and was not loaded.", "Error")
		return false, "corrupted"
	end
	local applied, err = Config:Apply(data, options)
	if not applied then
		notify("Config", "Config '" .. clean .. "' could not be applied: " .. tostring(err), "Error")
		return false, err
	end
	Config.Current = clean
	Config.Loaded:Fire(clean)
	Config.Changed:Fire()
	return true, nil
end

function Config:Delete(name: string): boolean
	local clean = Utility.SanitizeFileName(name)
	FS.Delete(configPath(clean))
	if Config:GetAutoload() == clean then
		Config:SetAutoload(nil)
	end
	if Config.Current == clean then
		Config.Current = nil
	end
	Config.Changed:Fire()
	return true
end

function Config:Rename(old: string, new: string): (boolean, string?)
	local from, to = Utility.SanitizeFileName(old), Utility.SanitizeFileName(new)
	if to == "" then
		return false, "invalid name"
	end
	if Config:Exists(to) then
		return false, "exists"
	end
	local text = FS.Read(configPath(from))
	if not text then
		return false, "missing"
	end
	FS.Write(configPath(to), text)
	FS.Delete(configPath(from))
	if Config:GetAutoload() == from then
		Config:SetAutoload(to)
	end
	if Config.Current == from then
		Config.Current = to
	end
	Config.Changed:Fire()
	return true, nil
end

function Config:Duplicate(name: string, newName: string?): (boolean, string?)
	local from = Utility.SanitizeFileName(name)
	local text = FS.Read(configPath(from))
	if not text then
		return false, "missing"
	end
	local target = Utility.SanitizeFileName(newName or "")
	if target == "" then
		local index = 1
		repeat
			target = from .. " copy" .. (if index > 1 then " " .. index else "")
			index += 1
		until not Config:Exists(target)
	end
	FS.Write(configPath(target), text)
	Config.Changed:Fire()
	return true, target
end

function Config:GetInfo(name: string): { [string]: any }?
	local text = FS.Read(configPath(Utility.SanitizeFileName(name)))
	if not text then
		return nil
	end
	local ok, data = Utility.JSONDecode(text)
	if not ok or type(data) ~= "table" then
		return { Corrupted = true }
	end
	return { SavedAt = data.SavedAt, Version = data.Version }
end

-- Autoload ------------------------------------------------------------------
function Config:SetAutoload(name: string?)
	Config:Init()
	Config.Settings.Autoload[Config.GameKey] = if name then Utility.SanitizeFileName(name) else nil
	Config:SaveSettings()
	Config.Changed:Fire()
end

function Config:GetAutoload(): string?
	return Config.Settings.Autoload[Config.GameKey]
end

function Config:LoadAutoload(): boolean
	Config:Init()
	local name = Config:GetAutoload()
	if not name then
		return false
	end
	if not Config:Exists(name) then
		notify("Config", "Autoload config '" .. name .. "' was not found.", "Warning")
		return false
	end
	local ok = Config:Load(name, { Instant = true })
	if ok then
		notify("Config", "Autoloaded '" .. name .. "'", "Success")
	end
	return ok
end

-- Sharing -------------------------------------------------------------------
function Config:Export(name: string?): string?
	local data
	if name then
		local text = FS.Read(configPath(Utility.SanitizeFileName(name)))
		if not text then
			return nil
		end
		local ok, decoded = Utility.JSONDecode(text)
		if not ok then
			return nil
		end
		data = decoded
	else
		data = Config:Collect()
	end
	return Utility.EncodeShare("CFG", data)
end

function Config:Import(text: string, saveAs: string?): (boolean, string?)
	local ok, data = Utility.DecodeShare("CFG", text)
	if not ok then
		notify("Config", "Import failed: " .. tostring(data), "Error")
		return false, data
	end
	local applied, err = Config:Apply(data)
	if not applied then
		return false, err
	end
	if saveAs and saveAs ~= "" then
		Config:Save(saveAs)
	end
	return true, nil
end

-- Auto-save -----------------------------------------------------------------
local autoSaveThread: thread? = nil

function Config:SetAutoSave(enabled: boolean, interval: number?)
	Config.Settings.AutoSave = enabled
	if interval then
		Config.Settings.AutoSaveInterval = math.clamp(interval, 10, 3600)
	end
	Config:SaveSettings()
	if autoSaveThread then
		pcall(task.cancel, autoSaveThread)
		autoSaveThread = nil
	end
	if enabled then
		autoSaveThread = task.spawn(function()
			while Config.Settings.AutoSave do
				task.wait(Config.Settings.AutoSaveInterval)
				if Config.Settings.AutoSave then
					Config:Save(Config.Current or "autosave")
				end
			end
		end)
	end
end

function Config:SaveOnClose()
	if Config.Settings.SaveOnClose and Config.Current then
		Config:Save(Config.Current)
	end
end

function Config:Shutdown()
	if autoSaveThread then
		pcall(task.cancel, autoSaveThread)
		autoSaveThread = nil
	end
end

-- Themes (NovaUI/themes/*.json) ----------------------------------------------
function Config:SaveTheme(name: string): boolean
	Config:Init()
	local clean = Utility.SanitizeFileName(name)
	if clean == "" then
		return false
	end
	local ok, json = Utility.JSONEncode(Theme:Serialize())
	if not ok then
		return false
	end
	FS.Write(Config:Paths().Themes .. "/" .. clean .. ".json", json)
	Config.Changed:Fire()
	return true
end

function Config:LoadTheme(name: string): boolean
	local text = FS.Read(Config:Paths().Themes .. "/" .. Utility.SanitizeFileName(name) .. ".json")
	local ok, data = Utility.JSONDecode(text or "")
	if not ok or type(data) ~= "table" then
		notify("Theme", "Theme '" .. tostring(name) .. "' is damaged.", "Error")
		return false
	end
	return Theme:ApplySerialized(data, false)
end

function Config:DeleteTheme(name: string)
	FS.Delete(Config:Paths().Themes .. "/" .. Utility.SanitizeFileName(name) .. ".json")
	Config.Changed:Fire()
end

function Config:ListThemes(): { string }
	Config:Init()
	return FS.List(Config:Paths().Themes)
end

return Config
end

