-- ==========================================================================
__modules["Icons"] = function()
--[[
	Icons
	Icons are referenced by name ("eye", "settings"...). The active icon set comes
	from the theme key `IconSet`. A value can be
	  * a glyph / short text (rendered with a TextLabel, tinted by the theme), or
	  * an image ("rbxassetid://123") rendered with an ImageLabel (ImageColor3 tinted).
	Register your own icons (e.g. a Lucide sprite) with Icons.Register / RegisterSet.
	A raw "rbxassetid://..." passed as icon name is used directly.
]]

local Icons = {}

Icons.Sets = {
	Default = {
		home = "⌂",
		eye = "◉",
		visuals = "◉",
		target = "⊕",
		aim = "⊕",
		combat = "⚔",
		sword = "⚔",
		player = "☺",
		user = "☺",
		users = "☺",
		settings = "⚙",
		gear = "⚙",
		palette = "◐",
		brush = "✎",
		edit = "✎",
		save = "▣",
		folder = "▤",
		file = "▢",
		star = "★",
		heart = "♥",
		bell = "✉",
		info = "ℹ",
		warning = "⚠",
		error = "✕",
		success = "✓",
		check = "✓",
		close = "✕",
		x = "✕",
		minimize = "—",
		maximize = "□",
		plus = "+",
		minus = "−",
		chevron = "›",
		["chevron-down"] = "⌄",
		["chevron-right"] = "›",
		menu = "☰",
		search = "⌕",
		pin = "⚲",
		lock = "⚿",
		key = "⚿",
		globe = "◍",
		world = "◍",
		bolt = "ϟ",
		zap = "ϟ",
		flag = "⚑",
		music = "♫",
		chart = "▤",
		stats = "▥",
		activity = "∿",
		layers = "≡",
		list = "≡",
		grid = "▦",
		move = "✥",
		copy = "⧉",
		trash = "⌫",
		refresh = "↻",
		upload = "⇪",
		download = "⇩",
		link = "∞",
		clock = "◷",
		cpu = "▩",
		shield = "⛨",
		box = "▢",
		car = "◭",
		map = "▧",
		sparkles = "✦",
		magic = "✦",
		crown = "♛",
		code = "⌘",
		keyboard = "⌨",
		mobile = "▯",
		image = "▨",
		font = "Aa",
		text = "Aa",
		layout = "▤",
		shape = "◇",
		droplet = "◒",
		gradient = "◑",
		transparency = "◌",
		animation = "≋",
		brand = "◆",
		elements = "▦",
	},
	Minimal = {
		close = "×",
		minimize = "–",
		chevron = "›",
		["chevron-down"] = "⌄",
		["chevron-right"] = "›",
		menu = "≡",
		check = "✓",
		plus = "+",
		minus = "–",
		search = "⌕",
		pin = "•",
	},
	Letters = {},
}

Icons.Custom = {} :: { [string]: string }

local function isImage(value: string): boolean
	return string.find(value, "^rbxasset") ~= nil or string.find(value, "^rbxthumb") ~= nil or string.find(value, "^http") ~= nil
end

-- Registers a single icon for every set (custom icons win over set icons)
function Icons.Register(name: string, value: string | number)
	if type(value) == "number" then
		value = "rbxassetid://" .. tostring(value)
	end
	Icons.Custom[string.lower(name)] = value :: string
end

-- Registers a whole set that can be selected with the theme key IconSet
function Icons.RegisterSet(setName: string, icons: { [string]: string | number })
	local set = {}
	for name, value in icons do
		set[string.lower(name)] = if type(value) == "number" then "rbxassetid://" .. tostring(value) else value
	end
	Icons.Sets[setName] = set
end

-- Resolves an icon name for the given set. Returns ("image" | "text", value)
function Icons.Resolve(name: string?, setName: string?): (string, string)
	if name == nil or name == "" then
		return "text", ""
	end
	local raw = name :: string
	if isImage(raw) then
		return "image", raw
	end
	if string.match(raw, "^%d+$") then
		return "image", "rbxassetid://" .. raw
	end
	local key = string.lower(raw)
	local value = Icons.Custom[key]
	if value == nil then
		local set = Icons.Sets[setName or "Default"] or Icons.Sets.Default
		value = set[key]
		if value == nil and setName ~= "Letters" then
			value = Icons.Sets.Default[key]
		end
	end
	if value == nil then
		-- unknown icon / "Letters" set: first letter of the name
		value = string.upper(string.sub(raw, 1, 1))
	end
	if isImage(value) then
		return "image", value
	end
	return "text", value
end

return Icons
end

-- ==========================================================================
-- Input
-- ==========================================================================
__modules["Input"] = function()
--[[
	Input
	Unified pointer tracking for mouse AND touch.

	  Input.Track(guiObject, {
	      Threshold = 8,              -- px before a press becomes a drag
	      LongPress = 0.5,            -- seconds (nil = disabled)
	      Began = function(pos) end,  -- absolute ScreenGui positions (Vector2)
	      DragStart = function(pos) end,
	      Moved = function(pos, delta, total) end,
	      Ended = function(pos, wasDrag) end,
	      Tap = function(pos) end,
	      LongPressed = function(pos) end,
	      LockScroll = true,          -- disable ancestor ScrollingFrames while dragging
	  }) -> cleanup()

	Positions are converted to ScreenGui space (IgnoreGuiInset = true) so they can be
	compared with AbsolutePosition directly.
]]

local Utility = Import("Utility")
local Constants = Import("Constants")

local UserInputService = Utility.Services.UserInputService

local Input = {}

local function isPointerDown(input: InputObject): boolean
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function scrollingAncestors(gui: Instance): { ScrollingFrame }
	local list = {}
	local current = gui.Parent
	while current do
		if current:IsA("ScrollingFrame") then
			table.insert(list, current)
		end
		current = current.Parent
	end
	return list
end

function Input.Track(gui: GuiObject, handlers: { [string]: any }): () -> ()
	local threshold = handlers.Threshold or Constants.DragThreshold
	local connections: { RBXScriptConnection } = {}
	local active: InputObject? = nil
	local startPos = Vector2.zero
	local lastPos = Vector2.zero
	local dragging = false
	local longPressed = false
	local pressId = 0
	local lockedScrolls: { ScrollingFrame } = {}

	local function unlockScroll()
		for _, frame in lockedScrolls do
			frame.ScrollingEnabled = true
		end
		table.clear(lockedScrolls)
	end

	local function finish(position: Vector2?)
		if not active then
			return
		end
		local pos = position or lastPos
		local wasDrag = dragging
		active = nil
		dragging = false
		pressId += 1
		unlockScroll()
		if handlers.Ended then
			handlers.Ended(pos, wasDrag)
		end
		if not wasDrag and not longPressed and handlers.Tap then
			handlers.Tap(pos)
		end
	end

	table.insert(connections, gui.InputBegan:Connect(function(input: InputObject)
		if not isPointerDown(input) or active then
			return
		end
		active = input
		startPos = Utility.InputToGui(input.Position)
		lastPos = startPos
		dragging = false
		longPressed = false
		pressId += 1
		local myId = pressId
		if handlers.LockScroll then
			for _, frame in scrollingAncestors(gui) do
				if frame.ScrollingEnabled then
					frame.ScrollingEnabled = false
					table.insert(lockedScrolls, frame)
				end
			end
		end
		if handlers.Began then
			handlers.Began(startPos)
		end
		if handlers.LongPress and handlers.LongPressed then
			task.delay(handlers.LongPress, function()
				if active and pressId == myId and not dragging then
					longPressed = true
					handlers.LongPressed(lastPos)
				end
			end)
		end
	end))

	table.insert(connections, UserInputService.InputChanged:Connect(function(input: InputObject)
		local current = active
		if not current then
			return
		end
		local matches = (current.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)
			or (current.UserInputType == Enum.UserInputType.Touch and input == current)
		if not matches then
			return
		end
		local pos = Utility.InputToGui(input.Position)
		local delta = pos - lastPos
		lastPos = pos
		if not dragging then
			if (pos - startPos).Magnitude >= threshold and not longPressed then
				dragging = true
				if handlers.DragStart then
					handlers.DragStart(startPos)
				end
			elseif not handlers.MoveBeforeThreshold then
				return
			end
		end
		if handlers.Moved then
			handlers.Moved(pos, delta, pos - startPos)
		end
	end))

	table.insert(connections, UserInputService.InputEnded:Connect(function(input: InputObject)
		local current = active
		if not current then
			return
		end
		if input == current or (current.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1) then
			finish(Utility.InputToGui(input.Position))
		end
	end))

	return function()
		unlockScroll()
		for _, c in connections do
			c:Disconnect()
		end
		table.clear(connections)
	end
end

-- Makes `target` draggable by `handle`. options.OnMoved(pos), options.OnEnded(), options.Clamp
function Input.Draggable(handle: GuiObject, target: GuiObject, options: { [string]: any }?): () -> ()
	local opts = options or {}
	local startPosition: UDim2 = target.Position
	return Input.Track(handle, {
		Threshold = opts.Threshold or 2,
		Began = function()
			startPosition = target.Position
		end,
		Moved = function(_, _, total: Vector2)
			local newPos = UDim2.new(
				startPosition.X.Scale,
				startPosition.X.Offset + total.X,
				startPosition.Y.Scale,
				startPosition.Y.Offset + total.Y
			)
			if opts.Clamp then
				newPos = opts.Clamp(newPos)
			end
			target.Position = newPos
			if opts.OnMoved then
				opts.OnMoved(newPos)
			end
		end,
		Ended = function(_, wasDrag: boolean)
			if wasDrag and opts.OnEnded then
				opts.OnEnded(target.Position)
			end
		end,
		Tap = opts.OnTap,
	})
end

-- Mouse location in ScreenGui space
function Input.MousePosition(): Vector2
	return UserInputService:GetMouseLocation()
end

return Input
end

-- ==========================================================================
-- Kit
-- ==========================================================================
__modules["Kit"] = function()
--[[
	Kit
	Theme-bound building blocks. Every helper wires the created instance to theme
	keys through the registry, so components never contain colour/font/size literals.
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Registry = Import("ThemeRegistry")
local Icons = Import("Icons")
local Constants = Import("Constants")

local Create = Utility.Create

local Kit = {}

Kit.Create = Create

function Kit.Bind(inst: Instance, property: string, deps: any, compute: ((any) -> any)?, options: any?): Instance
	return Registry.Bind(inst, property, deps, compute, options)
end

function Kit.Refresh(inst: Instance, property: string?, instant: boolean?)
	Registry.Refresh(inst, property, instant)
end

------------------------------------------------------------------------------
-- Surfaces
------------------------------------------------------------------------------

-- Binds BackgroundColor3 + BackgroundTransparency of `inst` to a colour key.
-- layer: "Window" | "Panel" | "Free" (see Theme:Alpha)
function Kit.Panel(inst: GuiObject, colorKey: string, layer: string?): GuiObject
	Registry.Bind(inst, "BackgroundColor3", colorKey)
	Registry.Bind(inst, "BackgroundTransparency", Theme.AlphaDeps(colorKey, layer), function(T)
		return Theme:Alpha(colorKey, layer, T)
	end)
	return inst
end

-- Rounded corners bound to CornerRadius. factor scales the radius ("pill" = full round)
function Kit.Corner(inst: GuiObject, factor: any?): UICorner
	local corner = Create("UICorner", { Parent = inst })
	if factor == "pill" then
		corner.CornerRadius = UDim.new(1, 0)
	else
		local f = (factor or 1) :: number
		Registry.Bind(corner, "CornerRadius", "CornerRadius", function(T)
			return UDim.new(0, math.floor(T.CornerRadius * f + 0.5))
		end)
	end
	return corner
end

-- Border stroke bound to Border/BorderEnabled/BorderThickness.
-- options.Always: ignore BorderEnabled (focus rings), options.Compute: custom colour fn
function Kit.Stroke(inst: GuiObject, colorKey: string?, options: any?): UIStroke
	local key = colorKey or "Border"
	local stroke = Create("UIStroke", {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		LineJoinMode = Enum.LineJoinMode.Round,
		Parent = inst,
	})
	local deps = options and options.Deps or { key }
	Registry.Bind(stroke, "Color", deps, options and options.Compute or function(T)
		return T[key]
	end)
	Registry.Bind(stroke, "Transparency", { key .. "Transparency", "WindowTransparency" }, function(T)
		return Theme:Alpha(key, "Window", T)
	end)
	Registry.Bind(stroke, "Thickness", { "BorderEnabled", "BorderThickness" }, function(T)
		if options and options.Always then
			return math.max(T.BorderThickness, 1)
		end
		return if T.BorderEnabled then T.BorderThickness else 0
	end)
	return stroke
end

------------------------------------------------------------------------------
-- Text
------------------------------------------------------------------------------

-- Binds font, size and colour of a text instance to a text role.
function Kit.Text(inst: Instance, role: string?, colorKey: string?): Instance
	local r = role or "Body"
	Registry.Bind(inst, "FontFace", { "FontTitle", "FontBody", "FontMono", "TitleWeight", "BodyWeight" }, function(T)
		return Theme:FontFor(r, T)
	end)
	Registry.Bind(inst, "TextSize", { "TextScale" }, function(T)
		return Theme:TextSize(r, T)
	end)
	if colorKey then
		Registry.Bind(inst, "TextColor3", colorKey)
	end
	return inst
end

-- Creates a transparent TextLabel bound to a role/colour.
function Kit.Label(props: { [string]: any }, role: string?, colorKey: string?): TextLabel
	local label = Create("TextLabel", {
		BackgroundTransparency = 1,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	for key, value in props do
		if key ~= "Parent" then
			(label :: any)[key] = value
		end
	end
	Kit.Text(label, role, colorKey or "Text")
	label.Parent = props.Parent
	return label
end

-- Same for a TextBox (input fields)
function Kit.TextBox(props: { [string]: any }, role: string?): TextBox
	local box = Create("TextBox", {
		BackgroundTransparency = 1,
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	for key, value in props do
		if key ~= "Parent" then
			(box :: any)[key] = value
		end
	end
	Kit.Text(box, role, "Text")
	Registry.Bind(box, "PlaceholderColor3", "Placeholder")
	box.Parent = props.Parent
	return box
end

------------------------------------------------------------------------------
-- Layout
------------------------------------------------------------------------------

-- UIPadding bound to a spacing metric (or fixed numbers when a number is passed)
function Kit.Padding(inst: Instance, metric: any, vertical: any?): UIPadding
	local padding = Create("UIPadding", { Parent = inst })
	local function resolve(m: any, T: any): number
		if type(m) == "number" then
			return m
		end
		return Theme:Metric(m, T)
	end
	local v = if vertical == nil then metric else vertical
	Registry.Bind(padding, "PaddingLeft", { "Spacing" }, function(T)
		return UDim.new(0, resolve(metric, T))
	end)
	Registry.Bind(padding, "PaddingRight", { "Spacing" }, function(T)
		return UDim.new(0, resolve(metric, T))
	end)
	Registry.Bind(padding, "PaddingTop", { "Spacing" }, function(T)
		return UDim.new(0, resolve(v, T))
	end)
	Registry.Bind(padding, "PaddingBottom", { "Spacing" }, function(T)
		return UDim.new(0, resolve(v, T))
	end)
	return padding
end

-- UIListLayout whose padding follows a spacing metric
function Kit.List(inst: Instance, direction: string?, gap: any?, props: { [string]: any }?): UIListLayout
	local layout = Create("UIListLayout", {
		FillDirection = if direction == "Horizontal" then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = inst,
	})
	if props then
		for key, value in props do
			(layout :: any)[key] = value
		end
	end
	local g = gap or "Gap"
	if type(g) == "number" then
		layout.Padding = UDim.new(0, g)
	else
		Registry.Bind(layout, "Padding", { "Spacing" }, function(T)
			return UDim.new(0, Theme:Metric(g, T))
		end)
	end
	return layout
end

-- ScrollingFrame with themed scrollbar
function Kit.Scrolling(props: { [string]: any }): ScrollingFrame
	local frame = Create("ScrollingFrame", {
		BackgroundTransparency = 1,
		ScrollBarThickness = 3,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(),
		ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
		VerticalScrollBarInset = Enum.ScrollBarInset.None,
	})
	for key, value in props do
		if key ~= "Parent" then
			(frame :: any)[key] = value
		end
	end
	Registry.Bind(frame, "ScrollBarImageColor3", "Scrollbar")
	Registry.Bind(frame, "ScrollBarImageTransparency", "ScrollbarTransparency")
	frame.Parent = props.Parent
	return frame
end

------------------------------------------------------------------------------
-- Icons
------------------------------------------------------------------------------

-- Colour keys an icon may switch to at runtime (so theme edits refresh them)
local ICON_COLOR_KEYS = { "Text", "TextMuted", "Accent", "Accent2", "AccentText", "Success", "Warning", "Danger" }

-- Creates an icon holder (TextLabel glyph + ImageLabel) that follows IconSet.
-- Returns the holder; use Kit.SetIcon(holder, name) to change it.
function Kit.Icon(name: string?, props: { [string]: any }?, colorKey: string?): Frame
	local p = props or {}
	local holder = Create("Frame", {
		Name = "Icon",
		BackgroundTransparency = 1,
		Size = p.Size or UDim2.fromOffset(18, 18),
		Position = p.Position or UDim2.new(),
		AnchorPoint = p.AnchorPoint or Vector2.zero,
		LayoutOrder = p.LayoutOrder or 0,
		ZIndex = p.ZIndex or 1,
	})
	local glyph = Create("TextLabel", {
		Name = "Glyph",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		TextScaled = true,
		ZIndex = holder.ZIndex,
		Parent = holder,
	})
	Create("UITextSizeConstraint", { MaxTextSize = 64, Parent = glyph })
	local image = Create("ImageLabel", {
		Name = "Image",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ScaleType = Enum.ScaleType.Fit,
		ZIndex = holder.ZIndex,
		Parent = holder,
	})
	local key = colorKey or "Text"
	holder:SetAttribute("IconName", name or "")
	holder:SetAttribute("ColorKey", key)
	Registry.Bind(glyph, "FontFace", { "FontBody" }, function(T)
		return Theme.ResolveFont(T.FontBody, "Bold")
	end)
	local colorDeps = { key }
	for _, extra in ICON_COLOR_KEYS do
		table.insert(colorDeps, extra)
	end
	Registry.Bind(glyph, "TextColor3", colorDeps, function(T)
		return T[holder:GetAttribute("ColorKey") or key]
	end)
	Registry.Bind(image, "ImageColor3", colorDeps, function(T)
		return T[holder:GetAttribute("ColorKey") or key]
	end)
	Registry.Bind(glyph, "Text", { "IconSet" }, function(T)
		local kind, value = Icons.Resolve(holder:GetAttribute("IconName"), T.IconSet)
		glyph.Visible = kind == "text"
		image.Visible = kind == "image"
		if kind == "image" then
			image.Image = value
			return ""
		end
		return value
	end, { NoTween = true })
	holder.Parent = p.Parent
	return holder
end

function Kit.SetIcon(holder: Frame, name: string?)
	holder:SetAttribute("IconName", name or "")
	local glyph = holder:FindFirstChild("Glyph")
	if glyph then
		Registry.Refresh(glyph, "Text", true)
	end
end

-- Changes the colour key of an icon (e.g. active state)
function Kit.SetIconColor(holder: Frame, colorKey: string)
	holder:SetAttribute("ColorKey", colorKey)
	local glyph = holder:FindFirstChild("Glyph")
	local image = holder:FindFirstChild("Image")
	if glyph then
		Registry.Refresh(glyph, "TextColor3")
	end
	if image then
		Registry.Refresh(image, "ImageColor3")
	end
end

------------------------------------------------------------------------------
-- Gradients
------------------------------------------------------------------------------
local animatedGradients: { [UIGradient]: boolean } = setmetatable({}, { __mode = "k" }) :: any
Kit.AnimatedGradients = animatedGradients

-- Neutral multiplier: UIGradient multiplies the base colour, so a gradient-enabled
-- surface uses an identity (white) base and lets the gradient carry the theme colours.
local IDENTITY = Color3.new(1, 1, 1)

local GRADIENT_FLAG = {
	Accent = "AccentGradient",
	Button = "ButtonGradient",
	Progress = "ProgressGradient",
}

Kit.IDENTITY = IDENTITY

-- Is the gradient of a given kind active for theme values T?
function Kit.GradientOn(T: any, kind: string): boolean
	local flag = GRADIENT_FLAG[kind] or "AccentGradient"
	return T.AccentGradient == true and T[flag] == true
end

-- Adds only the UIGradient (Accent-kind colours from baseKey -> Accent2).
-- `condition()` can additionally gate it (e.g. toggle is on). Caller manages the
-- base colour (use Kit.IDENTITY while the gradient is active).
function Kit.Gradient(inst: GuiObject, kind: string, baseKey: string?, condition: (() -> boolean)?): UIGradient
	local flag = GRADIENT_FLAG[kind] or "AccentGradient"
	local base = baseKey or "Accent"
	local gradient = Create("UIGradient", { Parent = inst })
	animatedGradients[gradient] = true
	Registry.Bind(gradient, "Enabled", { flag, "AccentGradient" }, function(T)
		return Kit.GradientOn(T, kind) and (condition == nil or condition())
	end, { NoTween = true })
	Registry.Bind(gradient, "Color", { base, "Accent2" }, function(T)
		return ColorSequence.new(T[base], T.Accent2)
	end, { NoTween = true })
	Registry.Bind(gradient, "Rotation", { "AccentGradientRotation" }, function(T)
		return T.AccentGradientRotation
	end, { NoTween = true })
	return gradient
end

-- Applies an accent gradient to `inst` and manages its BackgroundColor3.
-- kind: "Accent" | "Button" | "Progress"; baseKey: solid colour when gradient is off
function Kit.AccentFill(inst: GuiObject, kind: string, baseKey: string?, layer: string?): UIGradient
	local flag = GRADIENT_FLAG[kind] or "AccentGradient"
	local base = baseKey or "Accent"
	local gradient = Kit.Gradient(inst, kind, base)
	Registry.Bind(inst, "BackgroundColor3", { base, flag, "AccentGradient" }, function(T)
		if Kit.GradientOn(T, kind) then
			return IDENTITY
		end
		return T[base]
	end)
	Registry.Bind(inst, "BackgroundTransparency", Theme.AlphaDeps(base, layer or "Free"), function(T)
		return Theme:Alpha(base, layer or "Free", T)
	end)
	return gradient
end

------------------------------------------------------------------------------
-- Shadow (layered frames, no image assets required)
------------------------------------------------------------------------------

-- Creates shadow layers inside `holder` (a transparent container that has the same
-- size as the visible panel). The panel itself must have a higher ZIndex.
function Kit.Shadow(holder: GuiObject, layers: number?, spread: number?): Frame
	local count = layers or 6
	local size = spread or 3
	local container = Create("Frame", {
		Name = "Shadow",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 0,
		Parent = holder,
	})
	Registry.Bind(container, "Visible", { "ShadowEnabled" }, nil, { NoTween = true })
	for i = 1, count do
		local grow = i * size
		local layer = Create("Frame", {
			Name = "Layer" .. i,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, math.floor(i * 0.8)),
			Size = UDim2.new(1, grow * 2, 1, grow * 2),
			ZIndex = 0,
			Parent = container,
		})
		Registry.Bind(layer, "BackgroundColor3", "Shadow")
		Registry.Bind(layer, "BackgroundTransparency", { "ShadowStrength", "ShadowTransparency", "WindowTransparency" }, function(T)
			local strength = T.ShadowStrength * (1 - T.ShadowTransparency) * (1 - T.WindowTransparency)
			local falloff = (1 - (i - 1) / count) ^ 1.6
			return 1 - math.clamp(strength * 0.16 * falloff, 0, 1)
		end)
		local corner = Create("UICorner", { Parent = layer })
		Registry.Bind(corner, "CornerRadius", { "CornerRadius" }, function(T)
			return UDim.new(0, T.CornerRadius + grow)
		end)
	end
	return container
end

------------------------------------------------------------------------------
-- Dashed border (no native dashed stroke in Roblox -> small frames)
------------------------------------------------------------------------------
function Kit.Dashed(frame: GuiObject, colorKey: string?, dash: number?, gap: number?): Frame
	local key = colorKey or "Border"
	local d = dash or 6
	local g = gap or 4
	local holder = Create("Frame", {
		Name = "Dashes",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = frame.ZIndex + 1,
		Parent = frame,
	})
	local pool: { Frame } = {}
	local function dashAt(index: number): Frame
		local item = pool[index]
		if not item then
			item = Create("Frame", { ZIndex = holder.ZIndex, Parent = holder })
			Registry.Bind(item, "BackgroundColor3", key)
			Registry.Bind(item, "BackgroundTransparency", { key .. "Transparency" }, function(T)
				return T[key .. "Transparency"] or 0
			end)
			pool[index] = item
		end
		item.Visible = true
		return item
	end
	local function rebuild()
		local size = frame.AbsoluteSize
		local thickness = 1
		local index = 0
		local inset = math.min(Theme.Values.CornerRadius * 0.6, 8)
		local function run(horizontal: boolean, fixed: number, length: number)
			local pos = inset
			while pos < length - inset do
				index += 1
				local len = math.min(d, length - inset - pos)
				local item = dashAt(index)
				if horizontal then
					item.Position = UDim2.fromOffset(pos, fixed)
					item.Size = UDim2.fromOffset(len, thickness)
				else
					item.Position = UDim2.fromOffset(fixed, pos)
					item.Size = UDim2.fromOffset(thickness, len)
				end
				pos += d + g
			end
		end
		run(true, 0, size.X)
		run(true, size.Y - thickness, size.X)
		run(false, 0, size.Y)
		run(false, size.X - thickness, size.Y)
		for i = index + 1, #pool do
			pool[i].Visible = false
		end
	end
	frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(rebuild)
	Registry.Bind(holder, "Name", { "CornerRadius" }, function()
		task.defer(rebuild)
		return "Dashes"
	end, { NoTween = true })
	return holder
end

------------------------------------------------------------------------------
-- Misc
------------------------------------------------------------------------------

-- Transparent full-size click catcher button
function Kit.Hitbox(parent: Instance, zIndex: number?): TextButton
	return Create("TextButton", {
		Name = "Hitbox",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = zIndex or 5,
		Parent = parent,
	})
end

local soundCache: { [string]: Sound } = {}
function Kit.Sound(name: string)
	local T = Theme.Values
	if not T.SoundsEnabled then
		return
	end
	local id = Constants.Sounds[name]
	if not id then
		return
	end
	pcall(function()
		local sound = soundCache[name]
		if not sound then
			sound = Create("Sound", { SoundId = id })
			soundCache[name] = sound
		end
		sound.Volume = T.SoundVolume
		Utility.Services.SoundService:PlayLocalSound(sound)
	end)
end

return Kit
end

-- ==========================================================================
-- Loader
-- ==========================================================================
__modules["Loader"] = function()
--[[
	Loader
	  UI:CreateLoader({
	      Title = "Nova", Subtitle = "Loading...", Logo = "rbxassetid://...",
	      Steps = {
	          { Text = "Loading assets", Weight = 1, Run = function(progress) ... progress(0.5) ... end },
	          { Text = "Checking game", Duration = 0.4 },
	      },
	      MinDuration = 1.5, Blur = true, Async = false,
	      KeySystem = {
	          Enabled = true, Title = "Key required", Note = "Get a key on our Discord",
	          Keys = { "KEY-123" } | Validate = function(key) return ok, message end,
	          Link = "https://...", Remember = true,
	      },
	  }) -> boolean (key valid / loader finished)

	Fullscreen overlay with blur, logo pop (Back easing) + glow pulse, typewriter
	title, gradient progress bar with shimmer and counting percentage. Steps can be
	real async functions (they receive a `progress(alpha)` reporter).
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local State = Import("State")
local Gui = Import("Gui")
local Config = Import("Config")
local Constants = Import("Constants")

local Create = Utility.Create
local RunService = Utility.Services.RunService

local Loader = {}
Loader.__index = Loader

function Loader.new(options: { [string]: any }?)
	local o = options or {}
	local self = setmetatable({}, Loader)
	self.Options = o
	self.Progress = 0
	self.Shown = 0
	self.Connections = {}

	if o.Title then
		Theme:SetDefaults({ Title = o.Title })
	end
	if o.Logo then
		Theme:SetDefaults({ Logo = o.Logo })
	end

	local layer = Gui.Layer("Loader")
	local root = Create("CanvasGroup", {
		Name = "Loader",
		Size = UDim2.fromScale(1, 1),
		GroupTransparency = 1,
		Parent = layer,
	})
	Kit.Bind(root, "BackgroundColor3", "Overlay")
	Kit.Bind(root, "BackgroundTransparency", { "Overlay", "OverlayTransparency" }, function(T)
		return math.clamp(T.OverlayTransparency + 0.1, 0, 1)
	end)
	self.Root = root

	-- blur behind
	if o.Blur ~= false then
		pcall(function()
			self.Blur = Create("BlurEffect", { Name = Constants.Id .. "LoaderBlur", Size = 0, Parent = Utility.Services.Lighting })
			Animations.Tween(self.Blur, { Size = 20 }, 0.5)
		end)
	end

	local center = Create("Frame", {
		Name = "Center",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(340, 300),
		Parent = root,
	})
	self.Center = center

	-- logo with glow
	local logoHolder = Create("Frame", {
		Name = "LogoHolder",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0),
		Size = UDim2.fromOffset(84, 84),
		Parent = center,
	})
	local glow = Create("Frame", {
		Name = "Glow",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1.5, 1.5),
		Parent = logoHolder,
	})
	Kit.Corner(glow, "pill")
	Kit.Bind(glow, "BackgroundColor3", "Accent")
	glow.BackgroundTransparency = 0.85
	self.Glow = glow
	local logo = Create("Frame", {
		Name = "Logo",
		Size = UDim2.fromScale(1, 1),
		ZIndex = 2,
		Parent = logoHolder,
	})
	Kit.AccentFill(logo, "Accent")
	Kit.Corner(logo, 2)
	local logoScale = Create("UIScale", { Scale = 0.6, Parent = logoHolder })
	self.LogoScale = logoScale
	local logoImage = Create("ImageLabel", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(0.7, 0.7),
		ScaleType = Enum.ScaleType.Fit,
		ZIndex = 3,
		Parent = logo,
	})
	local logoGlyph = Kit.Label({
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = Enum.TextXAlignment.Center,
		ZIndex = 3,
		Parent = logo,
	}, "Display", "AccentText")
	Kit.Bind(logoGlyph, "TextSize", { "TextScale" }, function(T)
		return math.floor(36 * T.TextScale)
	end)
	Kit.Bind(logoImage, "Image", { "Logo" }, function(T)
		logoImage.Visible = T.Logo ~= ""
		logoGlyph.Visible = T.Logo == ""
		return T.Logo
	end, { NoTween = true })
	Kit.Bind(logoGlyph, "Text", { "Title" }, function(T)
		return string.upper(string.sub(T.Title, 1, 1))
	end, { NoTween = true })

	-- titles
	local titleText = o.Title or (if Theme.Values.LoaderTitle ~= "" then Theme.Values.LoaderTitle else Theme.Values.Title)
	local subtitleText = o.Subtitle or (if Theme.Values.LoaderSubtitle ~= "" then Theme.Values.LoaderSubtitle else Theme.Values.Subtitle)
	self.TitleText = titleText
	self.TitleLabel = Kit.Label({
		Text = "",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 104),
		Size = UDim2.new(1, 0, 0, 30),
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = center,
	}, "Display", "Text")
	self.SubtitleLabel = Kit.Label({
		Text = subtitleText,
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 144),
		Size = UDim2.new(1, 0, 0, 18),
		TextXAlignment = Enum.TextXAlignment.Center,
		TextTransparency = 1,
		Parent = center,
	}, "Small", "TextMuted")

	-- progress
	local bar = Create("Frame", {
		Name = "Bar",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 196),
		Size = UDim2.new(0.86, 0, 0, 8),
		ClipsDescendants = true,
		Parent = center,
	})
	Kit.Panel(bar, "SliderTrack", "Free")
	Kit.Corner(bar, "pill")
	local fill = Create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		ClipsDescendants = true,
		Parent = bar,
	})
	Kit.AccentFill(fill, "Progress", "SliderFill")
	Kit.Corner(fill, "pill")
	local shimmer = Create("Frame", {
		Name = "Shimmer",
		Size = UDim2.new(0.35, 0, 1, 0),
		Position = UDim2.fromScale(-0.4, 0),
		ZIndex = 2,
		Parent = fill,
	})
	Kit.Bind(shimmer, "BackgroundColor3", "AccentText")
	Create("UIGradient", {
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.5, 0.55),
			NumberSequenceKeypoint.new(1, 1),
		}),
		Parent = shimmer,
	})
	self.Fill, self.Shimmer = fill, shimmer

	self.StatusLabel = Kit.Label({
		Text = Theme.Values.LoaderStatusText,
		Position = UDim2.new(0.07, 0, 0, 212),
		Size = UDim2.new(0.66, 0, 0, 18),
		Parent = center,
	}, "Small", "TextMuted")
	self.PercentLabel = Kit.Label({
		Text = "0%",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(0.93, 0, 0, 212),
		Size = UDim2.new(0.2, 0, 0, 18),
		TextXAlignment = Enum.TextXAlignment.Right,
		Parent = center,
	}, "Mono", "Accent")

	-- per-frame: glow pulse, shimmer and percentage counter (loader only, removed afterwards)
	local started = os.clock()
	table.insert(self.Connections, RunService.RenderStepped:Connect(function(dt)
		local t = os.clock() - started
		glow.Size = UDim2.fromScale(1.4 + math.sin(t * 2.4) * 0.12, 1.4 + math.sin(t * 2.4) * 0.12)
		glow.BackgroundTransparency = 0.82 + math.sin(t * 2.4) * 0.06
		shimmer.Position = UDim2.fromScale(((t * 0.7) % 1.6) - 0.4, 0)
		self.Shown += (self.Progress - self.Shown) * math.clamp(dt * 8, 0, 1)
		self.PercentLabel.Text = tostring(math.floor(self.Shown * 100 + 0.5)) .. "%"
		fill.Size = UDim2.fromScale(self.Shown, 1)
	end))

	return self
end

function Loader:_Intro()
	Animations.Tween(self.Root, { GroupTransparency = 0 }, 0.35)
	Animations.Tween(self.LogoScale, { Scale = 1 }, 0.7, Enum.EasingStyle.Back)
	Animations.Wait(0.25)
	-- typewriter title
	local text = self.TitleText
	local length = utf8.len(text) or #text
	for i = 1, length do
		local ok, cut = pcall(function()
			return string.sub(text, 1, (utf8.offset(text, i + 1) or (#text + 1)) - 1)
		end)
		self.TitleLabel.Text = if ok then cut else text
		if Animations.Enabled() then
			task.wait(0.035 / Animations.Speed())
		end
	end
	self.TitleLabel.Text = text
	Animations.Tween(self.SubtitleLabel, { TextTransparency = 0 }, 0.4)
end

function Loader:SetStatus(text: string)
	self.StatusLabel.Text = text
end

function Loader:SetProgress(alpha: number)
	self.Progress = math.clamp(alpha, 0, 1)
end

function Loader:_RunSteps()
	local steps = self.Options.Steps or {
		{ Text = "Loading interface", Duration = 0.35 },
		{ Text = "Applying theme", Duration = 0.3 },
		{ Text = "Reading configs", Duration = 0.3 },
	}
	local totalWeight = 0
	for _, step in steps do
		totalWeight += step.Weight or 1
	end
	local done = 0
	for _, step in steps do
		local weight = step.Weight or 1
		self:SetStatus(tostring(step.Text or "Loading..."))
		local base = done / totalWeight
		local span = weight / totalWeight
		local report = function(alpha: number)
			self:SetProgress(base + math.clamp(alpha, 0, 1) * span)
		end
		if type(step.Run) == "function" then
			local ok, err = pcall(step.Run, report, self)
			if not ok then
				warn("[" .. Constants.Name .. "] loader step failed: " .. tostring(err))
			end
		elseif step.Duration then
			local elapsed = 0
			while elapsed < step.Duration do
				elapsed += task.wait()
				report(elapsed / step.Duration)
			end
		end
		done += weight
		self:SetProgress(done / totalWeight)
	end
	-- let the counter catch up
	local timeout = os.clock() + 1.5
	while self.Shown < 0.995 and os.clock() < timeout do
		task.wait()
	end
end

------------------------------------------------------------------------------
-- Key system
------------------------------------------------------------------------------
function Loader:_Validate(key: string): (boolean, string?)
	local ks = self.Options.KeySystem
	if type(ks.Validate) == "function" then
		local ok, result, message = pcall(ks.Validate, key)
		if not ok then
			return false, "Validation error"
		end
		return result == true, message
	end
	if type(ks.Keys) == "table" then
		for _, valid in ks.Keys do
			if key == valid then
				return true, nil
			end
		end
	end
	return false, "Invalid key"
end

function Loader:_KeyScreen(): boolean
	local ks = self.Options.KeySystem
	Config:Init()
	if ks.Remember ~= false and Config.Settings.RememberedKey then
		local ok = self:_Validate(Config.Settings.RememberedKey)
		if ok then
			return true
		end
	end

	local center = self.Center
	Animations.Tween(center, { Position = UDim2.fromScale(0.5, 0.36) }, 0.45)

	local card = Create("Frame", {
		Name = "KeyCard",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.62, 30),
		Size = UDim2.fromOffset(360, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = self.Root,
	})
	Create("UISizeConstraint", { MaxSize = Vector2.new(360, math.huge), Parent = card })
	card.Size = UDim2.new(0.9, 0, 0, 0)
	Kit.Panel(card, "Card", "Free")
	Kit.Corner(card, 1.2)
	Kit.Stroke(card, "Border", { Always = true })
	Kit.Padding(card, 16)
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10), Parent = card })
	Animations.Tween(card, { Position = UDim2.new(0.5, 0, 0.62, 0) }, 0.45, Enum.EasingStyle.Back)

	Kit.Label({
		Text = ks.Title or "Key required",
		Size = UDim2.new(1, 0, 0, 22),
		LayoutOrder = 1,
		Parent = card,
	}, "Title", "Text")
	if ks.Note then
		Kit.Label({
			Text = ks.Note,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			TextTruncate = Enum.TextTruncate.None,
			LayoutOrder = 2,
			Parent = card,
		}, "Small", "TextMuted")
	end
	local field = Create("Frame", { Size = UDim2.new(1, 0, 0, 40), LayoutOrder = 3, Parent = card })
	Kit.Panel(field, "Input", "Free")
	Kit.Corner(field, 0.7)
	local fieldStroke = Kit.Stroke(field, "Border", { Always = true })
	local box = Kit.TextBox({
		Position = UDim2.fromOffset(12, 0),
		Size = UDim2.new(1, -24, 1, 0),
		PlaceholderText = "Enter key...",
		Parent = field,
	}, "Mono")
	local message = Kit.Label({
		Text = "",
		Size = UDim2.new(1, 0, 0, 14),
		LayoutOrder = 4,
		Parent = card,
	}, "Small", "Danger")

	local remember = ks.Remember ~= false
	local buttons = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 38),
		LayoutOrder = 5,
		Parent = card,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
		Parent = buttons,
	})
	local function makeButton(order: number, text: string, primary: boolean, width: number): TextButton
		local b = Create("TextButton", {
			Size = UDim2.new(width, if order == 1 then 0 else -8, 1, 0),
			LayoutOrder = order,
			ClipsDescendants = true,
			Parent = buttons,
		})
		Kit.Corner(b, 0.7)
		if primary then
			Kit.AccentFill(b, "Button")
		else
			Kit.Panel(b, "Surface", "Free")
			Kit.Stroke(b, "Border")
		end
		Kit.Label({
			Text = text,
			Size = UDim2.fromScale(1, 1),
			TextXAlignment = Enum.TextXAlignment.Center,
			Parent = b,
		}, "Heading", if primary then "AccentText" else "Text")
		Animations.AttachPress(b, b, 0.95)
		return b
	end
	local hasLink = type(ks.Link) == "string"
	local submit = makeButton(1, "Continue", true, if hasLink then 0.5 else 1)
	if hasLink then
		local getKey = makeButton(2, "Get key", false, 0.5)
		getKey.MouseButton1Click:Connect(function()
			if Utility.SetClipboard(ks.Link) then
				message.Text = "Link copied to clipboard"
				Kit.Bind(message, "TextColor3", "Success")
			else
				message.Text = ks.Link
				Kit.Bind(message, "TextColor3", "TextMuted")
			end
		end)
	end

	local thread = coroutine.running()
	local finished = false
	local function attempt()
		if finished then
			return
		end
		local key = string.match(box.Text, "^%s*(.-)%s*$") or ""
		local ok, msg = self:_Validate(key)
		if ok then
			finished = true
			Kit.Bind(fieldStroke, "Color", "Success")
			message.Text = msg or "Key accepted"
			Kit.Bind(message, "TextColor3", "Success")
			if remember then
				Config.Settings.RememberedKey = key
				Config:SaveSettings()
			end
			task.delay(0.35, function()
				Animations.Tween(card, { Position = UDim2.new(0.5, 0, 1.2, 0) }, 0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
				Animations.Tween(center, { Position = UDim2.fromScale(0.5, 0.5) }, 0.45)
				task.wait(0.4 / Animations.Speed())
				card:Destroy()
				task.spawn(thread, true)
			end)
		else
			Kit.Bind(fieldStroke, "Color", "Danger")
			message.Text = msg or "Invalid key"
			Kit.Bind(message, "TextColor3", "Danger")
			Animations.Shake(card, 10)
			Kit.Sound("Error")
		end
	end
	submit.MouseButton1Click:Connect(attempt)
	box.FocusLost:Connect(function(enter)
		if enter then
			attempt()
		end
	end)
	return coroutine.yield()
end

------------------------------------------------------------------------------
-- Lifecycle
------------------------------------------------------------------------------
function Loader:_Outro()
	Animations.Tween(self.LogoScale, { Scale = 1.15 }, 0.3)
	local tween = Animations.Tween(self.Root, { GroupTransparency = 1 }, 0.45)
	if self.Blur then
		Animations.Tween(self.Blur, { Size = 0 }, 0.45)
	end
	if tween then
		tween.Completed:Wait()
	end
	self:Destroy()
end

function Loader:Destroy()
	for _, c in self.Connections do
		c:Disconnect()
	end
	table.clear(self.Connections)
	if self.Blur then
		self.Blur:Destroy()
		self.Blur = nil
	end
	if self.Root then
		self.Root:Destroy()
	end
end

-- Runs the whole sequence. Returns false if the key system was not passed.
function Loader:Run(): boolean
	State.LoaderActive = true
	local started = os.clock()
	self:_Intro()
	local passed = true
	local ks = self.Options.KeySystem
	if type(ks) == "table" and ks.Enabled ~= false then
		self:SetStatus("Waiting for key...")
		passed = self:_KeyScreen()
	end
	if passed then
		self:_RunSteps()
		local minDuration = self.Options.MinDuration or 1.2
		local remaining = minDuration - (os.clock() - started)
		if remaining > 0 and Animations.Enabled() then
			task.wait(remaining)
		end
	end
	self:_Outro()
	State.LoaderActive = false
	State.LoaderFinished:Fire(passed)
	return passed
end

return Loader
end

-- ==========================================================================
-- Maid
-- ==========================================================================
__modules["Maid"] = function()
--[[
	Maid
	Collects connections, instances, callbacks and objects with Destroy/Disconnect
	and cleans all of them in one call. Every component owns a Maid.
]]

local Maid = {}
Maid.__index = Maid

function Maid.new()
	return setmetatable({ _tasks = {} :: { any } }, Maid)
end

-- Adds a task and returns it (handy for inline usage)
function Maid:Give(item: any): any
	if item ~= nil then
		table.insert(self._tasks, item)
	end
	return item
end

local function cleanTask(item: any)
	local kind = typeof(item)
	if kind == "RBXScriptConnection" then
		item:Disconnect()
	elseif kind == "Instance" then
		item:Destroy()
	elseif kind == "function" then
		item()
	elseif kind == "thread" then
		pcall(task.cancel, item)
	elseif kind == "table" then
		if type(item.Destroy) == "function" then
			item:Destroy()
		elseif type(item.Disconnect) == "function" then
			item:Disconnect()
		elseif type(item.Cancel) == "function" then
			item:Cancel()
		end
	end
end

function Maid:Clean()
	local tasks = self._tasks
	self._tasks = {}
	for index = #tasks, 1, -1 do
		local ok, err = pcall(cleanTask, tasks[index])
		if not ok then
			warn("[NovaUI] cleanup error: " .. tostring(err))
		end
	end
end

Maid.Destroy = Maid.Clean

return Maid
end

-- ==========================================================================
-- Mobile/Device
-- ==========================================================================
__modules["Mobile/Device"] = function()
--[[
	Device
	  * Auto detection: TouchEnabled and not KeyboardEnabled -> touch layout
	  * Manual override "Auto" | "Mobile" | "Desktop" (stored in settings.json)
	  * Safe zones: rectangles of the Roblox thumbstick and jump button so floating
	    buttons never cover them (read from PlayerGui.TouchGui when available,
	    otherwise estimated).
	  * Screen clamping that respects GuiService:GetGuiInset()
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local State = Import("State")
local Config = Import("Config")

local UserInputService = Utility.Services.UserInputService

local Device = {}
Device.Initialized = false

function Device.Detect(): boolean
	return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
end

function Device.GetMode(): string
	return Config.Settings.DeviceMode or "Auto"
end

function Device.Update()
	local mode = Device.GetMode()
	local mobile
	if mode == "Mobile" then
		mobile = true
	elseif mode == "Desktop" then
		mobile = false
	else
		mobile = Device.Detect()
	end
	if mobile ~= State.IsMobile then
		State.IsMobile = mobile
		Theme.TouchMode = mobile
		Theme:Touch({ "Spacing" })
		State.DeviceChanged:Fire(mobile)
	end
end

function Device.SetMode(mode: string)
	if mode ~= "Auto" and mode ~= "Mobile" and mode ~= "Desktop" then
		return
	end
	Config.Settings.DeviceMode = mode
	Config:SaveSettings()
	Device.Update()
end

function Device.Init()
	if Device.Initialized then
		Device.Update()
		return
	end
	Device.Initialized = true
	-- force a first evaluation
	State.IsMobile = not Device.Detect()
	Device.Update()
	State.Maid:Give(UserInputService:GetPropertyChangedSignal("KeyboardEnabled"):Connect(Device.Update))
	State.Maid:Give(UserInputService:GetPropertyChangedSignal("TouchEnabled"):Connect(Device.Update))
end

------------------------------------------------------------------------------
-- Safe zones
------------------------------------------------------------------------------
type Zone = { Min: Vector2, Max: Vector2 }

local function zoneOf(gui: GuiObject, offsetY: number, margin: number): Zone
	local pos = gui.AbsolutePosition + Vector2.new(0, offsetY)
	return {
		Min = pos - Vector2.new(margin, margin),
		Max = pos + gui.AbsoluteSize + Vector2.new(margin, margin),
	}
end

function Device.SafeZones(): { Zone }
	local zones: { Zone } = {}
	if not UserInputService.TouchEnabled then
		return zones
	end
	local found = false
	pcall(function()
		local player = Utility.Services.Players.LocalPlayer
		local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
		local touchGui = playerGui and playerGui:FindFirstChild("TouchGui")
		if not touchGui or not touchGui.Enabled then
			return
		end
		local offsetY = if touchGui.IgnoreGuiInset then 0 else Utility.GuiInset().Y
		local frame = touchGui:FindFirstChild("TouchControlFrame")
		if not frame then
			return
		end
		for _, name in { "JumpButton", "ThumbstickFrame", "DynamicThumbstickFrame" } do
			local control = frame:FindFirstChild(name)
			if control and control:IsA("GuiObject") and control.Visible and control.AbsoluteSize.X > 0 then
				table.insert(zones, zoneOf(control, offsetY, 12))
				found = true
			end
		end
	end)
	if not found then
		-- estimates for the default touch controls
		local vp = Utility.Viewport()
		local small = math.min(vp.X, vp.Y) <= 500
		local jump = if small then 70 else 120
		table.insert(zones, {
			Min = Vector2.new(vp.X - jump - (if small then 95 else 170), vp.Y - jump - (if small then 90 else 160)),
			Max = vp,
		})
		table.insert(zones, { Min = Vector2.new(0, vp.Y * 0.5), Max = Vector2.new(vp.X * 0.38, vp.Y) })
	end
	return zones
end

local function overlaps(aMin: Vector2, aMax: Vector2, zone: Zone): boolean
	return aMin.X < zone.Max.X and aMax.X > zone.Min.X and aMin.Y < zone.Max.Y and aMax.Y > zone.Min.Y
end

-- Clamps a top-left position so the element stays on screen (below the topbar inset)
function Device.ClampToScreen(position: Vector2, size: Vector2, margin: number?): Vector2
	local m = margin or 8
	local vp = Utility.Viewport()
	local inset = Utility.GuiInset()
	return Vector2.new(
		math.clamp(position.X, m, math.max(m, vp.X - size.X - m)),
		math.clamp(position.Y, inset.Y + m, math.max(inset.Y + m, vp.Y - size.Y - m))
	)
end

-- Moves an element out of thumbstick/jump zones (pushes it upwards)
function Device.AvoidZones(position: Vector2, size: Vector2): Vector2
	local pos = position
	for _ = 1, 3 do
		local moved = false
		for _, zone in Device.SafeZones() do
			if overlaps(pos, pos + size, zone) then
				pos = Vector2.new(pos.X, zone.Min.Y - size.Y - 6)
				moved = true
			end
		end
		if not moved then
			break
		end
	end
	return Device.ClampToScreen(pos, size)
end

return Device
end

-- ==========================================================================
-- Mobile/FloatingButton
-- ==========================================================================
__modules["Mobile/FloatingButton"] = function()
--[[
	FloatingButton
	Round (or square) draggable button with the logo that opens/closes the window.
	Tap = toggle window, drag = move; on release it snaps animated to the nearest
	screen edge (avoiding thumbstick / jump button). Position is stored in the config.
	Shown when CreateWindow({FloatingButton = true}) or "Auto" on touch devices.
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Maid = Import("Maid")
local State = Import("State")
local Gui = Import("Gui")
local Config = Import("Config")
local Device = Import("Mobile/Device")

local Create = Utility.Create

local FloatingButton = {}
FloatingButton.__index = FloatingButton

function FloatingButton.new(window: any, mode: any)
	local self = setmetatable({}, FloatingButton)
	self.Window = window
	self.Mode = if mode == nil then "Auto" else mode
	self.Maid = Maid.new()
	self.Side = "Right"
	self.YScale = 0.35

	local button = Create("TextButton", {
		Name = "FloatingButton",
		Size = UDim2.fromOffset(56, 56),
		Visible = false,
		ZIndex = 5,
		Parent = Gui.Layer("Mobile"),
	})
	self.Button = button
	self.Maid:Give(button)
	Kit.Bind(button, "Size", { "MobileButtonSize" }, function(T)
		return UDim2.fromOffset(T.MobileButtonSize, T.MobileButtonSize)
	end)
	Kit.Bind(button, "BackgroundColor3", "MobileButton")
	Kit.Bind(button, "BackgroundTransparency", { "MobileButtonTransparency", "MobileTransparency" }, function(T)
		return 1 - (1 - T.MobileButtonTransparency) * (1 - T.MobileTransparency)
	end)
	local corner = Create("UICorner", { Parent = button })
	Kit.Bind(corner, "CornerRadius", { "MobileButtonShape", "CornerRadius" }, function(T)
		return if T.MobileButtonShape == "Round" then UDim.new(1, 0) else UDim.new(0, T.CornerRadius + 4)
	end, { NoTween = true })
	local stroke = Kit.Stroke(button, "Accent", {
		Always = true,
		Deps = { "Accent", "Border" },
		Compute = function(T)
			return if window.Visible then T.Accent else T.Border
		end,
	})
	stroke.Thickness = 2
	Kit.Bind(stroke, "Thickness", { "BorderThickness" }, function()
		return 2
	end)
	self.Stroke = stroke

	local logo = Create("ImageLabel", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(0.55, 0.55),
		ScaleType = Enum.ScaleType.Fit,
		Parent = button,
	})
	local glyph = Kit.Label({
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = button,
	}, "Title", "Accent")
	Kit.Bind(logo, "Image", { "Logo" }, function(T)
		logo.Visible = T.Logo ~= ""
		glyph.Visible = T.Logo == ""
		return T.Logo
	end, { NoTween = true })
	Kit.Bind(glyph, "Text", { "Title" }, function(T)
		return string.upper(string.sub(T.Title, 1, 1))
	end, { NoTween = true })

	local scale = Create("UIScale", { Parent = button })
	self.Scale = scale

	self.Maid:Give(Input.Track(button, {
		Threshold = 10,
		Began = function()
			self._start = button.AbsolutePosition
			Animations.Tween(scale, { Scale = 0.92 }, 0.1)
		end,
		Moved = function(_, _, total)
			local pos = Device.ClampToScreen(self._start + total, button.AbsoluteSize, 4)
			button.Position = UDim2.fromOffset(pos.X, pos.Y)
		end,
		Ended = function(_, wasDrag)
			Animations.Tween(scale, { Scale = 1 }, 0.3, Enum.EasingStyle.Back)
			if wasDrag then
				self:_Snap(true)
			end
		end,
		Tap = function()
			Kit.Sound("Click")
			Animations.Bounce(scale, 0.85)
			window:Toggle()
		end,
	}))

	self.Maid:Give(window.Opened:Connect(function()
		Kit.Refresh(stroke)
	end))
	self.Maid:Give(window.Closed:Connect(function()
		Kit.Refresh(stroke)
	end))
	self.Maid:Give(State.DeviceChanged:Connect(function()
		self:_UpdateVisibility()
	end))
	self.Maid:Give(State.ViewportChanged:Connect(function()
		self:_Snap(false)
	end))
	self.Maid:Give(Theme:OnChanged({ "MobileButtonSize" }, function()
		task.defer(function()
			self:_Snap(false)
		end)
	end))

	Config:RegisterProvider("FloatingButton", function()
		return { Side = self.Side, Y = self.YScale }
	end, function(data)
		if type(data) == "table" then
			if data.Side == "Left" or data.Side == "Right" then
				self.Side = data.Side
			end
			if type(data.Y) == "number" then
				self.YScale = math.clamp(data.Y, 0, 1)
			end
			self:_Snap(false)
		end
	end)

	self:_UpdateVisibility()
	task.defer(function()
		self:_Snap(false)
	end)
	return self
end

function FloatingButton:IsEnabled(): boolean
	if self.Mode == true then
		return true
	elseif self.Mode == false then
		return false
	end
	return State.IsMobile
end

function FloatingButton:_UpdateVisibility()
	local enabled = self:IsEnabled()
	self.Button.Visible = enabled
	if enabled then
		self:_Snap(false)
	end
end

function FloatingButton:SetMode(mode: any)
	self.Mode = mode
	self:_UpdateVisibility()
end

-- Snaps to the nearest horizontal edge. `fromDrag` recalculates side/Y from the
-- current position, otherwise the stored side/Y are applied.
function FloatingButton:_Snap(fromDrag: boolean)
	local button = self.Button
	local size = Vector2.new(Theme.Values.MobileButtonSize, Theme.Values.MobileButtonSize)
	local vp = Utility.Viewport()
	local inset = Utility.GuiInset()
	local margin = 12
	if fromDrag then
		local center = button.AbsolutePosition + size / 2
		self.Side = if center.X < vp.X / 2 then "Left" else "Right"
		local usable = math.max(vp.Y - inset.Y - size.Y, 1)
		self.YScale = math.clamp((button.AbsolutePosition.Y - inset.Y) / usable, 0, 1)
	end
	local x = if self.Side == "Left" then margin else vp.X - size.X - margin
	local y = inset.Y + self.YScale * math.max(vp.Y - inset.Y - size.Y, 0)
	local target = Device.AvoidZones(Vector2.new(x, y), size)
	local udim = UDim2.fromOffset(target.X, target.Y)
	if fromDrag then
		Animations.Tween(button, { Position = udim }, 0.4, Enum.EasingStyle.Back)
	else
		button.Position = udim
	end
end

function FloatingButton:Destroy()
	self.Maid:Clean()
end

return FloatingButton
end

-- ==========================================================================
-- Mobile/QuickToggles
-- ==========================================================================
__modules["Mobile/QuickToggles"] = function()
--[[
	QuickToggles
	Every Toggle created with `Pinnable = true` can be pinned (pin icon, or long-press
	on touch) to the screen as a small floating button:
	  * Tap  -> toggles (accent glow when on, grey when off, bounce)
	  * Drag -> move (threshold separates tap from drag)
	  * Long-press -> menu: size S/M/L, transparency, unpin
	  * Global edit mode with grid snapping (QuickToggles.SetEditMode(true))
	State is synchronised with the menu toggle in both directions, positions/sizes/
	pins are stored in the config ("QuickToggles" provider).
]]

local Utility = Import("Utility")
local Theme = Import("Theme")
local Kit = Import("Kit")
local Animations = Import("Animations")
local Input = Import("Input")
local Maid = Import("Maid")
local Signal = Import("Signal")
local State = Import("State")
local Gui = Import("Gui")
local Config = Import("Config")
local Constants = Import("Constants")
local Device = Import("Mobile/Device")

local Create = Utility.Create

local QuickToggles = {}
QuickToggles.Registered = {} :: { [string]: any } -- key -> toggle
QuickToggles.Pins = {} :: { [string]: any } -- key -> pin object
QuickToggles.Saved = {} :: { [string]: any } -- key -> saved data (pending)
QuickToggles.EditMode = false
QuickToggles.GridSize = 12
QuickToggles.EditModeChanged = Signal.new()
QuickToggles.SizeScale = { S = 0.78, M = 1, L = 1.3 }

local providerRegistered = false
local hintShown = false

local function keyOf(toggle: any): string
	if toggle.Flag then
		return toggle.Flag
	end
	if not toggle._quickKey then
		toggle._quickKey = "Toggle_" .. tostring(toggle.Options.Title or "") .. "_" .. tostring(math.random(1, 1e6))
	end
	return toggle._quickKey
end

local function registerProvider()
	if providerRegistered then
		return
	end
	providerRegistered = true
	Config:RegisterProvider("QuickToggles", function()
		local data = {}
		for key, pin in QuickToggles.Pins do
			data[key] = table.clone(pin.Data)
		end
		-- keep pins of toggles that do not exist (yet)
		for key, saved in QuickToggles.Saved do
			if data[key] == nil and not QuickToggles.Registered[key] then
				data[key] = saved
			end
		end
		return data
	end, function(data)
		if type(data) ~= "table" then
			return
		end
		QuickToggles.Saved = {}
		for key, entry in data do
			if type(key) == "string" and type(entry) == "table" then
				QuickToggles.Saved[key] = entry
			end
		end
		for key, toggle in QuickToggles.Registered do
			local saved = QuickToggles.Saved[key]
			if saved then
				QuickToggles.SetPinned(toggle, true, saved)
			elseif QuickToggles.Pins[key] then
				QuickToggles.SetPinned(toggle, false)
			end
		end
	end)
end

------------------------------------------------------------------------------
-- Registration
------------------------------------------------------------------------------
function QuickToggles.Attach(toggle: any)
	registerProvider()
	local key = keyOf(toggle)
	QuickToggles.Registered[key] = toggle
	toggle.Maid:Give(function()
		if QuickToggles.Registered[key] == toggle then
			QuickToggles.Registered[key] = nil
		end
		local pin = QuickToggles.Pins[key]
		if pin and pin.Toggle == toggle then
			pin.Maid:Clean()
			QuickToggles.Pins[key] = nil
		end
	end)
	local saved = QuickToggles.Saved[key]
	if saved then
		QuickToggles.SetPinned(toggle, true, saved)
	end
end

function QuickToggles.IsPinned(toggle: any): boolean
	return QuickToggles.Pins[keyOf(toggle)] ~= nil
end

------------------------------------------------------------------------------
-- Pin object
------------------------------------------------------------------------------
local function pixelSize(data: any): number
	return math.floor(Theme.Values.QuickToggleSize * (QuickToggles.SizeScale[data.Size] or 1) + 0.5)
end

local function savePosition(pin: any)
	local vp = Utility.Viewport()
	local pos = pin.Button.AbsolutePosition
	pin.Data.X = math.clamp(pos.X / math.max(vp.X, 1), 0, 1)
	pin.Data.Y = math.clamp(pos.Y / math.max(vp.Y, 1), 0, 1)
	QuickToggles.Saved[pin.Key] = table.clone(pin.Data)
end

local function applyPosition(pin: any, animated: boolean?)
	local vp = Utility.Viewport()
	local s = pixelSize(pin.Data)
	local size = Vector2.new(s, s)
	local pos = Device.AvoidZones(Vector2.new(pin.Data.X * vp.X, pin.Data.Y * vp.Y), size)
	local udim = UDim2.fromOffset(pos.X, pos.Y)
	if animated then
		Animations.Tween(pin.Button, { Position = udim }, 0.3, Enum.EasingStyle.Back)
	else
		pin.Button.Position = udim
	end
end

local function defaultPosition(): { [string]: any }
	-- spread new pins along the upper middle area (away from thumbstick & jump)
	local count = Utility.Count(QuickToggles.Pins)
	return {
		X = 0.32 + (count % 6) * 0.07,
		Y = 0.2 + math.floor(count / 6) * 0.13,
		Size = "M",
		Transparency = 0,
	}
end

local function closeMenu()
	if QuickToggles._menu then
		QuickToggles._menu:Destroy()
		QuickToggles._menu = nil
	end
end

local function openMenu(pin: any)
	closeMenu()
	local layer = Gui.Layer("Popups")
	local root = Create("TextButton", {
		Name = "QuickToggleMenu",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 30,
		Parent = layer,
	})
	QuickToggles._menu = root
	root.MouseButton1Click:Connect(closeMenu)

	local card = Create("Frame", {
		Size = UDim2.fromOffset(210, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 31,
		Parent = root,
	})
	Kit.Panel(card, "Card", "Free")
	Kit.Corner(card, 1)
	Kit.Stroke(card, "Border", { Always = true })
	Kit.Padding(card, 10)
	Create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8), Parent = card })
	local scale = Create("UIScale", { Scale = 0.85, Parent = card })
	Animations.Tween(scale, { Scale = 1 }, 0.25, Enum.EasingStyle.Back)

	Kit.Label({
		Text = tostring(pin.Toggle.Options.Title or "Quick toggle"),
		Size = UDim2.new(1, 0, 0, 18),
		LayoutOrder = 1,
		ZIndex = 31,
		Parent = card,
	}, "Heading", "Text")

	local function row(order: number, title: string, options: { any }, current: any, apply: (any) -> ())
		Kit.Label({
			Text = title,
			Size = UDim2.new(1, 0, 0, 14),
			LayoutOrder = order,
			ZIndex = 31,
			Parent = card,
		}, "Tiny", "TextMuted")
		local holder = Create("Frame", {
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 34),
			LayoutOrder = order + 1,
			ZIndex = 31,
			Parent = card,
		})
		Create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
			Parent = holder,
		})
		for i, option in options do
			local selected = option.Value == current
			local b = Create("TextButton", {
				Size = UDim2.new(1 / #options, -6, 1, 0),
				LayoutOrder = i,
				ZIndex = 31,
				Parent = holder,
			})
			Kit.Corner(b, 0.6)
			Kit.Panel(b, if selected then "Accent" else "Surface", "Free")
			Kit.Label({
				Text = option.Text,
				Size = UDim2.fromScale(1, 1),
				TextXAlignment = Enum.TextXAlignment.Center,
				ZIndex = 31,
				Parent = b,
			}, "Small", if selected then "AccentText" else "Text")
			b.MouseButton1Click:Connect(function()
				apply(option.Value)
				openMenu(pin)
			end)
		end
	end

	row(2, "Size", {
		{ Text = "S", Value = "S" },
		{ Text = "M", Value = "M" },
		{ Text = "L", Value = "L" },
	}, pin.Data.Size, function(value)
		pin.Data.Size = value
		pin:Render()
		applyPosition(pin, true)
		savePosition(pin)
	end)
	row(4, "Transparency", {
		{ Text = "0%", Value = 0 },
		{ Text = "25%", Value = 0.25 },
		{ Text = "50%", Value = 0.5 },
		{ Text = "75%", Value = 0.75 },
	}, pin.Data.Transparency, function(value)
		pin.Data.Transparency = value
		pin:Render()
		savePosition(pin)
	end)

	local actions = Create("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 34),
		LayoutOrder = 6,
		ZIndex = 31,
		Parent = card,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 6),
		Parent = actions,
	})
	local function action(order: number, text: string, colorKey: string, fn: () -> ())
		local b = Create("TextButton", { Size = UDim2.new(0.5, -3, 1, 0), LayoutOrder = order, ZIndex = 31, Parent = actions })
		Kit.Corner(b, 0.6)
		Kit.Panel(b, colorKey, "Free")
		Kit.Label({
			Text = text,
			Size = UDim2.fromScale(1, 1),
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 31,
			Parent = b,
		}, "Small", if colorKey == "Surface" then "Text" else "AccentText")
		b.MouseButton1Click:Connect(function()
			closeMenu()
			fn()
		end)
	end
	action(1, "Edit layout", "Surface", function()
		QuickToggles.SetEditMode(true)
	end)
	action(2, Constants.Strings.Unpin, "Danger", function()
		QuickToggles.SetPinned(pin.Toggle, false)
	end)

	-- place the menu next to the button, on screen
	task.defer(function()
		local vp = Utility.Viewport()
		local bpos, bsize = pin.Button.AbsolutePosition, pin.Button.AbsoluteSize
		local csize = card.AbsoluteSize
		local x = bpos.X + bsize.X + 8
		if x + csize.X > vp.X - 8 then
			x = bpos.X - csize.X - 8
		end
		local y = math.clamp(bpos.Y, Utility.GuiInset().Y + 8, vp.Y - csize.Y - 8)
		card.Position = UDim2.fromOffset(math.max(x, 8), y)
	end)
end

local function createPin(toggle: any, key: string, data: any)
	local pin = { Toggle = toggle, Key = key, Data = data, Maid = Maid.new() }
	local button = Create("TextButton", {
		Name = "Quick_" .. key,
		Size = UDim2.fromOffset(52, 52),
		ZIndex = 4,
		Parent = Gui.Layer("Mobile"),
	})
	pin.Button = button
	pin.Maid:Give(button)
	local corner = Create("UICorner", { Parent = button })
	Kit.Bind(corner, "CornerRadius", { "MobileButtonShape", "CornerRadius" }, function(T)
		return if T.MobileButtonShape == "Round" then UDim.new(1, 0) else UDim.new(0, T.CornerRadius)
	end, { NoTween = true })
	Kit.Bind(button, "BackgroundColor3", { "QuickToggleOn", "QuickToggleOff" }, function(T)
		return if toggle.Value then T.QuickToggleOn else T.QuickToggleOff
	end)
	Kit.Bind(button, "BackgroundTransparency", { "QuickToggleOnTransparency", "QuickToggleOffTransparency", "MobileTransparency" }, function(T)
		local own = if toggle.Value then T.QuickToggleOnTransparency else T.QuickToggleOffTransparency
		return 1 - (1 - own) * (1 - T.MobileTransparency) * (1 - (pin.Data.Transparency or 0))
	end)
	local glow = Kit.Stroke(button, "Accent", {
		Always = true,
		Deps = { "Accent", "Border" },
		Compute = function(T)
			return if toggle.Value or QuickToggles.EditMode then T.Accent else T.Border
		end,
	})
	Kit.Bind(glow, "Thickness", { "BorderThickness" }, function()
		return if toggle.Value then 2.5 else 1
	end)
	Kit.Bind(glow, "Transparency", { "AccentTransparency" }, function()
		local base = if toggle.Value then 0.15 else 0.4
		return 1 - (1 - base) * (1 - (pin.Data.Transparency or 0))
	end)
	pin.Glow = glow

	local content = Create("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = button })
	Create("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 1),
		Parent = content,
	})
	local o = toggle.Options
	local icon = Kit.Icon(o.Icon or o.Title or "bolt", { Size = UDim2.fromScale(0.36, 0.36), LayoutOrder = 1, Parent = content }, "Text")
	local title = Kit.Label({
		Text = tostring(o.QuickTitle or o.Title or ""),
		Size = UDim2.new(0.92, 0, 0.24, 0),
		TextXAlignment = Enum.TextXAlignment.Center,
		TextScaled = true,
		LayoutOrder = 2,
		Parent = content,
	}, "Tiny", "Text")
	Create("UITextSizeConstraint", { MaxTextSize = 13, MinTextSize = 7, Parent = title })
	Kit.Bind(title, "TextColor3", { "AccentText", "Text" }, function(T)
		return if toggle.Value then T.AccentText else T.Text
	end)
	pin.Icon, pin.Title = icon, title
	local scale = Create("UIScale", { Parent = button })
	pin.Scale = scale

	function pin:Render(animated: boolean?)
		local s = pixelSize(self.Data)
		button.Size = UDim2.fromOffset(s, s)
		Kit.Refresh(button, nil, not animated)
		Kit.Refresh(glow, nil, not animated)
		Kit.Refresh(title)
		Kit.SetIconColor(icon, if toggle.Value then "AccentText" else "Text")
	end

	-- input: tap toggles, drag moves (grid snap in edit mode), long press = menu
	local startPos = Vector2.zero
	pin.Maid:Give(Input.Track(button, {
		Threshold = Constants.DragThreshold,
		LongPress = Constants.LongPressTime,
		Began = function()
			startPos = button.AbsolutePosition
			Animations.Tween(scale, { Scale = 0.92 }, 0.1)
		end,
		Moved = function(_, _, total)
			local s = button.AbsoluteSize
			local pos = Device.ClampToScreen(startPos + total, s, 4)
			if QuickToggles.EditMode then
				local g = QuickToggles.GridSize
				pos = Vector2.new(math.floor(pos.X / g + 0.5) * g, math.floor(pos.Y / g + 0.5) * g)
			end
			button.Position = UDim2.fromOffset(pos.X, pos.Y)
		end,
		Ended = function(_, wasDrag)
			Animations.Tween(scale, { Scale = 1 }, 0.3, Enum.EasingStyle.Back)
			if wasDrag then
				savePosition(pin)
				applyPosition(pin, true)
				savePosition(pin)
			end
		end,
		Tap = function()
			if QuickToggles.EditMode or toggle.Disabled then
				Animations.Bounce(scale, 0.9)
				return
			end
			Kit.Sound("Toggle")
			toggle:Toggle()
			Animations.Bounce(scale, 0.8)
		end,
		LongPressed = function()
			Animations.Bounce(scale, 1.1)
			openMenu(pin)
		end,
	}))

	pin.Maid:Give(toggle.Changed:Connect(function()
		pin:Render(true)
	end))
	pin.Maid:Give(Theme:OnChanged({ "QuickToggleSize" }, function()
		pin:Render()
		applyPosition(pin, false)
	end))
	pin.Maid:Give(State.ViewportChanged:Connect(function()
		applyPosition(pin, false)
	end))
	pin.Maid:Give(QuickToggles.EditModeChanged:Connect(function()
		pin:Render(true)
	end))

	pin:Render()
	applyPosition(pin, false)
	scale.Scale = 0
	Animations.Tween(scale, { Scale = 1 }, 0.4, Enum.EasingStyle.Back)
	return pin
end

function QuickToggles.SetPinned(toggle: any, pinned: boolean, data: any?)
	local key = keyOf(toggle)
	local existing = QuickToggles.Pins[key]
	if pinned then
		local d = data or QuickToggles.Saved[key] or defaultPosition()
		local clean = {
			X = math.clamp(tonumber(d.X) or 0.4, 0, 1),
			Y = math.clamp(tonumber(d.Y) or 0.25, 0, 1),
			Size = if QuickToggles.SizeScale[d.Size] then d.Size else "M",
			Transparency = math.clamp(tonumber(d.Transparency) or 0, 0, 0.9),
		}
		if existing then
			existing.Data = clean
			existing:Render(true)
			applyPosition(existing, true)
		else
			QuickToggles.Pins[key] = createPin(toggle, key, clean)
			if not hintShown and not data then
				hintShown = true
				Import("Components/Notifications").Notify({
					Title = "Pinned to screen",
					Content = "Tap to toggle, drag to move, long-press for size, transparency and unpin.",
					Type = "Info",
					Duration = 4,
				})
			end
		end
		QuickToggles.Saved[key] = table.clone(clean)
	else
		if existing then
			local button = existing.Button
			local tween = Animations.Tween(existing.Scale, { Scale = 0 }, 0.2, Enum.EasingStyle.Back, Enum.EasingDirection.In)
			if tween then
				tween.Completed:Once(function()
					existing.Maid:Clean()
				end)
			else
				existing.Maid:Clean()
			end
			local _ = button
		end
		QuickToggles.Pins[key] = nil
		QuickToggles.Saved[key] = nil
	end
	if toggle._PinChanged then
		toggle:_PinChanged(pinned)
	end
end

------------------------------------------------------------------------------
-- Edit mode (grid overlay + done button)
------------------------------------------------------------------------------
function QuickToggles.SetEditMode(enabled: boolean)
	if QuickToggles.EditMode == enabled then
		return
	end
	QuickToggles.EditMode = enabled
	closeMenu()
	if QuickToggles._overlay then
		QuickToggles._overlay:Destroy()
		QuickToggles._overlay = nil
	end
	if enabled then
		local layer = Gui.Layer("Mobile")
		local overlay = Create("Frame", {
			Name = "EditGrid",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = 1,
			Parent = layer,
		})
		QuickToggles._overlay = overlay
		local vp = Utility.Viewport()
		local step = QuickToggles.GridSize * 4
		for x = 0, vp.X, step do
			local line = Create("Frame", { Position = UDim2.fromOffset(x, 0), Size = UDim2.new(0, 1, 1, 0), Parent = overlay })
			Kit.Bind(line, "BackgroundColor3", "Accent")
			line.BackgroundTransparency = 0.9
		end
		for y = 0, vp.Y, step do
			local line = Create("Frame", { Position = UDim2.fromOffset(0, y), Size = UDim2.new(1, 0, 0, 1), Parent = overlay })
			Kit.Bind(line, "BackgroundColor3", "Accent")
			line.BackgroundTransparency = 0.9
		end
		local done = Create("TextButton", {
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, Utility.GuiInset().Y + 10),
			Size = UDim2.fromOffset(170, 44),
			ZIndex = 6,
			Parent = overlay,
		})
		Kit.AccentFill(done, "Button")
		Kit.Corner(done, "pill")
		Kit.Label({
			Text = Constants.Strings.Done .. "  ✓",
			Size = UDim2.fromScale(1, 1),
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 6,
			Parent = done,
		}, "Heading", "AccentText")
		done.MouseButton1Click:Connect(function()
			QuickToggles.SetEditMode(false)
		end)
	end
	QuickToggles.EditModeChanged:Fire(enabled)
end

function QuickToggles.UnpinAll()
	for _, pin in table.clone(QuickToggles.Pins) do
		QuickToggles.SetPinned(pin.Toggle, false)
	end
end

function QuickToggles.Destroy()
	closeMenu()
	QuickToggles.SetEditMode(false)
	for _, pin in QuickToggles.Pins do
		pin.Maid:Clean()
	end
	table.clear(QuickToggles.Pins)
end

return QuickToggles
end

-- ==========================================================================
-- Signal
-- ==========================================================================
__modules["Signal"] = function()
--[[
	Signal
	Minimal synchronous event implementation. Handlers run in order inside xpcall so
	a failing handler never breaks the others.
]]

type Handler = (...any) -> ()

local Signal = {}
Signal.__index = Signal

function Signal.new()
	return setmetatable({ _handlers = {} :: { any } }, Signal)
end

function Signal:Connect(fn: Handler)
	local handler = { Fn = fn, Connected = true }
	table.insert(self._handlers, handler)
	local signal = self
	local connection = { Connected = true }
	function connection.Disconnect()
		if not handler.Connected then
			return
		end
		handler.Connected = false
		connection.Connected = false
		local index = table.find(signal._handlers, handler)
		if index then
			table.remove(signal._handlers, index)
		end
	end
	connection.Destroy = connection.Disconnect
	return connection
end

function Signal:Once(fn: Handler)
	local connection
	connection = self:Connect(function(...)
		connection.Disconnect()
		fn(...)
	end)
	return connection
end

function Signal:Fire(...)
	for _, handler in table.clone(self._handlers) do
		if handler.Connected then
			local ok, err = xpcall(handler.Fn, debug.traceback, ...)
			if not ok then
				warn("[NovaUI] signal handler error: " .. tostring(err))
			end
		end
	end
end

function Signal:Wait()
	local thread = coroutine.running()
	self:Once(function(...)
		task.spawn(thread, ...)
	end)
	return coroutine.yield()
end

function Signal:Destroy()
	for _, handler in self._handlers do
		handler.Connected = false
	end
	table.clear(self._handlers)
end

return Signal
end

-- ==========================================================================
-- State
-- ==========================================================================
__modules["State"] = function()
--[[
	State
	Shared runtime state of one library instance (there is only one per execution).
	Holds the ScreenGui, its layers and global lifecycle objects.
]]

local Maid = Import("Maid")
local Signal = Import("Signal")

local State = {
	Library = nil :: any,
	Gui = nil :: ScreenGui?,
	Layers = {} :: { [string]: Frame },
	Maid = Maid.new(),
	Windows = {} :: { any },
	MainWindow = nil :: any,
	Destroyed = false,

	-- Touch-first layout (set by Mobile/Device)
	IsMobile = false,
	DeviceChanged = Signal.new(),

	-- Fired when the ScreenGui viewport changes size
	ViewportChanged = Signal.new(),

	-- Loader gate: windows wait until the loader finished before popping in
	LoaderActive = false,
	LoaderFinished = Signal.new(),
}

return State
end

-- ==========================================================================
-- Tabs/AppearanceTab
-- ==========================================================================
__modules["Tabs/AppearanceTab"] = function()
--[[
	Appearance tab - Win:AddThemeTab({ Title = "Appearance", Icon = "palette" })

	Generated from Theme.Schema, so every theme key is editable without extra code:
	  Color   -> ColorPicker (with transparency)    Number -> Slider
	  Boolean -> Toggle                             Enum   -> Dropdown
	  Font    -> Dropdown (font families)           String/Asset -> Textbox
	Root page: presets, live preview, share (export/import), saved themes, global reset.
	Sidebar categories group the schema categories; every section has a reset button.
	Controls stay in sync when the theme changes from anywhere (presets, configs...).
]]

local Theme = Import("Theme")
local Utility = Import("Utility")
local Config = Import("Config")
local Constants = Import("Constants")
local Notifications = Import("Components/Notifications")

local AppearanceTab = {}

local GROUPS = {
	{ Title = "Style", Icon = "palette", Categories = { "Colors", "Gradients", "Background", "Transparency" } },
	{ Title = "Interface", Icon = "layout", Categories = { "Fonts", "Shape", "Layout", "Animations" } },
	{ Title = "Extras", Icon = "sparkles", Categories = { "Branding", "Elements", "Mobile" } },
}

local CATEGORY_ICON = {
	Colors = "droplet",
	Gradients = "gradient",
	Background = "image",
	Transparency = "transparency",
	Fonts = "font",
	Shape = "shape",
	Layout = "layout",
	Animations = "animation",
	Branding = "brand",
	Elements = "elements",
	Mobile = "mobile",
}

local function sectionsOf(category: string): ({ string }, { [string]: { any } })
	local order, map = {}, {}
	for _, entry in Theme.Schema do
		if entry.Category == category and not entry.Hidden then
			if not map[entry.Section] then
				map[entry.Section] = {}
				table.insert(order, entry.Section)
			end
			table.insert(map[entry.Section], entry)
		end
	end
	return order, map
end

-- Creates the control for one schema entry. Returns a sync function(values).
local function control(section: any, entry: any): ((any) -> ())?
	local key = entry.Key
	local T = Theme.Values
	if entry.Type == "Color" then
		local picker = section:AddColorPicker({
			Title = entry.Label,
			Default = T[key],
			Transparency = T[key .. "Transparency"] or 0,
			IgnoreConfig = true,
			Callback = function(color, transparency)
				Theme:SetMany({ [key] = color, [key .. "Transparency"] = transparency })
			end,
		})
		return function(values)
			picker:SetSilent(values[key], values[key .. "Transparency"])
		end
	elseif entry.Type == "Number" then
		local slider = section:AddSlider({
			Title = entry.Label,
			Min = entry.Min or 0,
			Max = entry.Max or 1,
			Increment = entry.Step or 0.01,
			Suffix = entry.Suffix,
			Default = T[key],
			IgnoreConfig = true,
			Callback = function(value)
				Theme:Set(key, value)
			end,
		})
		return function(values)
			slider:Set(values[key], true)
		end
	elseif entry.Type == "Boolean" then
		local toggle = section:AddToggle({
			Title = entry.Label,
			Default = T[key],
			IgnoreConfig = true,
			Callback = function(value)
				Theme:Set(key, value)
			end,
		})
		return function(values)
			toggle:Set(values[key], true)
		end
	elseif entry.Type == "Enum" or entry.Type == "Font" then
		local list = if entry.Type == "Font" then table.clone(Theme.FontFamilies) else entry.Options
		if entry.Type == "Font" and not table.find(list, T[key]) then
			table.insert(list, T[key])
		end
		local dropdown = section:AddDropdown({
			Title = entry.Label,
			Values = list,
			Default = T[key],
			IgnoreConfig = true,
			Search = entry.Type == "Font",
			Callback = function(value)
				if value then
					Theme:Set(key, value)
				end
			end,
		})
		return function(values)
			dropdown:Set(values[key], true)
		end
	else
		local textbox = section:AddTextbox({
			Title = entry.Label,
			Default = T[key],
			Placeholder = if entry.Type == "Asset" then "rbxassetid://..." else "",
			IgnoreConfig = true,
			Callback = function(value)
				Theme:Set(key, value)
			end,
		})
		return function(values)
			textbox:Set(values[key], true)
		end
	end
end

function AppearanceTab.Build(window: any, options: { [string]: any })
	local strings = Constants.Strings
	local tab = window:AddTab({
		Title = options.Title or strings.AppearanceTab,
		Icon = options.Icon or "palette",
		Description = "Every color, font, size and animation - applied live and saved with your config.",
		Tags = { { Text = "Live", Color = "Success", Icon = "bolt" }, { Text = Theme.CurrentPreset, Color = "Accent" } },
		OverviewTitle = "Presets",
	})

	local syncers: { [string]: { (any) -> () } } = {}
	local function track(key: string, fn: ((any) -> ())?)
		if not fn then
			return
		end
		syncers[key] = syncers[key] or {}
		table.insert(syncers[key], fn)
	end

	-- root page --------------------------------------------------------------
	local presets = tab:AddSection({ Title = "Presets", Icon = "palette", Description = "One click themes. Layout and branding are kept.", Side = "Left" })
	for _, name in Theme.PresetOrder do
		presets:AddButton({
			Title = name,
			Icon = "droplet",
			Align = "Left",
			Callback = function()
				Theme:ApplyPreset(name)
				tab.RootPage:SetTags({ { Text = "Live", Color = "Success", Icon = "bolt" }, { Text = name, Color = "Accent" } })
				Notifications.Notify({ Title = "Theme", Content = "Applied preset '" .. name .. "'", Type = "Success", Duration = 2.5 })
			end,
		})
	end

	local preview = tab:AddSection({ Title = "Live preview", Icon = "eye", Side = "Right" })
	preview:AddStatusCard({ Title = "Status card", Subtitle = "Everything is up to date", Icon = "success", Status = "Success" })
	preview:AddButton({ Title = "Primary button", Style = "Primary", Size = "Large", Icon = "bolt", Callback = function()
		Notifications.Notify({ Title = "Preview", Content = "This is how notifications look.", Type = "Info" })
	end })
	preview:AddToggle({ Title = "Toggle", Description = "With description", Default = true, IgnoreConfig = true })
	preview:AddCheckbox({ Title = "Checkbox", Default = true, IgnoreConfig = true })
	preview:AddSlider({ Title = "Slider", Min = 0, Max = 100, Default = 64, Suffix = "%", IgnoreConfig = true })
	preview:AddButton({ Title = "Add item", Style = "Dashed" })

	local share = tab:AddSection({ Title = "Share theme", Icon = "link", Side = "Right" })
	share:AddButton({
		Title = "Export to clipboard",
		Icon = "copy",
		Callback = function()
			local text = Theme:Export()
			if Utility.SetClipboard(text) then
				Notifications.Notify({ Title = "Theme", Content = "Theme copied to clipboard.", Type = "Success" })
			else
				window:Dialog({ Title = "Theme export", Content = "Clipboard is not available - copy the text below.", Input = { Default = text } })
			end
		end,
	})
	local importBox = share:AddTextbox({ Title = "Import", Placeholder = "Paste theme string...", IgnoreConfig = true })
	share:AddButton({
		Title = "Import theme",
		Icon = "download",
		Callback = function()
			local ok, err = Theme:Import(importBox:Get())
			Notifications.Notify({
				Title = "Theme",
				Content = if ok then "Theme imported." else "Import failed: " .. tostring(err),
				Type = if ok then "Success" else "Error",
			})
		end,
	})

	local saved = tab:AddSection({ Title = "Saved themes", Icon = "folder", Side = "Left" })
	local themeList = saved:AddDropdown({ Title = "Theme", Values = Config:ListThemes(), AllowNone = true, IgnoreConfig = true })
	local themeName = saved:AddTextbox({ Title = "Name", Placeholder = "my theme", IgnoreConfig = true })
	saved:AddButton({
		Title = "Save theme",
		Style = "Primary",
		Icon = "save",
		Callback = function()
			local name = themeName:Get()
			if name == "" then
				name = themeList:Get() or ""
			end
			if name == "" then
				Notifications.Notify({ Title = "Theme", Content = "Enter a name first.", Type = "Warning" })
				return
			end
			Config:SaveTheme(name)
			themeList:Refresh(Config:ListThemes(), true)
			themeList:Set(Utility.SanitizeFileName(name), true)
			Notifications.Notify({ Title = "Theme", Content = "Saved theme '" .. name .. "'", Type = "Success" })
		end,
	})
	saved:AddButton({
		Title = "Load theme",
		Icon = "upload",
		Callback = function()
			local name = themeList:Get()
			if name and Config:LoadTheme(name) then
				Notifications.Notify({ Title = "Theme", Content = "Loaded theme '" .. name .. "'", Type = "Success" })
			end
		end,
	})
	saved:AddButton({
		Title = "Delete theme",
		Style = "Danger",
		Icon = "trash",
		Callback = function()
			local name = themeList:Get()
			if name and window:Confirm("Delete theme?", "'" .. name .. "' will be removed.", "Delete", "Danger") then
				Config:DeleteTheme(name)
				themeList:Refresh(Config:ListThemes(), false)
			end
		end,
	})

	local reset = tab:AddSection({ Title = "Reset", Icon = "refresh", Side = "Right" })
	reset:AddButton({
		Title = strings.ResetAll,
		Style = "Danger",
		Icon = "refresh",
		Callback = function()
			if window:Confirm(strings.ResetAll .. "?", "All appearance settings return to their defaults.", "Reset", "Danger") then
				Theme:Reset()
				Notifications.Notify({ Title = "Theme", Content = "Theme reset to defaults.", Type = "Success" })
			end
		end,
	})

	-- generated category pages ---------------------------------------------------
	for _, group in GROUPS do
		local category = tab:AddCategory({ Title = group.Title, Icon = group.Icon })
		for _, categoryName in group.Categories do
			local order, map = sectionsOf(categoryName)
			if #order > 0 then
				local page = category:AddPage({
					Title = categoryName,
					Icon = CATEGORY_ICON[categoryName],
					Description = "Changes are applied instantly.",
				})
				for index, sectionName in order do
					local section = page:AddSection({
						Title = sectionName,
						Side = if #order == 1 then "Left" elseif index % 2 == 1 then "Left" else "Right",
					})
					local keys = {}
					for _, entry in map[sectionName] do
						track(entry.Key, control(section, entry))
						if entry.Type == "Color" then
							track(entry.Key .. "Transparency", syncers[entry.Key] and syncers[entry.Key][#syncers[entry.Key]])
							table.insert(keys, entry.Key .. "Transparency")
						end
						table.insert(keys, entry.Key)
					end
					section:AddButton({
						Title = strings.ResetSection,
						Icon = "refresh",
						Style = "Dashed",
						Callback = function()
							Theme:Reset(keys)
						end,
					})
				end
				if categoryName == "Fonts" then
					local sample = page:AddSection({ Title = "Sample", Side = "Right" })
					sample:AddLabel({ Text = "The quick brown fox jumps over the lazy dog", Role = "Title" })
					sample:AddLabel({ Text = "Body text - 0123456789", Role = "Body", Color = "TextMuted" })
					sample:AddLabel({ Text = "local mono = true -- code", Role = "Mono", Color = "Accent" })
				elseif categoryName == "Mobile" then
					local quick = page:AddSection({ Title = "Quick toggles", Side = "Right" })
					quick:AddButton({
						Title = strings.EditQuickToggles,
						Icon = "move",
						Callback = function()
							Import("Mobile/QuickToggles").SetEditMode(true)
						end,
					})
					quick:AddButton({
						Title = "Unpin all",
						Icon = "pin",
						Style = "Danger",
						Callback = function()
							Import("Mobile/QuickToggles").UnpinAll()
						end,
					})
				end
			end
		end
	end

	-- keep controls in sync with the theme ---------------------------------------
	local connection = Theme:OnChanged(nil, function(changed)
		local done = {}
		for key in changed do
			local list = syncers[key]
			if list then
				for _, fn in list do
					if not done[fn] then
						done[fn] = true
						pcall(fn, Theme.Values)
					end
				end
			end
		end
	end)
	tab.Maid:Give(connection)
	return tab
end

return AppearanceTab
end

-- ==========================================================================
-- Tabs/ConfigTab
-- ==========================================================================
__modules["Tabs/ConfigTab"] = function()
--[[
	Config tab - Win:AddConfigTab({ Title = "Settings", Icon = "settings" })
	  * config list, name field, save / save as / load / overwrite (confirm) /
	    delete (confirm) / rename / duplicate / refresh
	  * autoload marker + last saved timestamp
	  * export / import (clipboard) + auto-save + save on close
	  * interface: toggle keybind, device mode override, quick toggle edit mode, unload
]]

local Config = Import("Config")
local Utility = Import("Utility")
local Theme = Import("Theme")
local State = Import("State")
local Constants = Import("Constants")
local Notifications = Import("Components/Notifications")

local ConfigTab = {}

local function notify(content: string, kind: string?)
	Notifications.Notify({ Title = "Config", Content = content, Type = kind or "Success", Duration = 3 })
end

local function formatTime(timestamp: number?): string
	if not timestamp then
		return "never"
	end
	local ok, text = pcall(os.date, "%d.%m.%Y %H:%M:%S", timestamp)
	return if ok then tostring(text) else tostring(timestamp)
end

function ConfigTab.Build(window: any, options: { [string]: any })
	Config:Init()
	local tab = window:AddTab({
		Title = options.Title or Constants.Strings.ConfigTab,
		Icon = options.Icon or "settings",
		Description = "Save, load and share your settings. Configs are stored per game.",
		Tags = {
			{ Text = if Config.FS.Available then "File storage" else "Session only", Color = if Config.FS.Available then "Success" else "Warning", Icon = "save" },
			{ Text = Config.GameKey, Color = "Accent" },
		},
	})

	-- configs ----------------------------------------------------------------
	local configs = tab:AddSection({ Title = "Configs", Icon = "folder", Side = "Left" })
	local list = configs:AddDropdown({ Title = "Config", Values = Config:List(), AllowNone = true, IgnoreConfig = true, Search = true })
	local nameBox = configs:AddTextbox({ Title = "Name", Placeholder = "config name", IgnoreConfig = true })
	local autoloadLabel = configs:AddStatusCard({ Title = "Autoload", Subtitle = "none", Icon = "bolt", Status = "TextMuted" })
	local savedLabel = configs:AddLabel({ Text = "Last saved: never", Role = "Small", Color = "TextMuted" })

	local function selected(): string?
		local name = list:Get()
		return if name and name ~= "" then name else nil
	end
	local function typed(): string?
		local name = Utility.SanitizeFileName(nameBox:Get() or "")
		return if name ~= "" then name else nil
	end
	local function refresh()
		local current = selected()
		list:Refresh(Config:List(), true)
		if current and Config:Exists(current) then
			list:Set(current, true)
		end
		local auto = Config:GetAutoload()
		autoloadLabel:SetStatus(if auto then auto else "none", if auto then "Success" else "TextMuted")
		savedLabel:Set("Last saved: " .. formatTime(Config.LastSaved) .. (if Config.Current then "  (" .. Config.Current .. ")" else ""))
	end
	tab.Maid:Give(Config.Changed:Connect(function()
		task.defer(refresh)
	end))
	refresh()

	configs:AddButton({
		Title = "Save",
		Style = "Primary",
		Icon = "save",
		Tooltip = "Saves to the selected config (or the typed name)",
		Callback = function()
			local name = selected() or typed() or Config.Current or "default"
			if Config:Save(name) then
				list:Set(name, true)
				notify("Saved '" .. name .. "'")
			end
		end,
	})
	configs:AddButton({
		Title = "Save as new",
		Icon = "plus",
		Style = "Dashed",
		Callback = function()
			local name = typed()
			if not name then
				name = window:Prompt("Save as", "Name of the new config", "config name")
				name = if name then Utility.SanitizeFileName(name) else nil
			end
			if not name or name == "" then
				return
			end
			if Config:Exists(name) and not window:Confirm("Overwrite '" .. name .. "'?", "A config with this name already exists.", "Overwrite", "Danger") then
				return
			end
			Config:Save(name)
			refresh()
			list:Set(name, true)
			notify("Saved '" .. name .. "'")
		end,
	})
	configs:AddButton({
		Title = "Load",
		Icon = "upload",
		Callback = function()
			local name = selected()
			if not name then
				notify("Select a config first.", "Warning")
				return
			end
			if Config:Load(name) then
				notify("Loaded '" .. name .. "'")
			end
		end,
	})
	configs:AddButton({
		Title = "Overwrite",
		Icon = "save",
		Callback = function()
			local name = selected()
			if not name then
				notify("Select a config first.", "Warning")
				return
			end
			if window:Confirm("Overwrite '" .. name .. "'?", "The saved values will be replaced by the current ones.", "Overwrite", "Danger") then
				Config:Save(name)
				notify("Overwrote '" .. name .. "'")
			end
		end,
	})
	configs:AddButton({
		Title = "Rename",
		Icon = "edit",
		Callback = function()
			local name = selected()
			if not name then
				notify("Select a config first.", "Warning")
				return
			end
			local newName = typed() or window:Prompt("Rename", "New name for '" .. name .. "'", "new name", name)
			if not newName or newName == "" then
				return
			end
			local ok, err = Config:Rename(name, newName)
			if ok then
				refresh()
				list:Set(Utility.SanitizeFileName(newName), true)
				notify("Renamed to '" .. newName .. "'")
			else
				notify("Rename failed: " .. tostring(err), "Error")
			end
		end,
	})
	configs:AddButton({
		Title = "Duplicate",
		Icon = "copy",
		Callback = function()
			local name = selected()
			if not name then
				notify("Select a config first.", "Warning")
				return
			end
			local ok, newName = Config:Duplicate(name, typed())
			if ok then
				refresh()
				list:Set(newName, true)
				notify("Duplicated to '" .. tostring(newName) .. "'")
			end
		end,
	})
	configs:AddButton({
		Title = "Delete",
		Style = "Danger",
		Icon = "trash",
		Callback = function()
			local name = selected()
			if not name then
				notify("Select a config first.", "Warning")
				return
			end
			if window:Confirm("Delete '" .. name .. "'?", "This cannot be undone.", "Delete", "Danger") then
				Config:Delete(name)
				list:Set(nil, true)
				refresh()
				notify("Deleted '" .. name .. "'")
			end
		end,
	})
	configs:AddButton({ Title = "Refresh list", Icon = "refresh", Callback = refresh })

	-- autoload -----------------------------------------------------------------
	local auto = tab:AddSection({ Title = "Autoload", Icon = "bolt", Side = "Right", Description = "Loaded automatically after the loader." })
	auto:AddButton({
		Title = "Set selected as autoload",
		Icon = "check",
		Callback = function()
			local name = selected()
			if not name then
				notify("Select a config first.", "Warning")
				return
			end
			Config:SetAutoload(name)
			notify("'" .. name .. "' will be loaded automatically.")
		end,
	})
	auto:AddButton({
		Title = "Clear autoload",
		Icon = "close",
		Callback = function()
			Config:SetAutoload(nil)
			notify("Autoload cleared.")
		end,
	})
	auto:AddToggle({
		Title = "Auto-save",
		Description = "Saves the current config periodically",
		Default = Config.Settings.AutoSave,
		IgnoreConfig = true,
		Callback = function(value)
			Config:SetAutoSave(value)
		end,
	})
	auto:AddSlider({
		Title = "Interval",
		Min = 10,
		Max = 600,
		Increment = 10,
		Suffix = "s",
		Default = Config.Settings.AutoSaveInterval,
		IgnoreConfig = true,
		Callback = function(value)
			Config.Settings.AutoSaveInterval = value
			Config:SaveSettings()
		end,
	})
	auto:AddToggle({
		Title = "Save on close",
		Default = Config.Settings.SaveOnClose,
		IgnoreConfig = true,
		Callback = function(value)
			Config.Settings.SaveOnClose = value
			Config:SaveSettings()
		end,
	})

	-- share ----------------------------------------------------------------------
	local share = tab:AddSection({ Title = "Share", Icon = "link", Side = "Right" })
	share:AddButton({
		Title = "Export to clipboard",
		Icon = "copy",
		Tooltip = "Exports the selected config, or the current settings",
		Callback = function()
			local text = Config:Export(selected())
			if not text then
				notify("Export failed.", "Error")
				return
			end
			if Utility.SetClipboard(text) then
				notify("Config copied to clipboard.")
			else
				window:Dialog({ Title = "Config export", Content = "Clipboard is not available - copy the text below.", Input = { Default = text } })
			end
		end,
	})
	local importBox = share:AddTextbox({ Title = "Import", Placeholder = "Paste config string...", IgnoreConfig = true })
	share:AddButton({
		Title = "Import",
		Icon = "download",
		Callback = function()
			local ok, err = Config:Import(importBox:Get(), typed())
			if ok then
				refresh()
				notify("Config imported" .. (if typed() then " and saved as '" .. tostring(typed()) .. "'" else "") .. ".")
			else
				notify("Import failed: " .. tostring(err), "Error")
			end
		end,
	})

	-- interface ------------------------------------------------------------------
	local ui = tab:AddSection({ Title = "Interface", Icon = "settings", Side = "Left" })
	ui:AddKeybind({
		Title = "Toggle UI",
		Default = window.ToggleKey,
		ChangeableMode = false,
		IgnoreConfig = true,
		ChangedCallback = function(key)
			if key ~= "None" then
				window:SetToggleKey(key)
			end
		end,
	})
	ui:AddDropdown({
		Title = "Device mode",
		Description = "Auto detects touch devices",
		Values = { "Auto", "Mobile", "Desktop" },
		Default = Config.Settings.DeviceMode,
		IgnoreConfig = true,
		Callback = function(value)
			Import("Mobile/Device").SetMode(value)
		end,
	})
	ui:AddButton({
		Title = Constants.Strings.EditQuickToggles,
		Icon = "move",
		Callback = function()
			Import("Mobile/QuickToggles").SetEditMode(true)
		end,
	})
	ui:AddButton({
		Title = "Unload " .. Theme.Values.Title,
		Style = "Danger",
		Icon = "close",
		Callback = function()
			if window:Confirm("Unload?", "The interface and all quick toggles will be removed.", "Unload", "Danger") then
				local library = State.Library
				if library then
					library:Destroy()
				else
					window:Destroy()
				end
			end
		end,
	})
	return tab
end

return ConfigTab
end

-- ==========================================================================
-- Theme
-- ==========================================================================
__modules["Theme"] = function()
--[[
	Theme
	Single source of truth for every visual value of the library.

	* `Theme.Schema` describes every key (type, default, range, category, label).
	  The Appearance tab is generated from it, so adding a key here automatically
	  makes it editable in the menu.
	* Every colour key `X` automatically gets a companion `XTransparency` key.
	* Components never hardcode colours/sizes/fonts: they bind instance properties
	  to keys via `Theme:Bind(...)` (see ThemeRegistry) and read metrics through
	  `Theme:Metric(...)` / `Theme:TextSize(...)`.
]]

local Utility = Import("Utility")
local Signal = Import("Signal")
local Constants = Import("Constants")

type SchemaEntry = {
	Key: string,
	Type: string, -- "Color" | "Number" | "Boolean" | "Enum" | "Font" | "String" | "Asset"
	Default: any,
	Category: string,
	Section: string,
	Label: string,
	Min: number?,
	Max: number?,
	Step: number?,
	Suffix: string?,
	Options: { string }?,
	Hidden: boolean?,
	ColorOf: string?,
	Description: string?,
}

local Theme = {}

Theme.Schema = {} :: { SchemaEntry }
Theme.ByKey = {} :: { [string]: SchemaEntry }
Theme.Defaults = {} :: { [string]: any } -- schema defaults (+ developer overrides)
Theme.Values = {} :: { [string]: any } -- live values
Theme.Changed = Signal.new() -- (changedKeys: {[string]: true}, instant: boolean)
Theme.CurrentPreset = "Midnight"
Theme.TouchMode = false

-- Order of categories in the Appearance tab
Theme.Categories = {
	"Colors",
	"Gradients",
	"Background",
	"Fonts",
	"Shape",
	"Layout",
	"Transparency",
	"Animations",
	"Branding",
	"Elements",
	"Mobile",
}

-- Font families shipped with the Roblox client (rbxasset://fonts/families/<Name>.json)
Theme.FontFamilies = {
	"BuilderSans",
	"GothamSSm",
	"Montserrat",
	"Roboto",
	"RobotoCondensed",
	"Ubuntu",
	"SourceSansPro",
	"Nunito",
	"Oswald",
	"TitilliumWeb",
	"Michroma",
	"Jura",
	"Merriweather",
	"FredokaOne",
	"PressStart2P",
	"RobotoMono",
	"Inconsolata",
	"Arial",
}
Theme.FontWeights = { "Light", "Regular", "Medium", "SemiBold", "Bold", "ExtraBold" }
Theme.EasingStyles = { "Quint", "Quart", "Quad", "Cubic", "Sine", "Exponential", "Circular", "Back", "Linear" }

------------------------------------------------------------------------------
-- Schema definition
------------------------------------------------------------------------------
local function add(entry: SchemaEntry)
	table.insert(Theme.Schema, entry)
	Theme.ByKey[entry.Key] = entry
end

local function color(key: string, hex: string, category: string, section: string, label: string, transparency: number?)
	add({
		Key = key,
		Type = "Color",
		Default = Color3.fromHex(hex),
		Category = category,
		Section = section,
		Label = label,
	})
	add({
		Key = key .. "Transparency",
		Type = "Number",
		Default = transparency or 0,
		Min = 0,
		Max = 1,
		Step = 0.01,
		Category = category,
		Section = section,
		Label = label .. " transparency",
		Hidden = true, -- edited through the colour picker's alpha bar
		ColorOf = key,
	})
end

local function number(key, default, category, section, label, min, max, step, suffix)
	add({
		Key = key,
		Type = "Number",
		Default = default,
		Category = category,
		Section = section,
		Label = label,
		Min = min,
		Max = max,
		Step = step,
		Suffix = suffix,
	})
end

local function bool(key, default, category, section, label)
	add({ Key = key, Type = "Boolean", Default = default, Category = category, Section = section, Label = label })
end

local function enum(key, default, category, section, label, options)
	add({
		Key = key,
		Type = "Enum",
		Default = default,
		Category = category,
		Section = section,
		Label = label,
		Options = options,
	})
end

local function str(key, default, category, section, label, kind)
	add({ Key = key, Type = kind or "String", Default = default, Category = category, Section = section, Label = label })
end

