------------------------------------------------------------------------------
-- Validation
------------------------------------------------------------------------------

-- Returns the sanitised value or nil when the value is not valid for the key
function Theme:Validate(key: string, value: any): any
	local entry = Theme.ByKey[key]
	if not entry or value == nil then
		return nil
	end
	local kind = entry.Type
	if kind == "Color" then
		if typeof(value) == "Color3" then
			return value
		end
		return Utility.HexToColor(value)
	elseif kind == "Number" then
		local n = tonumber(value)
		if not n or n ~= n then
			return nil
		end
		if entry.Min and entry.Max then
			n = math.clamp(n, entry.Min, entry.Max)
		end
		return n
	elseif kind == "Boolean" then
		return if type(value) == "boolean" then value else nil
	elseif kind == "Enum" then
		if typeof(value) == "EnumItem" then
			value = value.Name
		end
		for _, option in entry.Options :: { string } do
			if option == value then
				return value
			end
		end
		return nil
	elseif kind == "Font" then
		if typeof(value) == "EnumItem" then
			return value.Name
		end
		return if type(value) == "string" and value ~= "" then value else nil
	elseif kind == "Asset" then
		if type(value) == "number" then
			return "rbxassetid://" .. tostring(value)
		end
		if type(value) == "string" then
			if string.match(value, "^%d+$") then
				return "rbxassetid://" .. value
			end
			return value
		end
		return nil
	else
		return if type(value) == "string" then value else nil
	end
end

------------------------------------------------------------------------------
-- Get / Set
------------------------------------------------------------------------------
function Theme:Get(key: string): any
	return Theme.Values[key]
end

-- Sets one key; every bound instance animates to the new value.
function Theme:Set(key: string, value: any, instant: boolean?): boolean
	local valid = Theme:Validate(key, value)
	if valid == nil then
		warn(string.format("[%s] invalid theme value for %s: %s", Constants.Name, tostring(key), tostring(value)))
		return false
	end
	if Theme.Values[key] == valid then
		return true
	end
	Theme.Values[key] = valid
	Theme.Changed:Fire({ [key] = true }, instant == true)
	return true
end

-- Sets several keys and refreshes bindings once.
function Theme:SetMany(values: { [string]: any }, instant: boolean?): { [string]: boolean }
	local changed = {}
	for key, value in values do
		local valid = Theme:Validate(key, value)
		if valid ~= nil and Theme.Values[key] ~= valid then
			Theme.Values[key] = valid
			changed[key] = true
		end
	end
	if next(changed) then
		Theme.Changed:Fire(changed, instant == true)
	end
	return changed
end

-- Re-applies bindings for keys without changing values (e.g. device switch)
function Theme:Touch(keys: { string })
	local set = {}
	for _, key in keys do
		set[key] = true
	end
	Theme.Changed:Fire(set, false)
end

-- Developer overrides: become the new defaults (used by "reset") and live values
function Theme:SetDefaults(values: { [string]: any })
	for key, value in values do
		local valid = Theme:Validate(key, value)
		if valid ~= nil then
			Theme.Defaults[key] = valid
		end
	end
	Theme:SetMany(values, true)
end

-- Resets given keys (or everything) to defaults
function Theme:Reset(keys: { string }?, instant: boolean?)
	local values = {}
	if keys then
		for _, key in keys do
			values[key] = Theme.Defaults[key]
		end
	else
		for key, value in Theme.Defaults do
			values[key] = value
		end
		Theme.CurrentPreset = "Midnight"
	end
	Theme:SetMany(values, instant)
end

-- Returns all keys of a category / section (schema order)
function Theme:GetKeys(category: string?, section: string?): { string }
	local keys = {}
	for _, entry in Theme.Schema do
		if (category == nil or entry.Category == category) and (section == nil or entry.Section == section) then
			table.insert(keys, entry.Key)
		end
	end
	return keys
end

------------------------------------------------------------------------------
-- Presets
------------------------------------------------------------------------------
function Theme:RegisterPreset(name: string, values: { [string]: any })
	Theme.Presets[name] = values
	if not table.find(Theme.PresetOrder, name) then
		table.insert(Theme.PresetOrder, name)
	end
end

function Theme:ApplyPreset(name: string, instant: boolean?): boolean
	local preset = Theme.Presets[name]
	if not preset then
		warn(string.format("[%s] unknown theme preset '%s'", Constants.Name, tostring(name)))
		return false
	end
	local values = {}
	for _, entry in Theme.Schema do
		if Theme.PresetCategories[entry.Category] then
			local value = preset[entry.Key]
			if value == nil then
				value = entry.Default
			end
			values[entry.Key] = value
		end
	end
	-- presets may also carry non-category keys (e.g. ShadowStrength)
	for key, value in preset do
		if values[key] == nil then
			values[key] = value
		end
	end
	Theme.CurrentPreset = name
	Theme:SetMany(values, instant)
	return true
end

------------------------------------------------------------------------------
-- Serialisation
------------------------------------------------------------------------------
local function encodeValue(entry: SchemaEntry, value: any): any
	if entry.Type == "Color" then
		return Utility.ColorToHex(value)
	end
	return value
end

function Theme:Serialize(): { [string]: any }
	local values = {}
	for _, entry in Theme.Schema do
		values[entry.Key] = encodeValue(entry, Theme.Values[entry.Key])
	end
	return { Version = Constants.ThemeVersion, Preset = Theme.CurrentPreset, Values = values }
end

-- Converts a serialised theme into validated values. Unknown keys are ignored,
-- invalid or missing keys fall back to the defaults.
function Theme:Deserialize(data: any): ({ [string]: any }?, string?)
	if type(data) ~= "table" then
		return nil, "theme data is not a table"
	end
	local source = if type(data.Values) == "table" then data.Values else data
	local values = {}
	for _, entry in Theme.Schema do
		local valid = Theme:Validate(entry.Key, source[entry.Key])
		values[entry.Key] = if valid ~= nil then valid else Theme.Defaults[entry.Key]
	end
	return values
end

function Theme:ApplySerialized(data: any, instant: boolean?): boolean
	local values, err = Theme:Deserialize(data)
	if not values then
		warn("[" .. Constants.Name .. "] " .. tostring(err))
		return false
	end
	if type(data) == "table" and type(data.Preset) == "string" then
		Theme.CurrentPreset = data.Preset
	end
	Theme:SetMany(values, instant)
	return true
end

function Theme:Export(): string
	return Utility.EncodeShare("THEME", Theme:Serialize()) or ""
end

function Theme:Import(text: string): (boolean, string?)
	local ok, data = Utility.DecodeShare("THEME", text)
	if not ok then
		return false, data
	end
	if Theme:ApplySerialized(data, false) then
		return true, nil
	end
	return false, "invalid theme"
end

------------------------------------------------------------------------------
-- Derived values used by components
------------------------------------------------------------------------------
Theme.SpacingPresets = {
	Compact = { Padding = 10, Gap = 6, Row = 34, Section = 10, Inner = 8 },
	Normal = { Padding = 14, Gap = 8, Row = 38, Section = 12, Inner = 10 },
	Large = { Padding = 18, Gap = 10, Row = 44, Section = 16, Inner = 12 },
}

-- Spacing metric ("Padding" | "Gap" | "Row" | "Section" | "Inner").
-- Rows are at least 44px on touch devices.
function Theme:Metric(name: string, values: { [string]: any }?): number
	local t = values or Theme.Values
	local preset = Theme.SpacingPresets[t.Spacing] or Theme.SpacingPresets.Normal
	local value = preset[name] or 0
	if name == "Row" and Theme.TouchMode then
		value = math.max(value, 44)
	end
	return value
end

Theme.TextRoles = {
	Display = { Size = 22, Font = "Title" },
	Title = { Size = 16, Font = "Title" },
	Heading = { Size = 14, Font = "Title" },
	Body = { Size = 14, Font = "Body" },
	Small = { Size = 12, Font = "Body" },
	Tiny = { Size = 10, Font = "Body" },
	Mono = { Size = 13, Font = "Mono" },
}

function Theme:TextSize(role: string, values: { [string]: any }?): number
	local t = values or Theme.Values
	local def = Theme.TextRoles[role] or Theme.TextRoles.Body
	return math.floor(def.Size * (t.TextScale or 1) + 0.5)
end

local fontCache: { [string]: Font } = {}
function Theme.ResolveFont(family: string, weightName: string?): Font
	local cacheKey = family .. "/" .. tostring(weightName)
	local cached = fontCache[cacheKey]
	if cached then
		return cached
	end
	local weight = Enum.FontWeight.Regular
	pcall(function()
		weight = (Enum.FontWeight :: any)[weightName or "Regular"]
	end)
	local font
	if string.find(family, "^rbxasset") then
		font = Font.new(family, weight)
	elseif table.find(Theme.FontFamilies, family) then
		font = Font.new("rbxasset://fonts/families/" .. family .. ".json", weight)
	else
		local ok, result = pcall(function()
			local fromEnum = Font.fromEnum((Enum.Font :: any)[family])
			return Font.new(fromEnum.Family, weight)
		end)
		font = if ok then result else Font.new("rbxasset://fonts/families/" .. family .. ".json", weight)
	end
	fontCache[cacheKey] = font
	return font
end

function Theme:FontFor(role: string, values: { [string]: any }?): Font
	local t = values or Theme.Values
	local def = Theme.TextRoles[role] or Theme.TextRoles.Body
	if def.Font == "Title" then
		return Theme.ResolveFont(t.FontTitle, t.TitleWeight)
	elseif def.Font == "Mono" then
		return Theme.ResolveFont(t.FontMono, "Regular")
	end
	return Theme.ResolveFont(t.FontBody, if role == "Small" or role == "Tiny" then "Regular" else t.BodyWeight)
end

-- Effective transparency of a colour key on a given layer:
--   "Window"  -> colour transparency x window transparency
--   "Panel"   -> colour x window x panel transparency
--   "Free"    -> colour transparency only (overlays, notifications)
function Theme:Alpha(colorKey: string, layer: string?, values: { [string]: any }?): number
	local t = values or Theme.Values
	local own = t[colorKey .. "Transparency"] or 0
	if layer == "Free" then
		return own
	end
	local window = t.WindowTransparency or 0
	local panel = if layer == "Panel" then (t.PanelTransparency or 0) else 0
	return 1 - (1 - own) * (1 - window) * (1 - panel)
end

-- Dependencies for Theme:Alpha bindings
function Theme.AlphaDeps(colorKey: string, layer: string?): { string }
	local deps = { colorKey, colorKey .. "Transparency" }
	if layer ~= "Free" then
		table.insert(deps, "WindowTransparency")
		if layer == "Panel" then
			table.insert(deps, "PanelTransparency")
		end
	end
	return deps
end

------------------------------------------------------------------------------
-- Bindings (delegated to ThemeRegistry)
------------------------------------------------------------------------------

-- Theme:Bind(inst, "BackgroundColor3", "Card")
-- Theme:Bind(inst, "Size", {"Spacing"}, function(T) return ... end)
function Theme:Bind(inst: Instance, property: string, deps: any, compute: ((any) -> any)?, options: any?): Instance
	return Import("ThemeRegistry").Bind(inst, property, deps, compute, options)
end

-- Calls fn(changedKeys, instant) when any of `keys` changes (nil = any key)
function Theme:OnChanged(keys: any, fn: (changed: { [string]: boolean }, instant: boolean) -> ())
	local list: { string }? = if type(keys) == "string" then { keys } else keys
	return Theme.Changed:Connect(function(changed, instant)
		if list == nil then
			fn(changed, instant)
			return
		end
		for _, key in list do
			if changed[key] then
				fn(changed, instant)
				return
			end
		end
	end)
end

return Theme
end

-- ==========================================================================
-- ThemeRegistry
-- ==========================================================================
__modules["ThemeRegistry"] = function()
--[[
	ThemeRegistry
	Remembers which instance property depends on which theme key(s).

	  Registry.Bind(frame, "BackgroundColor3", "Card")
	  Registry.Bind(frame, "BackgroundTransparency", {"Card", "WindowTransparency"}, function(T) ... end)

	When Theme:Set/SetMany fires `Theme.Changed`, only the entries depending on the
	changed keys are recomputed and tweened (via Animations, respecting the speed
	multiplier and the "animations off" switch). Compute functions may also read
	component state (hover/pressed...) - call Registry.Refresh(inst) after a state change.
]]

local Theme = Import("Theme")
local Animations = Import("Animations")

type Entry = {
	Deps: { string },
	Compute: (any) -> any,
	NoTween: boolean?,
	Duration: number?,
}

local Registry = {}

-- inst -> { [property] = Entry }   (weak keys: destroyed instances are collected)
local entriesByInstance: { [Instance]: { [string]: Entry } } = setmetatable({}, { __mode = "k" }) :: any
-- theme key -> set of instances
local instancesByKey: { [string]: { [Instance]: boolean } } = {}

local TWEENABLE = {
	number = true,
	Color3 = true,
	UDim = true,
	UDim2 = true,
	Vector2 = true,
	Rect = true,
}

local function apply(inst: Instance, property: string, entry: Entry, instant: boolean?)
	local ok, value = pcall(entry.Compute, Theme.Values)
	if not ok then
		warn("[NovaUI] theme binding error (" .. property .. "): " .. tostring(value))
		return
	end
	if value == nil then
		return
	end
	if instant or entry.NoTween or not TWEENABLE[typeof(value)] or not Animations.Enabled() then
		local current = (inst :: any)[property]
		if current ~= value then
			pcall(function()
				(inst :: any)[property] = value
			end)
		end
		return
	end
	Animations.Tween(inst, { [property] = value }, entry.Duration or 0.25)
end

function Registry.Bind(inst: Instance, property: string, deps: any, compute: ((any) -> any)?, options: any?): Instance
	local depList: { string } = if type(deps) == "string" then { deps } else deps
	local fn = compute
	if not fn then
		local key = depList[1]
		fn = function(T)
			return T[key]
		end
	end
	local entry: Entry = {
		Deps = depList,
		Compute = fn :: any,
		NoTween = options and options.NoTween,
		Duration = options and options.Duration,
	}
	local map = entriesByInstance[inst]
	if not map then
		map = {}
		entriesByInstance[inst] = map
	end
	map[property] = entry
	for _, key in depList do
		local set = instancesByKey[key]
		if not set then
			set = setmetatable({}, { __mode = "k" }) :: any
			instancesByKey[key] = set
		end
		set[inst] = true
	end
	apply(inst, property, entry, true)
	return inst
end

function Registry.Unbind(inst: Instance, property: string?)
	local map = entriesByInstance[inst]
	if not map then
		return
	end
	if property then
		map[property] = nil
	else
		entriesByInstance[inst] = nil
	end
end

-- Recomputes bindings of one instance (after a component state change)
function Registry.Refresh(inst: Instance, property: string?, instant: boolean?)
	local map = entriesByInstance[inst]
	if not map then
		return
	end
	if property then
		local entry = map[property]
		if entry then
			apply(inst, property, entry, instant)
		end
		return
	end
	for prop, entry in map do
		apply(inst, prop, entry, instant)
	end
end

function Registry.HandleChanged(changed: { [string]: boolean }, instant: boolean?)
	local done: { [Entry]: boolean } = {}
	for key in changed do
		local set = instancesByKey[key]
		if set then
			for inst in set do
				local map = entriesByInstance[inst]
				if map then
					for prop, entry in map do
						if not done[entry] then
							for _, dep in entry.Deps do
								if changed[dep] then
									done[entry] = true
									apply(inst, prop, entry, instant)
									break
								end
							end
						end
					end
				else
					set[inst] = nil
				end
			end
		end
	end
end

Theme.Changed:Connect(Registry.HandleChanged)

return Registry
end

-- ==========================================================================
-- Utility
-- ==========================================================================
__modules["Utility"] = function()
--[[
	Utility
	Theme-independent helpers: services, instance creation, colour/hex, Base64, JSON,
	clipboard, GUI parenting, line drawing and visibility watching.
	NOTE: this module never decides colours - every visual value comes from Theme.
]]

local Constants = Import("Constants")

local Utility = {}

------------------------------------------------------------------------------
-- Services (lazy, cloneref'd when the executor offers it)
------------------------------------------------------------------------------
local serviceCache: { [string]: Instance } = {}
local cloneRef = (typeof(cloneref) == "function" and cloneref) or function(x)
	return x
end

Utility.Services = setmetatable({}, {
	__index = function(_, name: string)
		local service = serviceCache[name]
		if not service then
			service = cloneRef(game:GetService(name))
			serviceCache[name] = service
		end
		return service
	end,
}) :: any

local Services = Utility.Services

------------------------------------------------------------------------------
-- Instances
------------------------------------------------------------------------------

-- Creates an instance. `props.Parent` is applied last. Array entries of `props`
-- are treated as children. GuiObjects get sane defaults (no border, no auto colour).
function Utility.Create(className: string, props: { [any]: any }?, children: { Instance }?): any
	local inst = Instance.new(className)
	if inst:IsA("GuiObject") then
		inst.BorderSizePixel = 0
	end
	if inst:IsA("GuiButton") then
		inst.AutoButtonColor = false
	end
	if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
		inst.Text = ""
		inst.RichText = false
	end
	local parent = nil
	if props then
		for key, value in props do
			if key == "Parent" then
				parent = value
			elseif type(key) == "number" then
				value.Parent = inst
			else
				inst[key] = value
			end
		end
	end
	if children then
		for _, child in children do
			child.Parent = inst
		end
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

function Utility.IsAlive(inst: Instance?): boolean
	return inst ~= nil and inst.Parent ~= nil
end

------------------------------------------------------------------------------
-- Math
------------------------------------------------------------------------------
function Utility.Round(value: number, increment: number?): number
	local inc = increment or 1
	if inc <= 0 then
		return value
	end
	return math.floor(value / inc + 0.5) * inc
end

function Utility.DecimalsOf(increment: number): number
	local text = tostring(increment)
	local dot = string.find(text, ".", 1, true)
	if not dot then
		return 0
	end
	return #text - dot
end

function Utility.FormatNumber(value: number, decimals: number): string
	if decimals <= 0 then
		return tostring(math.floor(value + 0.5))
	end
	return string.format("%." .. decimals .. "f", value)
end

function Utility.Lerp(a: number, b: number, alpha: number): number
	return a + (b - a) * alpha
end

------------------------------------------------------------------------------
-- Colour helpers (pure maths on theme supplied colours)
------------------------------------------------------------------------------
function Utility.Mix(a: Color3, b: Color3, alpha: number): Color3
	return a:Lerp(b, alpha)
end

function Utility.Luminance(color: Color3): number
	return 0.2126 * color.R + 0.7152 * color.G + 0.0722 * color.B
end

function Utility.ColorToHex(color: Color3): string
	local r = math.clamp(math.floor(color.R * 255 + 0.5), 0, 255)
	local g = math.clamp(math.floor(color.G * 255 + 0.5), 0, 255)
	local b = math.clamp(math.floor(color.B * 255 + 0.5), 0, 255)
	return string.format("#%02X%02X%02X", r, g, b)
end

function Utility.HexToColor(hex: any): Color3?
	if type(hex) ~= "string" then
		return nil
	end
	local clean = string.gsub(hex, "#", "")
	if #clean == 3 then
		clean = string.gsub(clean, ".", "%0%0")
	end
	if #clean ~= 6 or string.find(clean, "[^%x]") then
		return nil
	end
	local r = tonumber(string.sub(clean, 1, 2), 16)
	local g = tonumber(string.sub(clean, 3, 4), 16)
	local b = tonumber(string.sub(clean, 5, 6), 16)
	if not (r and g and b) then
		return nil
	end
	return Color3.fromRGB(r, g, b)
end

------------------------------------------------------------------------------
-- Tables
------------------------------------------------------------------------------
function Utility.DeepCopy(value: any): any
	if type(value) ~= "table" then
		return value
	end
	local copy = {}
	for k, v in value do
		copy[Utility.DeepCopy(k)] = Utility.DeepCopy(v)
	end
	return copy
end

-- Fills missing keys of `target` from `defaults` (non destructive)
function Utility.Defaults(target: { [any]: any }?, defaults: { [any]: any }): { [any]: any }
	local result = target or {}
	for k, v in defaults do
		if result[k] == nil then
			result[k] = v
		end
	end
	return result
end

function Utility.Count(tbl: { [any]: any }): number
	local n = 0
	for _ in tbl do
		n += 1
	end
	return n
end

------------------------------------------------------------------------------
-- JSON / Base64
------------------------------------------------------------------------------
function Utility.JSONEncode(value: any): (boolean, string)
	local ok, result = pcall(function()
		return Services.HttpService:JSONEncode(value)
	end)
	return ok, result
end

function Utility.JSONDecode(text: string): (boolean, any)
	if type(text) ~= "string" or text == "" then
		return false, "empty input"
	end
	local ok, result = pcall(function()
		return Services.HttpService:JSONDecode(text)
	end)
	return ok, result
end

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64Lookup: { [string]: number } = {}
for i = 1, #B64 do
	B64Lookup[string.sub(B64, i, i)] = i - 1
end

function Utility.Base64Encode(data: string): string
	local out = table.create(math.ceil(#data / 3) * 4)
	for i = 1, #data, 3 do
		local a, b, c = string.byte(data, i, i + 2)
		local n = a * 65536 + (b or 0) * 256 + (c or 0)
		local c1 = bit32.extract(n, 18, 6)
		local c2 = bit32.extract(n, 12, 6)
		local c3 = bit32.extract(n, 6, 6)
		local c4 = bit32.extract(n, 0, 6)
		table.insert(out, string.sub(B64, c1 + 1, c1 + 1))
		table.insert(out, string.sub(B64, c2 + 1, c2 + 1))
		table.insert(out, if b then string.sub(B64, c3 + 1, c3 + 1) else "=")
		table.insert(out, if c then string.sub(B64, c4 + 1, c4 + 1) else "=")
	end
	return table.concat(out)
end

function Utility.Base64Decode(data: string): string?
	local clean = string.gsub(data, "[^%w%+/=]", "")
	if #clean % 4 ~= 0 then
		return nil
	end
	local out = {}
	for i = 1, #clean, 4 do
		local n, pad = 0, 0
		for j = 0, 3 do
			local ch = string.sub(clean, i + j, i + j)
			if ch == "=" then
				pad += 1
				n = n * 64
			else
				local v = B64Lookup[ch]
				if v == nil then
					return nil
				end
				n = n * 64 + v
			end
		end
		local b1 = bit32.extract(n, 16, 8)
		local b2 = bit32.extract(n, 8, 8)
		local b3 = bit32.extract(n, 0, 8)
		table.insert(out, string.char(b1))
		if pad < 2 then
			table.insert(out, string.char(b2))
		end
		if pad < 1 then
			table.insert(out, string.char(b3))
		end
	end
	return table.concat(out)
end

-- Encodes a table as "<PREFIX>:<base64(json)>" for clipboard sharing
function Utility.EncodeShare(prefix: string, value: any): string?
	local ok, json = Utility.JSONEncode(value)
	if not ok then
		return nil
	end
	return Constants.Id .. "-" .. prefix .. ":" .. Utility.Base64Encode(json)
end

-- Accepts the encoded share string, plain base64 or raw JSON
function Utility.DecodeShare(prefix: string, text: string): (boolean, any)
	if type(text) ~= "string" then
		return false, "no text"
	end
	local trimmed = string.match(text, "^%s*(.-)%s*$") or text
	local header = Constants.Id .. "-" .. prefix .. ":"
	if string.sub(trimmed, 1, #header) == header then
		trimmed = string.sub(trimmed, #header + 1)
	elseif string.find(trimmed, "^[%w%-]+%-[%u]+:") then
		return false, "wrong share type"
	end
	if string.sub(trimmed, 1, 1) ~= "{" then
		local decoded = Utility.Base64Decode(trimmed)
		if not decoded then
			return false, "invalid base64"
		end
		trimmed = decoded
	end
	local ok, data = Utility.JSONDecode(trimmed)
	if not ok or type(data) ~= "table" then
		return false, "invalid json"
	end
	return true, data
end

------------------------------------------------------------------------------
-- Executor helpers
------------------------------------------------------------------------------
function Utility.SetClipboard(text: string): boolean
	local fn = (typeof(setclipboard) == "function" and setclipboard)
		or (typeof(toclipboard) == "function" and toclipboard)
		or (typeof(set_clipboard) == "function" and set_clipboard)
	if not fn then
		return false
	end
	return (pcall(fn, text))
end

-- Runs a user callback safely in its own thread and reports errors without crashing
function Utility.SafeCallback(fn: any, ...: any)
	if type(fn) ~= "function" then
		return
	end
	local args = table.pack(...)
	task.spawn(function()
		local ok, err = xpcall(function()
			fn(table.unpack(args, 1, args.n))
		end, debug.traceback)
		if not ok then
			warn("[" .. Constants.Name .. "] callback error: " .. tostring(err))
		end
	end)
end

------------------------------------------------------------------------------
-- GUI parenting
------------------------------------------------------------------------------
function Utility.GetGuiParent(): Instance
	if typeof(gethui) == "function" then
		local ok, holder = pcall(gethui)
		if ok and typeof(holder) == "Instance" then
			return holder
		end
	end
	local ok = pcall(function()
		local probe = Instance.new("Folder")
		probe.Parent = Services.CoreGui
		probe:Destroy()
	end)
	if ok then
		return Services.CoreGui
	end
	local player = Services.Players.LocalPlayer
	return player:WaitForChild("PlayerGui")
end

-- Destroys an older instance of the library (re-execution)
function Utility.DestroyOld(name: string)
	local candidates = {}
	pcall(function()
		if typeof(gethui) == "function" then
			table.insert(candidates, gethui())
		end
	end)
	pcall(function()
		table.insert(candidates, Services.CoreGui)
	end)
	pcall(function()
		table.insert(candidates, Services.Players.LocalPlayer:FindFirstChildOfClass("PlayerGui"))
	end)
	for _, holder in candidates do
		pcall(function()
			for _, child in holder:GetChildren() do
				if child.Name == name and child:IsA("ScreenGui") then
					child:Destroy()
				end
			end
		end)
	end
end

function Utility.Viewport(): Vector2
	local camera = workspace.CurrentCamera
	return if camera then camera.ViewportSize else Vector2.new(1280, 720)
end

-- Top-left inset (InputObject positions are relative to the inset area)
function Utility.GuiInset(): Vector2
	local ok, topLeft = pcall(function()
		return (Services.GuiService:GetGuiInset())
	end)
	return if ok and typeof(topLeft) == "Vector2" then topLeft else Vector2.zero
end

-- Converts an InputObject position into absolute ScreenGui space (IgnoreGuiInset = true)
function Utility.InputToGui(position: Vector3 | Vector2): Vector2
	local inset = Utility.GuiInset()
	return Vector2.new(position.X + inset.X, position.Y + inset.Y)
end

------------------------------------------------------------------------------
-- Drawing
------------------------------------------------------------------------------

-- Positions a Frame so that it renders a line from `a` to `b` (local pixel coords)
function Utility.SetLine(line: Frame, a: Vector2, b: Vector2, thickness: number)
	local delta = b - a
	local length = delta.Magnitude
	line.AnchorPoint = Vector2.new(0.5, 0.5)
	line.Position = UDim2.fromOffset((a.X + b.X) / 2, (a.Y + b.Y) / 2)
	line.Size = UDim2.fromOffset(length, thickness)
	line.Rotation = math.deg(math.atan2(delta.Y, delta.X))
end

------------------------------------------------------------------------------
-- Visibility watching (used to pause per-frame work while hidden)
------------------------------------------------------------------------------

-- Calls `callback(isVisible)` whenever the effective visibility of `gui` changes.
-- Returns a cleanup function.
function Utility.WatchVisible(gui: GuiObject, callback: (boolean) -> ()): () -> ()
	local connections = {}
	local last: boolean? = nil

	local function compute(): boolean
		local current: Instance? = gui
		while current do
			if current:IsA("GuiObject") and not current.Visible then
				return false
			end
			if current:IsA("LayerCollector") then
				return (current :: any).Enabled
			end
			current = current.Parent
		end
		return false
	end

	local rebind
	local function update()
		local visible = compute()
		if visible ~= last then
			last = visible
			callback(visible)
		end
	end

	rebind = function()
		for _, c in connections do
			c:Disconnect()
		end
		table.clear(connections)
		local current: Instance? = gui
		while current do
			if current:IsA("GuiObject") then
				table.insert(connections, current:GetPropertyChangedSignal("Visible"):Connect(update))
			elseif current:IsA("LayerCollector") then
				table.insert(connections, current:GetPropertyChangedSignal("Enabled"):Connect(update))
			end
			table.insert(connections, current:GetPropertyChangedSignal("Parent"):Connect(function()
				task.defer(rebind)
			end))
			current = current.Parent
		end
		update()
	end

	rebind()
	return function()
		for _, c in connections do
			c:Disconnect()
		end
		table.clear(connections)
	end
end

function Utility.PlayerName(): (string, string, number)
	local player = Services.Players.LocalPlayer
	if not player then
		return "Player", "Player", 0
	end
	return player.DisplayName, player.Name, player.UserId
end

function Utility.GameKey(): string
	local name = "Game"
	pcall(function()
		local info = Services.MarketplaceService:GetProductInfo(game.PlaceId)
		if info and type(info.Name) == "string" then
			name = info.Name
		end
	end)
	name = string.gsub(name, "[^%w%s%-_]", "")
	name = string.gsub(name, "%s+", "_")
	name = string.sub(name, 1, 40)
	if name == "" then
		name = "Game"
	end
	return name .. "_" .. tostring(game.PlaceId)
end

function Utility.SanitizeFileName(name: string): string
	local clean = string.gsub(name or "", "[^%w%s%-_%.]", "")
	clean = string.match(clean, "^%s*(.-)%s*$") or ""
	return string.sub(clean, 1, 48)
end

return Utility
end

-- ==========================================================================
-- init
-- ==========================================================================
__modules["init"] = function()
--[[
	Nova UI - public library API

	  local UI = loadstring(game:HttpGet(".../dist/NovaUI.lua"))()
	  UI:CreateLoader({...})                        -- optional, yields until done
	  local Win = UI:CreateWindow({...})
	  local Tab = Win:AddTab({ Title = "Visuals", Icon = "eye" })
	  local Sec = Tab:AddSection("ESP")
	  Sec:AddToggle({ Title = "Box", Flag = "ESP_Box", Default = false, Pinnable = true, Callback = function(v) end })
	  Win:AddThemeTab()
	  Win:AddConfigTab()

	See README.md for the complete API.
]]

local Constants = Import("Constants")
local Utility = Import("Utility")
local State = Import("State")
local Theme = Import("Theme")
Import("ThemeRegistry") -- connects theme changes to bindings
local Gui = Import("Gui")
local Config = Import("Config")
local Icons = Import("Icons")
local Animations = Import("Animations")
local Notifications = Import("Components/Notifications")
local Window = Import("Components/Window")
local Device = Import("Mobile/Device")
local FloatingButton = Import("Mobile/FloatingButton")
local QuickToggles = Import("Mobile/QuickToggles")
local Loader = Import("Loader")
local ESPPreview = Import("ESPPreview")

local Library = {}
Library.__index = Library

Library.Name = Constants.Name
Library.Version = Constants.Version
Library.Constants = Constants
Library.Theme = Theme
Library.Config = Config
Library.Flags = Config.Flags
Library.Icons = Icons
Library.Animations = Animations
Library.QuickToggles = QuickToggles
Library.Utility = Utility
Library.Windows = State.Windows

------------------------------------------------------------------------------
-- Re-execution: destroy the previous instance completely (connections included)
------------------------------------------------------------------------------
local globalKey = Constants.Id .. "_Instance"
local env = (typeof(getgenv) == "function" and getgenv()) or shared
pcall(function()
	local previous = env[globalKey]
	if previous and type(previous.Destroy) == "function" then
		previous:Destroy()
	end
end)

local function setup()
	Gui.Ensure()
	Config:Init()
	Device.Init()
end

------------------------------------------------------------------------------
-- Loader
------------------------------------------------------------------------------
-- Shows the loader. Yields until finished unless options.Async = true.
-- Returns true when the loader (and the optional key system) was completed.
function Library:CreateLoader(options: { [string]: any }?): any
	setup()
	-- the loader is shown before the window exists: apply its theme (and the
	-- autoload config's theme) first so it already uses the final look
	local o = options or {}
	if type(o.Theme) == "string" then
		Theme:ApplyPreset(o.Theme, true)
	elseif type(o.Theme) == "table" then
		if type(o.Theme.Preset) == "string" then
			Theme:ApplyPreset(o.Theme.Preset, true)
		end
		local overrides = table.clone(o.Theme)
		overrides.Preset = nil
		Theme:SetDefaults(overrides)
	end
	pcall(function()
		local name = Config:GetAutoload()
		if name and o.Autoload ~= false then
			local text = Config.FS.Read(Config:Paths().Configs .. "/" .. name .. ".json")
			local ok, data = Utility.JSONDecode(text or "")
			if ok and type(data) == "table" and type(data.Theme) == "table" then
				Theme:ApplySerialized(data.Theme, true)
			end
		end
	end)
	local loader = Loader.new(options)
	if options and options.Async then
		task.spawn(loader.Run, loader)
		return loader
	end
	return loader:Run()
end

------------------------------------------------------------------------------
-- Window
------------------------------------------------------------------------------
function Library:CreateWindow(options: { [string]: any }?): any
	setup()
	local o = options or {}
	local window = Window.new(o)
	window.Library = self
	window.FloatingButton = FloatingButton.new(window, if o.FloatingButton == nil then "Auto" else o.FloatingButton)

	-- autoload: theme/window/mobile state apply now, element values are applied
	-- as soon as the elements with matching flags are created.
	if o.Autoload ~= false then
		Config:LoadAutoload()
	end
	if Config.Settings.AutoSave then
		Config:SetAutoSave(true)
	end

	task.spawn(function()
		if State.LoaderActive then
			State.LoaderFinished:Wait()
		end
		task.wait()
		if not window.Destroyed then
			window:SetVisible(true)
		end
	end)
	return window
end

------------------------------------------------------------------------------
-- Shortcuts
------------------------------------------------------------------------------
function Library:Notify(options: { [string]: any })
	setup()
	return Notifications.Notify(options)
end

function Library:GetFlag(flag: string): any
	return Config:GetFlag(flag)
end

function Library:SetFlag(flag: string, value: any)
	local element = Config.Flags[flag]
	if element then
		element:Set(value)
	end
end

-- Current ESP preview settings (see ESPPreview.lua for the table layout)
function Library:GetESPSettings(prefix: string?): { [string]: any }
	return ESPPreview.ReadSettings(prefix)
end

function Library:SetTheme(nameOrValues: any)
	if type(nameOrValues) == "string" then
		Theme:ApplyPreset(nameOrValues)
	elseif type(nameOrValues) == "table" then
		Theme:SetMany(nameOrValues)
	end
end

function Library:IsMobile(): boolean
	return State.IsMobile
end

-- "Auto" | "Mobile" | "Desktop"
function Library:SetDeviceMode(mode: string)
	Device.SetMode(mode)
end

function Library:RegisterIcon(name: string, asset: string | number)
	Icons.Register(name, asset)
end

------------------------------------------------------------------------------
-- Destroy: removes every instance, connection, blur and quick toggle
------------------------------------------------------------------------------
function Library:Destroy()
	if State.Destroyed then
		return
	end
	State.Destroyed = true
	pcall(function()
		Config:SaveOnClose()
	end)
	Config:Shutdown()
	pcall(QuickToggles.Destroy)
	for _, window in table.clone(State.Windows) do
		if window.FloatingButton then
			pcall(window.FloatingButton.Destroy, window.FloatingButton)
		end
		pcall(window.Destroy, window)
	end
	pcall(function()
		for _, child in Utility.Services.Lighting:GetChildren() do
			if child:IsA("BlurEffect") and string.sub(child.Name, 1, #Constants.Id) == Constants.Id then
				child:Destroy()
			end
		end
	end)
	State.Maid:Clean()
	State.Gui = nil
	pcall(function()
		if env[globalKey] == Library then
			env[globalKey] = nil
		end
	end)
end

State.Library = Library
pcall(function()
	env[globalKey] = Library
end)

return Library
end

return Import("init")
